#!/bin/zsh
# ============================================================================
# Kanban Board Helpers
# Terminal task tracking for AITeamForge installations
# ============================================================================
# This file is a template — {{ORG_NAME}}, {{ORG_SLUG}}, {{SHARED_DEV_ROOT}},
# etc. are substituted at install time by the AITeamForge installer.
# Do not edit the rendered copy directly.
# ============================================================================
# Usage: Source this file in your terminal session
#   source {{AITEAMFORGE_DIR}}/kanban-helpers.sh
#
# Then use the kb-* commands to update your task status
#
# Auto-generated by aiteamforge installer — do not edit directly.
# Source: aiteamforge homebrew-tap/share/templates/kanban/kanban-helpers.template.sh
# ============================================================================

# ─────────────────────────────────────────────────────────────────────────────
# AITeamForge Installation Root
# This variable is substituted by the installer (install-kanban.sh)
# ─────────────────────────────────────────────────────────────────────────────
AITEAMFORGE_DIR="${AITEAMFORGE_DIR:-}"

# Configuration
# Legacy centralized path (kept for reference, no longer used)
# KANBAN_DIR="${AITEAMFORGE_DIR}/kanban"

# ─────────────────────────────────────────────────────────────────────────────
# Load the canonical team-path config loader (XACA-0168).
# This provides aiteamforge_team_kanban_dir(), aiteamforge_team_lcars_port(), etc.
# The loader is guarded against double-sourcing so it is safe to call repeatedly.
# ─────────────────────────────────────────────────────────────────────────────
if [ -z "${_AITEAMFORGE_PATHS_LOADED:-}" ]; then
    _kb_loader_sourced=0
    for _kb_loader_candidate in \
        "${HOME}/dev-team/homebrew-tap/libexec/lib/aiteamforge-paths.sh" \
        "$(brew --prefix 2>/dev/null)/share/aiteamforge/libexec/lib/aiteamforge-paths.sh" \
        "${HOME}/.aiteamforge/lib/aiteamforge-paths.sh"; do
        if [ -f "$_kb_loader_candidate" ]; then
            # shellcheck source=/dev/null
            source "$_kb_loader_candidate"
            _kb_loader_sourced=1
            break
        fi
    done
    unset _kb_loader_candidate _kb_loader_sourced
fi

# Get the kanban directory for a specific team
# Each team has their own kanban/ directory in their repository.
#
# XACA-0649: Three-tier lookup — same logic as kanban-aliases.sh and the
# Python server — so shell and Python resolvers always agree.
#
# Strategy 1: team-paths.json registry (written by install-team.sh / kb-port-reconcile).
#   Read kanban_dir directly; only trust an entry that points to an existing dir
#   (mirrors the [ -d ] guard in kanban-helpers.sh).  Wrong-but-existing default
#   paths mean the install itself was broken — surface it, not hide it.
# Strategy 2: Well-known case arms for every built-in team template.
#   Parameterized teams (legal-*, medical-*, finance-*, freelance-*) derive the
#   path from the slug suffix, NOT from $AITEAMFORGE_DIR — so the early-exit
#   [[ -d "${_atf_dir}/kanban" ]] guard that existed here before XACA-0649 is
#   intentionally removed: that guard fired for ALL teams once the academy kanban
#   dir existed on disk (it always does on any consumer), silently routing
#   legal-coparenting et al. to the wrong directory.
# Strategy 3: $AITEAMFORGE_DIR/kanban — catch-all for genuinely unknown teams only.
#
# SIBLING-DRIFT NOTE (XACA-0649): This function has three copies:
#   1. kanban-helpers.template.sh (this file — deployed on upgrade by aiteamforge-upgrade.sh)
#   2. kanban-aliases.sh           (deployed on fresh install by install-kanban.sh)
#   3. kanban-helpers.sh           (dev source of truth — dev-tree only, not deployed)
# When changing this function UPDATE ALL THREE and run
#   homebrew-tap/tests/test-xaca-0649-kanban-dir-resolver.sh
# to verify parity.
# ─────────────────────────────────────────────────────────────────────────────
# Board-less alias marker (XACA-0794 / XACA-0794-013)
# ─────────────────────────────────────────────────────────────────────────────
#
# A board-less team owns NO kanban board but keeps its other identities (LCARS
# port, team_code, crew launcher, personas). "mainevent" is the only one today: a
# coordination/port identity (LCARS 8400, team_code MEV) whose operative kanban
# identity is "command".
#
# WHY THIS EXISTS (XACA-0794-013): this resolver never had a board-less guard --
# not even XACA-0727's, which only ever landed on the dev-tree copy. So on a
# CONSUMER box a kb-* call for 'mainevent' read kanban_dir=null from the registry,
# failed Strategy 1's [[ -d ]] test, matched no case arm, and fell through to the
# Strategy-3 catch-all -- silently resolving to ACADEMY's board and operating on
# the wrong team's data. Erroring clearly beats corrupting a bystander.
#
# Contract: echo the alias target and return 0 when $1 is board-less; return 1
# otherwise. Mirrors board_less_alias_of() in kanban-hooks/aiteamforge_paths.py --
# EXPLICIT OVERLAY MARKER FIRST, built-in fallback second.
_kb_board_less_builtin_alias_of() {
    case "${1-}" in
        mainevent) echo "command"; return 0 ;;
    esac
    return 1
}

_kb_board_less_alias_of() {
    local team="${1-}"
    [[ -z "$team" ]] && return 1

    # 1. Explicit overlay marker -- authoritative once the overlay is migrated.
    #    The helper exits non-zero for "not board-less" AND for "config unreadable";
    #    both correctly mean "fall through to the built-in table" below.
    local _cfg_file="${AITEAMFORGE_CONFIG:-${HOME}/.aiteamforge/team-paths.json}"
    if [[ -f "$_cfg_file" ]] && command -v python3 &>/dev/null; then
        local _alias
        if _alias=$(python3 - "$_cfg_file" "$team" 2>/dev/null <<'PYEOF'
import json, sys
from pathlib import Path
cfg, team = sys.argv[1], sys.argv[2]
try:
    entry = json.loads(Path(cfg).read_text(encoding="utf-8")).get("teams", {}).get(team, {})
except Exception:
    sys.exit(1)
if not isinstance(entry, dict) or entry.get("board_less") is not True:
    sys.exit(1)
alias = entry.get("alias_of")
# Absence is representable as missing / null / "null" / "" -- normalize all four
# (_ABSENT_SENTINELS in aiteamforge_paths.py).
if alias not in (None, "", "null"):
    print(alias)
sys.exit(0)
PYEOF
        ); then
            if [[ -n "$_alias" ]]; then
                echo "$_alias"
            else
                # Overlay marks the team board-less but omits alias_of. Python's
                # board_less_alias_of() falls back to DEFAULT_TEAMS here; mirror it,
                # or the error message below loses its "use 'command'" guidance.
                _kb_board_less_builtin_alias_of "$team" || true
            fi
            return 0
        fi
    fi

    # 2. Built-in fallback -- un-migrated overlay, or no overlay at all.
    if _kb_board_less_builtin_alias_of "$team"; then
        return 0
    fi

    return 1
}

_kb_get_kanban_dir() {
    local team="$1"
    local _atf_dir="${AITEAMFORGE_DIR}"

    # ── Strategy 0: board-less guard (XACA-0727 / XACA-0794-013) ─────────────
    # Refuse BEFORE any resolution strategy. A board-less alias has no board, so
    # every strategy below would be answering the wrong question -- and the
    # catch-all would answer it with someone else's board.
    local _bl_alias
    if _bl_alias=$(_kb_board_less_alias_of "$team"); then
        if [[ -n "$_bl_alias" ]]; then
            echo "kb: '$team' is a board-less alias (no kanban board) — this is intentional, not corruption. Use '$_bl_alias' instead. (XACA-0727/XACA-0794)" >&2
        else
            echo "kb: '$team' is a board-less alias (no kanban board) — this is intentional, not corruption. (XACA-0727/XACA-0794)" >&2
        fi
        return 1
    fi

    # ── Strategy 1: team-paths.json registry (XACA-0649) ─────────────────────
    # Read kanban_dir directly from the registry — the same source the Python
    # server uses — so the shell and Python resolvers always agree.
    # Only trust an entry that is both non-empty AND points to an existing directory.
    local _cfg_file="${AITEAMFORGE_CONFIG:-${HOME}/.aiteamforge/team-paths.json}"
    if [[ -f "$_cfg_file" ]] && command -v python3 &>/dev/null; then
        local _reg_dir
        _reg_dir=$(python3 - "$_cfg_file" "$team" 2>/dev/null <<'PYEOF'
import json, sys
from pathlib import Path
cfg, team = sys.argv[1], sys.argv[2]
try:
    entry = json.loads(Path(cfg).read_text(encoding="utf-8")).get("teams", {}).get(team, {})
    v = entry.get("kanban_dir", "")
    if v:
        print(v)
except Exception:
    pass
PYEOF
)
        if [[ -n "$_reg_dir" ]] && [[ -d "$_reg_dir" ]]; then
            echo "$_reg_dir"
            return 0
        fi
        # Registry has an entry but directory does not exist yet (first-launch) —
        # fall through to case arms which carry the same paths via well-known patterns.
    fi

    # ── Strategy 2: well-known case arms ─────────────────────────────────────
    case "$team" in
        academy)
            echo "${_atf_dir}/kanban"
            ;;
        ios)
            # TODO(installer): replace {{SHARED_DEV_ROOT}} with paths.shared_dev_root at install time
            echo "{{SHARED_DEV_ROOT}}/{{ORG_NAME}}App-iOS/kanban"
            ;;
        android)
            echo "{{SHARED_DEV_ROOT}}/{{ORG_NAME}}App-Android/kanban"
            ;;
        firebase)
            echo "{{SHARED_DEV_ROOT}}/{{ORG_NAME}}App-Functions/kanban"
            ;;
        command)
            echo "{{SHARED_DEV_ROOT}}/dev-team/kanban"
            ;;
        dns)
            # TODO(installer): replace with org-specific DNS framework path if applicable
            echo "${HOME}/dns-framework/kanban"
            ;;
        legal-*)
            local _suffix="${team#legal-}"
            echo "${HOME}/legal/${_suffix}/kanban"
            ;;
        medical-*)
            local _suffix="${team#medical-}"
            echo "${HOME}/medical/${_suffix}/kanban"
            ;;
        finance-*)
            local _suffix="${team#finance-}"
            echo "${HOME}/finance/${_suffix}/kanban"
            ;;
        freelance-*)
            # Try to extract project from team ID (e.g., freelance-<client>-<project>)
            local _parts=("${(@s/-/)team}")
            if [[ ${#_parts[@]} -ge 3 ]]; then
                local _client="${_parts[2]}"
                local _project="${_parts[3]}"
                echo "${HOME}/development/${_client}/${_project}/kanban"
            else
                echo "${_atf_dir}/kanban"
            fi
            ;;
        # ── Strategy 3: unknown team — central fallback ───────────────────────
        *)
            echo "${_atf_dir}/kanban"
            ;;
    esac
}

# Get the config directory for a specific team (kanban/config/)
# Each team's config lives alongside their board data for self-containment.
# Mirrors TEAM_CONFIG_DIR in server.py and _TEAM_KANBAN_DIRS in manager.py.
_kb_get_config_dir() {
    local team="$1"
    local kanban_dir
    kanban_dir=$(_kb_get_kanban_dir "$team")
    echo "${kanban_dir}/config"
}

# ============================================================================
# Safe File Operations with Locking
# ============================================================================
# These functions use file locking to prevent race conditions with Python hooks

_kb_lock_file() {
    local board_file="$1"
    echo "${board_file}.lock"
}

# Run an argv command (no shell) under an exclusive flock, capturing its
# stdout to tmp_file and atomically renaming it onto target_file on success.
# Usage: _kb_jq_atomic_write <lock_file> <tmp_file> <target_file> <error_label> <argv...>
#   <argv...>       the command to run (e.g. jq --arg x "$v" -f filter board)
#   <error_label>   text appended after "ERROR: " to stderr on failure
# Returns 0 on success (target_file now holds the new content), 1 on failure
# (tmp_file removed, nothing written to target_file).
#
# XACA-0935: the code this replaced built a shell command STRING via zsh's
# `printf '%q'` and ran it through a freshly spawned `sh -c "..."`. Any
# --arg/--argjson VALUE containing embedded newlines makes zsh's `printf '%q'`
# emit bash/zsh-only `$'...'` ANSI-C quoting; macOS's default /bin/sh (bash in
# posix mode) tolerates that, but Linux's dash /bin/sh does not understand
# `$'...'` and silently mis-parses the argument boundary, corrupting the JSON
# payload before jq ever sees it. This primitive hands argv straight to
# Perl's system(LIST) form (the same technique the sibling _kb_jq_read already
# used), which execs via execvp with NO shell involved at all, so no argument,
# however it's shaped, is ever re-parsed or re-quoted.
_kb_jq_atomic_write() {
    local lock_file="$1"
    local tmp_file="$2"
    local target_file="$3"
    local error_label="$4"
    shift 4
    local cmd_argv=("$@")

    # Create lock file if it doesn't exist
    touch "$lock_file" 2>/dev/null

    # Use Perl's flock for exclusive locking (available on macOS by default)
    # Note: bash flock syntax (200>"$file") doesn't work in zsh, so we use perl
    perl -e '
        use Fcntl qw(:flock);
        my $lock_file   = shift @ARGV;
        my $tmp_file    = shift @ARGV;
        my $target_file = shift @ARGV;

        # Structural guarantee, not just an incidental fact: this primitive
        # must never be able to degenerate into system()'"'"'s single-scalar
        # shell-metacharacter-check form, which (unlike the execvp() LIST
        # form) re-parses the argv through a shell. Both real callers here
        # always pass jq with well over a dozen argv elements.
        die "_kb_jq_atomic_write: refusing to run with fewer than 2 argv elements (got " . scalar(@ARGV) . ") -- this primitive must never shell out\n"
            if scalar(@ARGV) < 2;

        # A die() between here and the successful rename() below must not
        # leave $tmp_file behind. An END block fires on every exit path,
        # die()s included, so cleanup can never be skipped. $cleanup_tmp is
        # cleared only after a successful rename, where $tmp_file no longer
        # exists anyway.
        my $cleanup_tmp = 1;
        END { unlink($tmp_file) if $cleanup_tmp && defined($tmp_file) && -e $tmp_file; }

        open(my $fh, ">", $lock_file) or die "Cannot open lock file: $!";
        flock($fh, LOCK_EX) or die "Cannot lock: $!";

        # Capture the child'"'"'s stdout to tmp_file by redirecting our own
        # STDOUT fd before exec (system() children inherit it) -- no shell
        # redirection operator needed.
        open(my $out, ">", $tmp_file) or die "Cannot open tmp file: $!";
        open(my $saved_stdout, ">&STDOUT") or die "Cannot save stdout: $!";
        open(STDOUT, ">&", $out) or die "Cannot redirect stdout: $!";
        # Indirect-object form forces execvp() LIST-form dispatch
        # unconditionally, regardless of how many elements @ARGV has --
        # unlike plain system(@ARGV), this can never degenerate into the
        # single-scalar shell path even if the die guard above were bypassed.
        my $status = system { $ARGV[0] } @ARGV;  # zsh-index-ok: Perl, 0-indexed by design
        open(STDOUT, ">&", $saved_stdout) or die "Cannot restore stdout: $!";
        close($saved_stdout);
        close($out);

        # SAFETY: gate on the FULL $status, never `$status >> 8` alone. A
        # child killed by a signal (SIGTERM/SIGINT/...) sets the low 7 bits
        # of $status and leaves the high byte (the shifted "exit code") at 0
        # -- `>> 8` alone reads that as a clean exit(0) and would rename a
        # partially-flushed tmp file over the target. Only a literal
        # $status == 0 (no signal, exit code 0) counts as success.
        if ($status == 0 && -s $tmp_file) {
            rename($tmp_file, $target_file) or die "Cannot rename tmp file: $!";
            $cleanup_tmp = 0;
            close($fh);
            exit(0);
        }

        # Failure path: report a specific reason instead of letting the
        # caller'"'"'s generic $error_label stand in for every cause -- a
        # signal kill, a nonzero jq exit, and a genuine empty-output guard
        # trip are different failure classes. Callers that want silence
        # (e.g. _kb_log_activity, deliberately best-effort) already wrap this
        # whole invocation in 2>/dev/null.
        my $exit_code;
        if ($status == -1) {
            print STDERR "_kb_jq_atomic_write: failed to execute command: $!\n";
            $exit_code = 1;
        } elsif ($status & 127) {
            my $sig = $status & 127;
            print STDERR "_kb_jq_atomic_write: command killed by signal $sig\n";
            $exit_code = 128 + $sig;
        } elsif ($status != 0) {
            my $rc = $status >> 8;
            print STDERR "_kb_jq_atomic_write: command exited with status $rc\n";
            $exit_code = $rc;
        } else {
            print STDERR "_kb_jq_atomic_write: command produced empty output\n";
            $exit_code = 1;
        }

        # XACA-0935: unlink $tmp_file HERE, while the flock is still held,
        # instead of leaving it to the END block. $tmp_file is a fixed,
        # non-unique name (${board_file}.tmp) shared by every writer racing
        # for this lock -- an END-only unlink runs AFTER close($fh) below
        # releases the lock, so a slow failing process could delete the tmp
        # file a different, already-relocked writer just created. Cleaning
        # up in-lock, before close($fh), removes that window; END remains a
        # safety net for `die` exits, all of which (once $tmp_file exists)
        # happen before $fh is closed, so it still always fires in-lock.
        unlink($tmp_file) if defined($tmp_file) && -e $tmp_file;
        $cleanup_tmp = 0;
        close($fh);
        exit($exit_code);
    ' "$lock_file" "$tmp_file" "$target_file" "${cmd_argv[@]}"

    local result=$?
    [[ $result -ne 0 ]] && echo "ERROR: ${error_label}" >&2
    return $result
}

# Execute a jq operation with exclusive file locking
# Usage: _kb_jq_update "board_file" "jq_filter" [jq_args...]
_kb_jq_update() {
    local board_file="$1"
    local jq_filter="$2"
    shift 2
    local jq_args=("$@")

    local lock_file="${board_file}.lock"
    local tmp_file="${board_file}.tmp"

    # Write jq filter to a temp file to avoid zsh printf '%q' escaping issues.
    # zsh's printf '%q' escapes '!' to '\!' -- this used to matter because the
    # filter round-tripped through `sh -c`; that round-trip is gone (XACA-0935,
    # see _kb_jq_atomic_write above), but the temp-file/`-f` approach is kept
    # anyway since it keeps long/multi-line filter bodies out of argv, and
    # test-kb-jq-bang-hist.sh asserts on this exact invariant.
    local filter_file
    filter_file=$(mktemp "${TMPDIR:-/tmp}/kb-jq-filter.XXXXXX")
    printf '%s' "$jq_filter" > "$filter_file"

    _kb_jq_atomic_write "$lock_file" "$tmp_file" "$board_file" \
        "jq produced empty output, aborting write" \
        jq "${jq_args[@]}" -f "$filter_file" "$board_file"
    local result=$?

    rm "$filter_file" 2>/dev/null

    # After successful board update, trigger team re-registration and board push (background, non-blocking)
    # This keeps Fleet Monitor in sync when board data changes
    # NOTE: Double-subshell idiom suppresses zsh's [N] job start/done notifications
    if [ $result -eq 0 ]; then
        ( (type _kb_register_team &>/dev/null && _kb_register_team) & ) 2>/dev/null
        ( (type _kb_push_board &>/dev/null && _kb_push_board) & ) 2>/dev/null
    fi

    return $result
}

# Read board file with shared locking
# Usage: _kb_jq_read "board_file" "jq_filter" [jq_args...]
_kb_jq_read() {
    local board_file="$1"
    local jq_filter="$2"
    shift 2
    local jq_args=("$@")

    local lock_file="${board_file}.lock"

    # Create lock file if it doesn't exist
    touch "$lock_file" 2>/dev/null

    # Use shared lock (LOCK_SH) to prevent reading during writes
    # This prevents race conditions where we read a 0-byte file during atomic rename
    perl -e '
        use Fcntl qw(:flock);
        my $lock_file = $ARGV[0];
        open(my $fh, "<", $lock_file) or die "Cannot open lock file: $!";
        flock($fh, LOCK_SH) or die "Cannot lock: $!";
        my $exit_code = system(@ARGV[1..$#ARGV]);
        close($fh);
        exit($exit_code >> 8);
    ' "$lock_file" jq "${jq_args[@]}" "$jq_filter" "$board_file"
}

# Resolve context purely from explicit env signals (XACA-0725).
# Precedence: KB_TEAM (canonical) → LCARS_TEAM (LCARS runtime) → AITEAMFORGE_TEAM
# (legacy alias). These are DELIBERATE, per-invocation assertions of team
# identity, so they outrank the ambient tmux session (see _kb_detect_context).
# Returns "team:terminal:window_index:window_name" on success, exit 1 otherwise.
_kb_resolve_explicit_env_context() {
    local team
    if [[ -n "${KB_TEAM:-}" ]]; then
        team="${KB_TEAM}"
    elif [[ -n "${LCARS_TEAM:-}" ]]; then
        team="${LCARS_TEAM}"
    elif [[ -n "${AITEAMFORGE_TEAM:-}" ]]; then
        team="${AITEAMFORGE_TEAM}"
    fi

    if [[ -n "${team:-}" ]]; then
        echo "${team}:${KB_TERMINAL:-agent}:${KB_WINDOW_INDEX:-0}:${KB_WINDOW_NAME:-main}"
        return 0
    fi

    return 1
}

# Detect which team, terminal, and window we're in.
# Priority (XACA-0725): an explicit env signal (KB_TEAM / LCARS_TEAM /
# AITEAMFORGE_TEAM) outranks the ambient tmux session — a cross-team agent that
# exported KB_TEAM=<other-team> inside another team's tmux pane was previously
# mis-attributed to the session team. Normal panes set no such var → tmux wins.
_kb_detect_context() {
    # Priority 1: explicit env signals outrank the ambient tmux session.
    if _kb_resolve_explicit_env_context; then
        return 0
    fi

    local session_name window_index window_name
    local pane_target="${TMUX_PANE:-}"
    if [[ -n "$pane_target" ]]; then
        session_name=$(tmux display-message -t "$pane_target" -p '#S' 2>/dev/null || echo "")
        window_index=$(tmux display-message -t "$pane_target" -p '#I' 2>/dev/null || echo "0")
        window_name=$(tmux display-message -t "$pane_target" -p '#W' 2>/dev/null || echo "main")
    else
        session_name=$(tmux display-message -p '#S' 2>/dev/null || echo "")
        window_index=$(tmux display-message -p '#I' 2>/dev/null || echo "0")
        window_name=$(tmux display-message -p '#W' 2>/dev/null || echo "main")
    fi

    if [[ -z "$session_name" ]]; then
        echo "ERROR:ERROR:0:unknown"
        return 1
    fi

    # Extract team/board-prefix and terminal from session name
    # Works for any number of segments:
    #   freelance-command → team=freelance, terminal=command
    #   freelance-<client>-<project>-command → team=freelance-<client>-<project>, terminal=command
    #   ios-bridge → team=ios, terminal=bridge
    local team terminal

    # Terminal is always the last segment
    terminal="${session_name##*-}"
    # Team/board-prefix is everything before the last segment
    team="${session_name%-*}"

    echo "${team}:${terminal}:${window_index}:${window_name}"
}

# Get current git worktree path
_kb_get_worktree() {
    git rev-parse --show-toplevel 2>/dev/null || echo ""
}

# Get short worktree name (just the directory name)
_kb_get_worktree_short() {
    local worktree
    worktree=$(_kb_get_worktree)
    if [[ -n "$worktree" ]]; then
        basename "$worktree"
    else
        echo ""
    fi
}

# Check if we're in the main worktree (not a secondary worktree)
# Returns 0 (true) if in main worktree, 1 (false) if in secondary worktree
_kb_is_main_worktree() {
    local git_dir common_dir
    git_dir=$(git rev-parse --git-dir 2>/dev/null)
    common_dir=$(git rev-parse --git-common-dir 2>/dev/null)

    # If not in a git repo, return false
    [[ -z "$git_dir" ]] && return 1

    # If .git is a file (pointing to main repo), we're in a secondary worktree
    if [[ -f "$git_dir" ]]; then
        return 1
    fi

    # If git-dir equals git-common-dir, we're in the main worktree
    if [[ "$git_dir" == "$common_dir" ]]; then
        return 0
    fi

    return 1
}

# Check if we're already in the correct worktree for a given item.
# Compares both the worktree path (from kanban) and the on-disk branch.
# Usage: _kb_is_correct_worktree <item_worktree> <item_worktree_branch>
# Returns 0 if current directory IS the correct worktree, 1 otherwise.
_kb_is_correct_worktree() {
    local expected_worktree="$1"
    local expected_branch="$2"

    # If no worktree info at all, can't be correct
    if [[ -z "$expected_worktree" ]] && [[ -z "$expected_branch" ]]; then
        return 1
    fi

    # Path-based check: are we physically in the expected worktree directory?
    if [[ -n "$expected_worktree" ]] && [[ -d "$expected_worktree" ]]; then
        local current_real expected_real
        current_real=$(pwd -P 2>/dev/null)
        expected_real=$(cd "$expected_worktree" && pwd -P 2>/dev/null)
        if [[ "$current_real" == "$expected_real" ]]; then
            # Also verify on-disk branch matches if we have an expected branch
            if [[ -n "$expected_branch" ]]; then
                local current_branch
                current_branch=$(git branch --show-current 2>/dev/null)
                if [[ "$current_branch" == "$expected_branch" ]]; then
                    return 0
                fi
                # Path matches but branch doesn't — not correct
                return 1
            fi
            return 0
        fi
    fi

    # Branch-based fallback: if no path match, check branch in current worktree
    if [[ -n "$expected_branch" ]]; then
        local current_branch
        current_branch=$(git branch --show-current 2>/dev/null)
        if [[ "$current_branch" == "$expected_branch" ]]; then
            return 0
        fi
    fi

    return 1
}

# ============================================================================
# XACA-0395 — consumer auth-header helpers
# ============================================================================
# Two independent secrets. Never cross them:
#   LCARS mutating calls         -> AITEAMFORGE_API_KEY (via installed `kb-api-key show`)
#   fleet-monitor mutating calls -> FLEET_AUTH_TOKEN (env, else fleet-config.json)
# Graceful degradation: when no key/token resolves, the server-side gate is
# OPEN, so sending no header is correct — these helpers populate an empty
# array rather than failing, and callers must not hard-fail on it.
# Ported from dev-team's kanban-helpers.sh (subitem 006) into this template's
# own conventions — this file is hand-maintained, not a `sync_file` mirror of
# the canonical source, so the port adapts rather than copies verbatim.

# Populate _KB_LCARS_AUTH_ARGS (curl flags) and _KB_LCARS_AUTH_STDIN (the curl
# config-file text to feed on stdin) carrying the LCARS Authorization header,
# or leave BOTH empty if no key resolves. Resolves via the installed
# `kb-api-key show` helper, which implements the same env-over-file precedence
# the LCARS server itself uses.
#
# XACA-0395 review finding 022: the header goes through `curl --config -` on
# stdin rather than `-H` in argv, because argv is world-readable via `ps` and
# would expose the key to any other local user. Callers must pipe
# "$_KB_LCARS_AUTH_STDIN" into curl whenever the array is non-empty.
_kb_lcars_auth_args() {
    _KB_LCARS_AUTH_ARGS=()
    _KB_LCARS_AUTH_STDIN=""
    local _kb_api_key_bin="${AITEAMFORGE_DIR}/scripts/kb-api-key"
    [[ -x "$_kb_api_key_bin" ]] || return 0

    local _kb_key
    _kb_key=$(bash "$_kb_api_key_bin" show 2>/dev/null) || return 0
    [[ -z "$_kb_key" ]] && return 0

    # curl config-file syntax quotes the value; escape backslash then quote so
    # a key containing either cannot break parsing.
    local _kb_key_escaped="${_kb_key//\\/\\\\}"
    _kb_key_escaped="${_kb_key_escaped//\"/\\\"}"
    _KB_LCARS_AUTH_ARGS=(--config -)
    _KB_LCARS_AUTH_STDIN=$(printf 'header = "Authorization: Bearer %s"\n' "$_kb_key_escaped")
}

# Populate the global array _KB_FLEET_AUTH_ARGS with curl -H args carrying the
# fleet-monitor Authorization header, or leave it empty if no token resolves.
# Precedence mirrors the existing client precedent in this same tap
# (fleet-reporter.sh, msg-client.js): env FLEET_AUTH_TOKEN wins, else
# fleet-config.json .centralServer.authToken.
_kb_fleet_auth_args() {
    _KB_FLEET_AUTH_ARGS=()
    _KB_FLEET_AUTH_STDIN=""
    local _kb_token="${FLEET_AUTH_TOKEN:-}"
    if [[ -z "$_kb_token" ]]; then
        local _kb_fleet_cfg=""
        if [[ -f "${HOME}/.aiteamforge/fleet-config.json" ]]; then
            _kb_fleet_cfg="${HOME}/.aiteamforge/fleet-config.json"
        elif [[ -f "${HOME}/.dev-team/fleet-config.json" ]]; then
            _kb_fleet_cfg="${HOME}/.dev-team/fleet-config.json"
        fi
        if [[ -n "$_kb_fleet_cfg" ]] && command -v jq >/dev/null 2>&1; then
            _kb_token=$(jq -r '.centralServer.authToken // empty' "$_kb_fleet_cfg" 2>/dev/null)
        fi
    fi
    [[ -z "$_kb_token" ]] && return 0

    # See finding 022 above — header via `curl --config -` on stdin, not argv.
    local _kb_token_escaped="${_kb_token//\\/\\\\}"
    _kb_token_escaped="${_kb_token_escaped//\"/\\\"}"
    _KB_FLEET_AUTH_ARGS=(--config -)
    _KB_FLEET_AUTH_STDIN=$(printf 'header = "Authorization: Bearer %s"\n' "$_kb_token_escaped")
}

# Sync an item to release manifests via LCARS server
# Usage: _kb_release_sync <item_id>
# Returns 0 (success) even if server is down - this is a best-effort sync
_kb_release_sync() {
    local item_id="$1"

    # Skip if no item_id provided
    [[ -z "$item_id" ]] && return 0

    # XACA-0182: Subitem IDs (e.g., XACA-0179-002) are not top-level board
    # items. Release manifests track parent items only, so skip the round-trip
    # to LCARS — the parent syncs separately when kb-done runs on it.
    if [[ "$item_id" =~ ^X[A-Z]{2,4}-[0-9]+-[0-9]+$ ]]; then
        return 0
    fi

    # Determine LCARS port from config file or default
    local _lcars_port="8080"
    local _port_file="${AITEAMFORGE_DIR}/lcars-ui/.lcars-port"
    if [[ -f "$_port_file" ]]; then
        _lcars_port="$(cat "$_port_file" 2>/dev/null || echo "8080")"
    fi

    # Try to sync with LCARS server (2 second timeout)
    # Silent by default - only warn on unexpected errors
    local response http_code
    local _KB_LCARS_AUTH_ARGS=() _KB_LCARS_AUTH_STDIN=""
    _kb_lcars_auth_args
    response=$(printf '%s' "$_KB_LCARS_AUTH_STDIN" | curl -s -w "\n%{http_code}" \
        --max-time 2 \
        -X POST \
        -H "Content-Type: application/json" \
        "${_KB_LCARS_AUTH_ARGS[@]}" \
        -d "{\"itemId\": \"$item_id\"}" \
        "http://localhost:${_lcars_port}/api/releases/sync-item" 2>/dev/null)

    # Extract HTTP code from last line
    http_code=$(echo "$response" | tail -n1)

    # Silently succeed if server isn't running or sync worked
    # Only warn on unexpected HTTP codes (not 200, 404, or connection failure)
    if [[ -n "$http_code" ]] && [[ "$http_code" != "200" ]] && [[ "$http_code" != "404" ]] && [[ "$http_code" != "000" ]]; then
        echo "⚠️  Warning: Release manifest sync returned HTTP $http_code for $item_id" >&2
    fi

    # Always return success - sync is best-effort
    return 0
}

# Detect the main/development branch for the current repo
# Usage: _kb_get_main_branch [remote_name]
# Prints the branch name (e.g., "develop", "main", "master")
# Detection order:
#   1. Check if remote/develop exists (preferred — most kanban repos use develop)
#   2. git symbolic-ref refs/remotes/<remote>/HEAD (remote default branch)
#   3. Check if remote/main or remote/master exist
#   4. Fallback to "develop"
_kb_get_main_branch() {
    local remote="${1:-$(git remote 2>/dev/null | head -1)}"
    if [[ -z "$remote" ]]; then
        echo "develop"
        return
    fi

    # Method 1: Check if develop exists on remote (preserves existing behavior)
    if git rev-parse --verify "refs/remotes/${remote}/develop" &>/dev/null; then
        echo "develop"
        return
    fi

    # Method 2: Check remote HEAD symbolic ref
    local remote_head
    remote_head=$(git symbolic-ref "refs/remotes/${remote}/HEAD" 2>/dev/null)
    if [[ -n "$remote_head" ]]; then
        # Strip refs/remotes/<remote>/ prefix to get branch name
        local branch="${remote_head#refs/remotes/${remote}/}"
        if [[ -n "$branch" ]]; then
            echo "$branch"
            return
        fi
    fi

    # Method 3: Check for other common branch names on the remote
    local candidate
    for candidate in main master; do
        if git rev-parse --verify "refs/remotes/${remote}/${candidate}" &>/dev/null; then
            echo "$candidate"
            return
        fi
    done

    # Fallback
    echo "develop"
}

# Reset the current worktree to the latest main branch from remote
# Usage: _kb_reset_worktree
# Auto-detects the remote name and main branch
# Returns: 0 = success, 1 = failed but user chose to continue, 2 = user aborted
# On failure, prompts user for confirmation before continuing
_kb_reset_worktree() {
    # Auto-detect remote name (first remote listed)
    local remote
    remote=$(git remote 2>/dev/null | head -1)

    # Warn if multiple remotes exist (using first one)
    local remote_count
    remote_count=$(git remote 2>/dev/null | wc -l | tr -d ' ')
    if [[ "$remote_count" -gt 1 ]]; then
        echo "⚠️  Warning: Multiple remotes detected (using '${remote}'):" >&2
        git remote 2>/dev/null | sed 's/^/   /' >&2
    fi

    if [[ -z "$remote" ]]; then
        echo "⚠️  Warning: No git remote found, skipping worktree reset" >&2
        return 1
    fi

    # Detect the main branch for this repo
    local main_branch
    main_branch=$(_kb_get_main_branch "$remote")

    echo "─────────────────────────────────────"
    echo "🔄 Resetting worktree to ${remote}/${main_branch}..."

    # Fetch latest main branch from remote
    local fetch_output fetch_exit
    fetch_output=$(git fetch "$remote" "$main_branch" 2>&1)
    fetch_exit=$?
    if [[ -n "$fetch_output" ]]; then
        echo "$fetch_output" | sed 's/^/   /'
    fi
    if [[ $fetch_exit -ne 0 ]]; then
        echo "" >&2
        echo "❌ Error: Could not fetch ${remote}/${main_branch}" >&2
        echo "   Possible causes: no network, branch doesn't exist, or auth failure" >&2
        echo "" >&2
        echo -n "   Continue without resetting worktree? [y/N] " >&2
        local confirm="n"
        if (exec < /dev/tty) 2>/dev/null; then
            read -r confirm < /dev/tty
        fi
        if [[ "$confirm" =~ ^[Yy]$ ]]; then
            echo "   Continuing with current worktree state." >&2
            echo "─────────────────────────────────────"
            return 1
        else
            echo "   Aborting." >&2
            echo "─────────────────────────────────────"
            return 2
        fi
    fi

    # Warn about uncommitted changes that will be lost
    local dirty_files
    dirty_files=$(git status --porcelain 2>/dev/null)
    if [[ -n "$dirty_files" ]]; then
        echo "⚠️  Warning: Uncommitted changes will be lost:" >&2
        echo "$dirty_files" | sed 's/^/   /' >&2
    fi

    # Hard-reset current branch to remote main branch
    local reset_output reset_exit
    reset_output=$(git reset --hard "${remote}/${main_branch}" 2>&1)
    reset_exit=$?
    if [[ -n "$reset_output" ]]; then
        echo "$reset_output" | sed 's/^/   /'
    fi
    if [[ $reset_exit -ne 0 ]]; then
        echo "" >&2
        echo "❌ Error: Could not reset to ${remote}/${main_branch}" >&2
        echo "" >&2
        echo -n "   Continue without resetting worktree? [y/N] " >&2
        local confirm="n"
        if (exec < /dev/tty) 2>/dev/null; then
            read -r confirm < /dev/tty
        fi
        if [[ "$confirm" =~ ^[Yy]$ ]]; then
            echo "   Continuing with current worktree state." >&2
            echo "─────────────────────────────────────"
            return 1
        else
            echo "   Aborting." >&2
            echo "─────────────────────────────────────"
            return 2
        fi
    fi

    # Clean untracked files and directories
    local clean_output
    clean_output=$(git clean -fd 2>&1)
    if [[ -n "$clean_output" ]]; then
        echo "$clean_output" | sed 's/^/   /'
    fi

    echo "✓ Worktree reset to ${remote}/${main_branch}"
    echo "─────────────────────────────────────"
    return 0
}

# Create a worktree for an item and cd into it
# Usage: _kb_create_item_worktree <item_id> <title>
# Returns the worktree path, or empty on failure
_kb_create_item_worktree() {
    local item_id="$1"
    local title="$2"

    local git_root worktree_dir branch_name worktree_name project_root

    # Get the main repo root (works from any worktree)
    git_root=$(git rev-parse --git-common-dir 2>/dev/null | xargs dirname)
    if [[ -z "$git_root" ]] || [[ "$git_root" == "." ]]; then
        git_root=$(git rev-parse --show-toplevel 2>/dev/null)
    fi

    if [[ -z "$git_root" ]]; then
        echo "Error: Not in a git repository" >&2
        return 1
    fi

    # Determine the project root for worktrees
    # If git_root is named after a common main branch (develop, main, master, DEV),
    # worktrees should be a sibling directory (one level up), not inside the checkout directory
    local git_root_name
    git_root_name=$(basename "$git_root")
    if [[ "$git_root_name" == "develop" ]] || [[ "$git_root_name" == "main" ]] || [[ "$git_root_name" == "master" ]] || [[ "$git_root_name" == "DEV" ]]; then
        project_root=$(dirname "$git_root")
    else
        project_root="$git_root"
    fi

    # Create worktree directory name from item ID (lowercase, portable)
    worktree_name=$(echo "$item_id" | tr '[:upper:]' '[:lower:]')
    worktree_dir="${project_root}/worktrees/${worktree_name}"

    # Create branch name from item ID (lowercase, portable)
    branch_name="feature/${worktree_name}"

    # Check if worktree is already tracked by git
    local existing_worktree
    existing_worktree=$(git worktree list --porcelain 2>/dev/null | grep -A2 "^worktree.*/${worktree_name}$" | head -1 | sed 's/^worktree //')

    if [[ -n "$existing_worktree" ]] && [[ -d "$existing_worktree" ]]; then
        echo "✓ Using existing worktree: $existing_worktree" >&2
        echo "$existing_worktree"
        return 0
    fi

    # Check if directory exists but git doesn't know about it (orphaned)
    if [[ -d "$worktree_dir" ]]; then
        # Check if it's a valid git worktree
        if [[ -f "$worktree_dir/.git" ]]; then
            echo "⚠️  Found orphaned worktree directory. Attempting repair..." >&2
            # Try to repair by removing and re-adding
            git worktree remove "$worktree_dir" --force 2>/dev/null
        else
            echo "⚠️  Directory exists but is not a worktree: $worktree_dir" >&2
            echo "   Removing and recreating..." >&2
            rm -rf "$worktree_dir"
        fi
    fi

    # Check if branch exists and where it's checked out
    local branch_checkout
    branch_checkout=$(git worktree list --porcelain 2>/dev/null | grep -B1 "\[${branch_name}\]" | head -1 | sed 's/^worktree //')

    if [[ -n "$branch_checkout" ]]; then
        echo "⚠️  Branch '$branch_name' is already checked out at:" >&2
        echo "   $branch_checkout" >&2
        echo "   Use that worktree or run: git worktree remove \"$branch_checkout\"" >&2
        return 1
    fi

    # Create worktrees directory if it doesn't exist
    mkdir -p "${project_root}/worktrees"

    # Create the worktree with a new branch based on current branch
    echo "Creating worktree for [$item_id]..." >&2
    echo "  Directory: $worktree_dir" >&2
    echo "  Branch: $branch_name" >&2

    local git_error
    # Try to create with new branch first
    if git_error=$(git worktree add -b "$branch_name" "$worktree_dir" 2>&1); then
        echo "✓ Created new worktree with branch $branch_name" >&2
        echo "$worktree_dir"
        return 0
    fi

    # If branch already exists, try to use it
    if echo "$git_error" | grep -q "already exists"; then
        echo "  Branch exists, attaching worktree..." >&2
        # Redirect both stdout and stderr - git outputs "HEAD is now at..." to stdout
        if git worktree add "$worktree_dir" "$branch_name" >/dev/null 2>&1; then
            echo "✓ Created worktree using existing branch $branch_name" >&2
            echo "$worktree_dir"
            return 0
        fi
    fi

    # Provide detailed error
    echo "Error: Failed to create worktree" >&2
    echo "  Git error: $git_error" >&2
    echo "  Try manually: git worktree add -b $branch_name $worktree_dir" >&2
    return 1
}

# Check if worktree is already in use by another item/subitem
# Returns: "conflict:<id>:<title>" if conflict found, empty otherwise
_kb_check_worktree_conflict() {
    local board_file="$1"
    local current_id="$2"
    local worktree="$3"

    if [[ -z "$worktree" ]]; then
        return 0
    fi

    # Check main items for worktree conflicts
    local conflict
    conflict=$(_kb_jq_read "$board_file" '
        .backlog[] |
        select(.activelyWorking == true and .worktree == $wt and .id != $cid) |
        "item:\(.id):\(.title)"
    ' --arg wt "$worktree" --arg cid "$current_id" -r | head -1)

    if [[ -n "$conflict" ]]; then
        echo "$conflict"
        return 0
    fi

    # Check subitems for worktree conflicts
    conflict=$(_kb_jq_read "$board_file" '
        .backlog[].subitems[]? |
        select(.activelyWorking == true and .worktree == $wt and .id != $cid) |
        "subitem:\(.id):\(.title)"
    ' --arg wt "$worktree" --arg cid "$current_id" -r | head -1)

    if [[ -n "$conflict" ]]; then
        echo "$conflict"
        return 0
    fi

    echo ""
}

# Display worktree conflict warning
_kb_warn_worktree_conflict() {
    local conflict="$1"
    local conflict_type="${conflict%%:*}"
    local rest="${conflict#*:}"
    local conflict_id="${rest%%:*}"
    local conflict_title="${rest#*:}"

    echo ""
    echo "⚠️  WORKTREE CONFLICT WARNING"
    echo "─────────────────────────────────────"
    echo "This worktree is already in use by:"
    if [[ "$conflict_type" == "subitem" ]]; then
        echo "  Subitem: [$conflict_id] $conflict_title"
    else
        echo "  Item: [$conflict_id] $conflict_title"
    fi
    echo ""
    echo "Working on multiple items in the same worktree can cause confusion."
    echo "Consider:"
    echo "  • Complete or stop working on the other item first"
    echo "  • Create a separate worktree for this task"
    echo ""
    echo "Proceeding anyway..."
    echo "─────────────────────────────────────"
}

_kb_get_board_file() {
    local team="$1"
    local kanban_dir
    kanban_dir=$(_kb_get_kanban_dir "$team")
    echo "${kanban_dir}/${team}-board.json"
}

_kb_ensure_jq() {
    if ! command -v jq &> /dev/null; then
        echo "Error: jq is required but not installed."
        echo "Install with: brew install jq"
        return 1
    fi
    return 0
}

_kb_get_timestamp() {
    date -u +"%Y-%m-%dT%H:%M:%SZ"
}

# Set the item/subitem being worked on for the current window
# Usage: _kb_set_working_on <id> [work_mode]
# ID can be an item (XFRE-0001) or subitem (XFRE-0001-001)
# work_mode can be DEV, REVIEW, TEST, DEBUG, or empty string (clears workMode)
_kb_set_working_on() {
    local working_id="$1"
    local work_mode="${2:-}"

    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    local timestamp
    timestamp=$(_kb_get_timestamp)

    _kb_jq_update "$board_file" '
       (.activeWindows[] | select(.id == $wid)) |= (
           . + { workingOnId: $workingId } |
           if $workMode == "" then del(.workMode) else . + { workMode: $workMode } end
       ) |
       .lastUpdated = $ts
       ' \
       --arg wid "$window_id" \
       --arg workingId "$working_id" \
       --arg workMode "$work_mode" \
       --arg ts "$timestamp"

    # Activity log: window claimed on item
    _kb_log_activity "window_claimed" "$working_id" "item" "" "" "" "workMode=${work_mode:-DEV}"
}

# Clear the working-on item for the current window
_kb_clear_working_on() {
    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Capture current workingOnId before clearing (for activity log)
    local prev_working_id
    prev_working_id=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $wid) | .workingOnId) // ""' \
        --arg wid "$window_id" -r 2>/dev/null || echo "")

    _kb_jq_update "$board_file" '
       (.activeWindows[] | select(.id == $wid)) |= del(.workingOnId, .workMode) |
       .lastUpdated = $ts
       ' \
       --arg wid "$window_id" \
       --arg ts "$timestamp"

    # Activity log: window released
    if [[ -n "$prev_working_id" ]]; then
        _kb_log_activity "window_released" "$prev_working_id" "item" "" "" "" ""
    fi
}

# Extract 2-letter code from compound word (e.g., starwords→SW, appplanning→AP)
# Uses heuristic: find consonant cluster after vowel, split it to find word boundary
_kb_extract_compound_code() {
    local word
    word=$(echo "$1" | tr '[:upper:]' '[:lower:]')  # zsh-compatible lowercase
    local len=${#word}

    # Check for camelCase first (e.g., StarWords → SW)
    # Look for lowercase followed by uppercase
    local camel_match
    camel_match=$(echo "$1" | grep -oE '[a-z][A-Z]' | head -1)
    if [[ -n "$camel_match" ]]; then
        local upper_char="${camel_match:1:1}"
        upper_char=$(echo "$upper_char" | tr '[:upper:]' '[:lower:]')
        echo "${word:0:1}$upper_char"
        return
    fi

    # Heuristic for compound words:
    # Find consonant cluster of 2+ that:
    # 1. Occurs after at least one vowel (not at word start)
    # 2. Is followed by a vowel (not at word end)
    # Then split the cluster - second half starts the new word
    local vowels="aeiou"
    local best_cluster_start=-1
    local best_cluster_len=0
    local cluster_start=-1
    local cluster_len=0
    local seen_vowel=false
    local i=0

    while [[ $i -lt $len ]]; do
        local char="${word:$i:1}"

        if [[ "$vowels" == *"$char"* ]]; then
            # Vowel - mark that we've seen one, check if cluster just ended
            seen_vowel=true
            if [[ $cluster_len -ge 2 && $cluster_len -gt $best_cluster_len ]]; then
                best_cluster_start=$cluster_start
                best_cluster_len=$cluster_len
            fi
            cluster_start=-1
            cluster_len=0
        else
            # Consonant - only track clusters after we've seen a vowel
            if $seen_vowel; then
                if [[ $cluster_start -lt 0 ]]; then
                    cluster_start=$i
                fi
                cluster_len=$((cluster_len + 1))
            fi
        fi
        i=$((i + 1))
    done

    if [[ $best_cluster_start -ge 0 && $best_cluster_len -ge 2 ]]; then
        # Split the cluster - second half starts the new word
        # e.g., "rw" in starwords → split at 'w', "rkst" in workstats → split at 's'
        local split_char_pos=$((best_cluster_start + best_cluster_len / 2))
        echo "${word:0:1}${word:$split_char_pos:1}"
        return
    fi

    # Fallback: first two letters
    echo "${word:0:2}"
}

# Get 3-letter team code for JIRA-style IDs
# Format: X<TeamCode>-#### (e.g., XIOS-0001, XFRE-0042)
_kb_get_team_code() {
    local team="$1"
    case "$team" in
        ios)                               echo "IOS" ;;
        android)                           echo "AND" ;;
        firebase)                          echo "FIR" ;;
        freelance)                         echo "FRE" ;;
        # NOTE: freelance-<client>-<project> entries below are examples of registered
        # team IDs from a specific install. New installations register their own team IDs.
        freelance-doublenode-starwords)    echo "FSW" ;; # xaca-0139:allowed — stable team slug constant
        freelance-doublenode-workstats)    echo "FWS" ;; # xaca-0139:allowed — stable team slug constant
        freelance-doublenode-appplanning)  echo "FAP" ;; # xaca-0139:allowed — stable team slug constant
        freelance-doublenode-lifeboard)    echo "FLB" ;; # xaca-0139:allowed — stable team slug constant
        freelance-doublenode-caravan)      echo "VAN" ;; # xaca-0139:allowed — stable team slug constant
        freelance-doublenode-awaysentry)   echo "FAS" ;; # xaca-0139:allowed — stable team slug constant
        freelance-liquidstyle-agentbadges-app) echo "FLA" ;;
        freelance-liquidstyle-agentbadges-ios) echo "FLI" ;;
        academy)                           echo "ACA" ;;
        dns)                               echo "DNS" ;;
        command)                           echo "CMD" ;;
        # NOTE: "mainevent" is a registered team slug example — xaca-0139:allowed (legacy slug constant, not org branding)
        # At install time, the org team slug ({{ORG_SLUG}}) would be registered instead.
        # xaca-0139:allowed — "mainevent" is a legacy team slug constant (backward-compat alias, not user-facing org branding)
        mainevent)                         echo "MEV" ;;
        legal-coparenting)                 echo "LCP" ;;
        medical-general)                   echo "MED" ;;
        finance-personal)                  echo "FIN" ;;
        *)
            # Smart fallback for multi-segment names (e.g., freelance-<client>-<project>)
            # Uses: first letter of first segment + 2-letter code from last segment
            if [[ "$team" == *-* ]]; then
                local first_segment="${team%%-*}"   # Everything before first dash
                local last_segment="${team##*-}"    # Everything after last dash
                local code="${first_segment:0:1}"   # First letter of first segment
                code+=$(_kb_extract_compound_code "$last_segment")  # Smart 2-letter from last
                echo "${code:0:3}" | tr '[:lower:]' '[:upper:]'
            else
                # Simple single-word name: first 3 chars
                echo "${team:0:3}" | tr '[:lower:]' '[:upper:]'
            fi
            ;;
    esac
}

# Reverse lookup: get team name from 3-letter code
# Format: X<TeamCode>-#### → team name (e.g., XFRE-0013 → freelance, XFSW-0013 → freelance-<client>-<project>)
# Args: code (3-letter code like "FSW" or full ID like "XFSW-0013")
# Returns: team name or empty string if not found
_kb_get_team_from_code() {
    local input="$1"
    local code

    # Extract code from full ID if provided (XFSW-0013 → FSW)
    # Use parameter expansion instead of regex capture for zsh/bash compatibility
    if [[ "$input" =~ ^X[A-Z]{3}-[0-9]+ ]]; then
        # Extract chars 2-4 (0-indexed: positions 1,2,3) → the 3-letter code
        code="${input:1:3}"
    else
        code="$input"
    fi

    case "$code" in
        IOS) echo "ios" ;;
        AND) echo "android" ;;
        FIR) echo "firebase" ;;
        FRE) echo "freelance" ;;
        # NOTE: FSW/FWS/FAP/FLB/VAN/FAS are example registered codes from a
        # specific install. New installations register their own team codes.
        FSW) echo "freelance-doublenode-starwords" ;; # xaca-0139:allowed — stable team slug constant
        FWS) echo "freelance-doublenode-workstats" ;; # xaca-0139:allowed — stable team slug constant
        FAP) echo "freelance-doublenode-appplanning" ;; # xaca-0139:allowed — stable team slug constant
        FLB) echo "freelance-doublenode-lifeboard" ;; # xaca-0139:allowed — stable team slug constant
        VAN) echo "freelance-doublenode-caravan" ;; # xaca-0139:allowed — stable team slug constant
        FAS) echo "freelance-doublenode-awaysentry" ;; # xaca-0139:allowed — stable team slug constant
        FLA) echo "freelance-liquidstyle-agentbadges-app" ;;
        FLI) echo "freelance-liquidstyle-agentbadges-ios" ;;
        ACA) echo "academy" ;;
        DNS) echo "dns" ;;
        CMD) echo "command" ;;
        # NOTE: MEV is the registered team code example. See _kb_get_team_code above.
        # xaca-0139:allowed — "mainevent" is a legacy team slug constant (backward-compat alias, not user-facing org branding)
        MEV) echo "mainevent" ;;
        LCP) echo "legal-coparenting" ;;
        MED) echo "medical-general" ;;
        FIN) echo "finance-personal" ;;
        *)   echo "" ;;  # Unknown code
    esac
}

# Validate Jira ID format and optionally check existence via API
# Args: jira_id
# Returns: 0 always (warn but allow)
# Outputs warning messages to stderr if validation fails
_kb_validate_jira_id() {
    local jira_id="$1"

    # Skip validation for clear operations
    [[ "$jira_id" == "-" ]] && return 0
    [[ -z "$jira_id" ]] && return 0

    # Basic format validation: PROJECT-123 (1-10 uppercase letters + hyphen + digits)
    if [[ ! "$jira_id" =~ ^[A-Z]{1,10}-[0-9]+$ ]]; then
        echo "⚠️  Warning: '$jira_id' doesn't match standard Jira format (PROJECT-123)" >&2
        echo "   Continuing anyway - ticket may be created later" >&2
        return 0
    fi

    # Optional API validation if credentials are available
    if [[ -n "$JIRA_ENDPOINT" ]] && [[ -n "$JIRA_USER" ]] && [[ -n "$JIRA_API_TOKEN" ]]; then
        local response http_code
        response=$(curl -s -o /dev/null -w "%{http_code}" \
            -u "${JIRA_USER}:${JIRA_API_TOKEN}" \
            "${JIRA_ENDPOINT}/rest/api/3/issue/${jira_id}?fields=summary" \
            --connect-timeout 3 --max-time 5 2>/dev/null)

        case "$response" in
            200)
                # Ticket exists - all good
                ;;
            404)
                echo "⚠️  Warning: Jira ticket '$jira_id' not found in ${JIRA_ENDPOINT}" >&2
                echo "   Continuing anyway - ticket may be created later" >&2
                ;;
            401|403)
                # Auth issues - silently skip API validation
                ;;
            000|"")
                # Network/timeout - silently skip
                ;;
            *)
                # Other errors - silently skip
                ;;
        esac
    fi

    return 0
}

# Generate next ID for a team
# Returns: X<TeamCode>-#### (e.g., XIOS-0001)
# Validate and auto-correct nextId counter to prevent duplicate IDs
# Returns the safe next ID number (validates against existing items)
_kb_validate_next_id() {
    local board_file="$1"
    local series="$2"

    # Get the current nextId from board
    local next_id
    next_id=$(_kb_jq_read "$board_file" '.nextId // 1' -r)

    # Find the highest existing ID number in backlog matching this series
    # Extract numeric portion from IDs like "XAND-0564" -> 564
    local max_existing
    max_existing=$(_kb_jq_read "$board_file" \
        '[.backlog[].id | select(startswith($series + "-")) | split("-")[1] | tonumber] | max // 0' \
        --arg series "$series" -r 2>/dev/null)

    # If max_existing is null/empty, default to 0
    if [[ -z "$max_existing" || "$max_existing" == "null" ]]; then
        max_existing=0
    fi

    # Ensure nextId is always greater than the highest existing ID
    if [[ "$next_id" -le "$max_existing" ]]; then
        local corrected_id=$((max_existing + 1))
        echo "⚠️  ID counter sync issue detected: nextId=$next_id but max existing ID=$max_existing" >&2
        echo "   Auto-correcting nextId to $corrected_id" >&2

        # Update the board with corrected nextId
        local timestamp
        timestamp=$(_kb_get_timestamp)
        _kb_jq_update "$board_file" \
            '.nextId = ($new_id | tonumber) | .lastUpdated = $ts' \
            --arg new_id "$corrected_id" --arg ts "$timestamp"

        echo "$corrected_id"
    else
        echo "$next_id"
    fi
}

_kb_generate_id() {
    local board_file="$1"
    local team="$2"

    # Priority 1: Use 'series' field from board config (single source of truth)
    local series
    series=$(_kb_jq_read "$board_file" '.series // empty' -r 2>/dev/null)

    local prefix
    if [[ -n "$series" ]]; then
        # Board has explicit series prefix (e.g., "XLCP")
        prefix="$series"
    else
        # Fallback to derived team code
        local team_code
        team_code=$(_kb_get_team_code "$team")
        prefix="X$team_code"
    fi

    # SAFEGUARD: Validate nextId against existing items to prevent duplicates
    local next_num
    next_num=$(_kb_validate_next_id "$board_file" "$prefix")

    # Format as 4-digit number with leading zeros
    printf "%s-%04d" "$prefix" "$next_num"
}

# Increment the nextId counter in the board
_kb_increment_id() {
    local board_file="$1"
    local timestamp
    timestamp=$(_kb_get_timestamp)

    _kb_jq_update "$board_file" \
       '.nextId = ((.nextId // 1) + 1) | .lastUpdated = $ts' \
       --arg ts "$timestamp"
}

# Find item index by ID
# Returns the array index or -1 if not found
_kb_find_by_id() {
    local board_file="$1"
    local item_id="$2"

    _kb_jq_read "$board_file" \
       '.backlog | to_entries | map(select(.value.id == $id)) | .[0].key // -1' \
       --arg id "$item_id" -r
}

# Resolve selector to index - supports both ID (XIOS-0001) and numeric index
_kb_resolve_selector() {
    local board_file="$1"
    local selector="$2"

    if [[ "$selector" =~ ^X[A-Z]{3}-[0-9]+$ ]]; then
        # It's an ID - look it up
        _kb_find_by_id "$board_file" "$selector"
    elif [[ "$selector" =~ ^[0-9]+$ ]]; then
        # It's a numeric index
        echo "$selector"
    else
        echo "-1"
    fi
}

# Resolve a subitem ID (e.g., XFRE-0001-001) to "parent_idx:subitem_idx"
# Returns "-1:-1" if not found
_kb_resolve_subitem_id() {
    local board_file="$1"
    local subitem_id="$2"

    # Match pattern: XTEAM-####-### (e.g., XFRE-0001-001)
    if [[ ! "$subitem_id" =~ ^(X[A-Z]{2,4}-[0-9]+)-([0-9]+)$ ]]; then
        echo "-1:-1"
        return
    fi

    local parent_id="${match[1]}"

    # Find parent index
    local parent_idx
    parent_idx=$(_kb_find_by_id "$board_file" "$parent_id")

    if [[ "$parent_idx" == "-1" ]]; then
        echo "-1:-1"
        return
    fi

    # Find subitem by ID
    local sub_idx
    sub_idx=$(_kb_jq_read "$board_file" \
        '.backlog[$pidx].subitems // [] | to_entries[] | select(.value.id == $sid) | .key' \
        --argjson pidx "$parent_idx" --arg sid "$subitem_id" -r 2>/dev/null | head -n1)

    if [[ -z "$sub_idx" ]]; then
        echo "-1:-1"
        return
    fi

    echo "$parent_idx:$sub_idx"
}

# Check if an ID is a subitem ID (XTEAM-####-###) - XACA-0025
# Usage: _kb_is_subitem_id <id>
# Returns: 0 (true) if subitem ID, 1 (false) otherwise
_kb_is_subitem_id() {
    local id="$1"
    [[ "$id" =~ ^X[A-Z]{2,4}-[0-9]+-[0-9]+$ ]]
}

# Generate unique window ID
_kb_get_window_id() {
    local terminal="$1"
    local window_name="$2"
    echo "${terminal}:${window_name}"
}

# ============================================================================
# Core Window Management
# ============================================================================

# Update or create a window entry in activeWindows (with file locking)
_kb_update_window() {
    _kb_ensure_jq || return 1

    local task_status="$1"
    local task="$2"

    local context team terminal window_index window_name board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    local timestamp worktree window_id
    timestamp=$(_kb_get_timestamp)
    # XACA-0020 FIX: Use full worktree path for comparison with existing entry
    # Previously used _kb_get_worktree_short which never matched $existing.worktree (full path)
    worktree=$(_kb_get_worktree)
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get developer info from terminals (read with locking)
    local developer color
    developer=$(_kb_jq_read "$board_file" '.terminals[$t].developer // "Unknown"' --arg t "$terminal" -r)
    color=$(_kb_jq_read "$board_file" '.terminals[$t].color // "operations"' --arg t "$terminal" -r)

    # Update or insert window in activeWindows array (with exclusive locking)
    # IMPORTANT: Preserves workingOnId and other persistent fields from existing entry
    _kb_jq_update "$board_file" '
       # Find existing entry to preserve important fields
       # NOTE: Must use [... ] | first // null to handle empty activeWindows array.
       # Using bare (.activeWindows[] | select(...)) as $existing produces ZERO results
       # when no match exists, causing the entire pipeline to emit nothing (empty output).
       ([.activeWindows[] | select(.id == $id)] | first // null) as $existing |
       # Remove existing entry with same id
       .activeWindows = [.activeWindows[] | select(.id != $id)] |
       # Add new/updated entry, preserving persistent fields from existing
       .activeWindows += [{
           id: $id,
           terminal: $terminal,
           window: $window,
           windowName: $windowName,
           status: $status,
           task: $task,
           worktree: $worktree,
           developer: $developer,
           color: $color,
           startedAt: ($existing.startedAt // $timestamp),
           statusChangedAt: (if ($existing.status // "") != $status then $timestamp else ($existing.statusChangedAt // $timestamp) end),
           statusHistory: (if ($existing.status // "") != $status and ($existing.status // "") != "" then (($existing.statusHistory // []) + [$existing.status]) else ($existing.statusHistory // []) end),
           todoProgress: $existing.todoProgress,
           lastActivity: $timestamp,
           workingOnId: ($existing.workingOnId // null),
           workMode: ($existing.workMode // null),
           blockedReason: $existing.blockedReason,
           previousStatus: $existing.previousStatus,
           gitBranch: $existing.gitBranch,
           gitModified: $existing.gitModified,
           gitLines: $existing.gitLines
       } | with_entries(select(.value != null))] |
       .lastUpdated = $timestamp
       ' \
       --arg id "$window_id" \
       --arg terminal "$terminal" \
       --argjson window "$window_index" \
       --arg windowName "$window_name" \
       --arg status "$task_status" \
       --arg task "$task" \
       --arg worktree "$worktree" \
       --arg timestamp "$timestamp" \
       --arg developer "$developer" \
       --arg color "$color"
}

# Remove window from activeWindows (with file locking)
_kb_remove_window() {
    _kb_ensure_jq || return 1

    local context team terminal window_index window_name board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        return 1
    fi

    local window_id timestamp
    window_id=$(_kb_get_window_id "$terminal" "$window_name")
    timestamp=$(_kb_get_timestamp)

    # Remove with exclusive locking
    _kb_jq_update "$board_file" \
       '.activeWindows = [.activeWindows[] | select(.id != $id)] |
        .lastUpdated = $timestamp' \
       --arg id "$window_id" \
       --arg timestamp "$timestamp"
}

# ============================================================================
# Dependency Blocking Helpers (XACA-0020)
# ============================================================================

# Add a blocker to an item
# Usage: _kb_add_blocker <board_file> <item_id> <blocker_id>
# Adds blocker_id to item's blockedBy array, sets status to blocked
_kb_add_blocker() {
    local board_file="$1"
    local item_id="$2"
    local blocker_id="$3"

    local index timestamp
    index=$(_kb_find_by_id "$board_file" "$item_id")

    if [[ "$index" == "-1" ]]; then
        echo "Error: Item not found: $item_id" >&2
        return 1
    fi

    # Validate that blocker is not already resolved
    local blocker_status
    if _kb_is_subitem_id "$blocker_id"; then
        local blocker_indices
        blocker_indices=$(_kb_resolve_subitem_id "$board_file" "$blocker_id")
        if [[ "$blocker_indices" != "-1:-1" ]]; then
            local blocker_parent_idx="${blocker_indices%%:*}"
            local blocker_sub_idx="${blocker_indices##*:}"
            blocker_status=$(_kb_jq_read "$board_file" \
                ".backlog[$blocker_parent_idx].subitems[$blocker_sub_idx].status // empty" -r)
            if [[ "$blocker_status" == "completed" ]] || [[ "$blocker_status" == "cancelled" ]]; then
                echo "Error: Cannot block on already-resolved item/subitem $blocker_id (status: $blocker_status)" >&2
                return 1
            fi
        fi
    else
        blocker_status=$(_kb_jq_read "$board_file" \
            '.backlog[] | select(.id == $bid) | .status // empty' \
            --arg bid "$blocker_id" -r)
        if [[ "$blocker_status" == "completed" ]] || [[ "$blocker_status" == "cancelled" ]]; then
            echo "Error: Cannot block on already-resolved item/subitem $blocker_id (status: $blocker_status)" >&2
            return 1
        fi
    fi

    timestamp=$(_kb_get_timestamp)

    # Add blocker to blockedBy array (create if needed), set status to blocked
    _kb_jq_update "$board_file" '
        .backlog[$idx].blockedBy = ((.backlog[$idx].blockedBy // []) + [$blocker] | unique) |
        .backlog[$idx].status = "blocked" |
        .backlog[$idx].blockedAt //= $ts |
        .backlog[$idx].updatedAt = $ts |
        .lastUpdated = $ts
    ' --argjson idx "$index" \
      --arg blocker "$blocker_id" \
      --arg ts "$timestamp"
}

# Remove a blocker from an item
# Usage: _kb_remove_blocker <board_file> <item_id> <blocker_id>
# Removes blocker_id from item's blockedBy array
# If blockedBy becomes empty, sets status back to "todo"
_kb_remove_blocker() {
    local board_file="$1"
    local item_id="$2"
    local blocker_id="$3"

    local index timestamp
    index=$(_kb_find_by_id "$board_file" "$item_id")

    if [[ "$index" == "-1" ]]; then
        echo "Error: Item not found: $item_id" >&2
        return 1
    fi

    timestamp=$(_kb_get_timestamp)

    # Remove blocker from blockedBy array
    # If blockedBy becomes empty, change status from blocked to todo and clean up
    _kb_jq_update "$board_file" '
        .backlog[$idx].blockedBy = ((.backlog[$idx].blockedBy // []) - [$blocker]) |
        if (.backlog[$idx].blockedBy | length) == 0 then
            .backlog[$idx].status = "todo" |
            del(.backlog[$idx].blockedBy) |
            del(.backlog[$idx].blockedAt)
        else . end |
        .backlog[$idx].updatedAt = $ts |
        .lastUpdated = $ts
    ' --argjson idx "$index" \
      --arg blocker "$blocker_id" \
      --arg ts "$timestamp"
}

# Check and unblock dependents when an item is completed
# Usage: _kb_check_unblock_dependents <board_file> <completed_item_id>
# Finds all items blocked by the completed item and removes it from their blockedBy
_kb_check_unblock_dependents() {
    local board_file="$1"
    local resolved_id="$2"

    local timestamp unblocked_items
    timestamp=$(_kb_get_timestamp)

    # Find all items that have this resolved (completed OR cancelled) item in their blockedBy array
    # and remove it, potentially unblocking them
    unblocked_items=$(_kb_jq_update "$board_file" '
        .backlog = [.backlog[] |
            if (.blockedBy // []) | any(. == $resolvedId) then
                .blockedBy = (.blockedBy - [$resolvedId]) |
                if (.blockedBy | length) == 0 then
                    .status = "todo" |
                    del(.blockedBy) |
                    del(.blockedAt) |
                    .unblockedAt = $ts |
                    .updatedAt = $ts
                else
                    .updatedAt = $ts
                end
            else . end
        ] |
        .lastUpdated = $ts
    ' --arg resolvedId "$resolved_id" \
      --arg ts "$timestamp" 2>&1)

    # XACA-0025: Also unblock subitems that are blocked by the resolved (completed OR cancelled) item
    _kb_jq_update "$board_file" '
        .backlog = [.backlog[] |
            .subitems = [(.subitems // [])[] |
                if (.blockedBy // []) | any(. == $resolvedId) then
                    .blockedBy = (.blockedBy - [$resolvedId]) |
                    if (.blockedBy | length) == 0 then
                        .status = "todo" |
                        del(.blockedBy) |
                        del(.blockedAt) |
                        .unblockedAt = $ts |
                        .updatedAt = $ts
                    else
                        .updatedAt = $ts
                    end
                else . end
            ]
        ] |
        .lastUpdated = $ts
    ' --arg resolvedId "$resolved_id" \
      --arg ts "$timestamp" 2>&1

    # Return list of unblocked items for notification
    _kb_jq_read "$board_file" '
        [.backlog[] | select(.unblockedAt == $ts)] | map(.id) | join(", ")
    ' --arg ts "$timestamp" -r
}

# Add a blocker to a subitem (XACA-0025)
# Usage: _kb_add_subitem_blocker <board_file> <subitem_id> <blocker_id>
_kb_add_subitem_blocker() {
    local board_file="$1"
    local subitem_id="$2"
    local blocker_id="$3"

    local indices timestamp
    indices=$(_kb_resolve_subitem_id "$board_file" "$subitem_id")

    if [[ "$indices" == "-1:-1" ]]; then
        echo "Error: Subitem not found: $subitem_id" >&2
        return 1
    fi

    local parent_idx="${indices%%:*}"
    local sub_idx="${indices##*:}"

    # Validate that blocker is not already resolved
    local blocker_status
    if _kb_is_subitem_id "$blocker_id"; then
        local blocker_indices
        blocker_indices=$(_kb_resolve_subitem_id "$board_file" "$blocker_id")
        if [[ "$blocker_indices" != "-1:-1" ]]; then
            local blocker_parent_idx="${blocker_indices%%:*}"
            local blocker_sub_idx="${blocker_indices##*:}"
            blocker_status=$(_kb_jq_read "$board_file" \
                ".backlog[$blocker_parent_idx].subitems[$blocker_sub_idx].status // empty" -r)
            if [[ "$blocker_status" == "completed" ]] || [[ "$blocker_status" == "cancelled" ]]; then
                echo "Error: Cannot block on already-resolved item/subitem $blocker_id (status: $blocker_status)" >&2
                return 1
            fi
        fi
    else
        blocker_status=$(_kb_jq_read "$board_file" \
            '.backlog[] | select(.id == $bid) | .status // empty' \
            --arg bid "$blocker_id" -r)
        if [[ "$blocker_status" == "completed" ]] || [[ "$blocker_status" == "cancelled" ]]; then
            echo "Error: Cannot block on already-resolved item/subitem $blocker_id (status: $blocker_status)" >&2
            return 1
        fi
    fi

    timestamp=$(_kb_get_timestamp)

    # XACA-0029: Calculate and accumulate work time if actively working
    local work_started_at existing_time_ms total_time_ms
    work_started_at=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].workStartedAt // empty" -r)
    existing_time_ms=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].timeWorkedMs // 0")
    total_time_ms="$existing_time_ms"

    if [[ -n "$work_started_at" ]]; then
        # Calculate elapsed time in milliseconds
        local start_epoch now_epoch elapsed_ms
        # Strip Z suffix and parse as UTC (macOS date -j -f ignores timezone suffix)
        start_epoch=$(TZ=UTC date -j -f "%Y-%m-%dT%H:%M:%S" "${${work_started_at%\.[0-9]*}%Z}" "+%s" 2>/dev/null || echo "0")
        now_epoch=$(date -u "+%s")
        if [[ "$start_epoch" != "0" ]] && [[ "$start_epoch" -gt 0 ]]; then
            elapsed_ms=$(( (now_epoch - start_epoch) * 1000 ))
            total_time_ms=$(( existing_time_ms + elapsed_ms ))
        fi
    fi

    _kb_jq_update "$board_file" '
        .backlog[$pidx].subitems[$sidx].blockedBy = ((.backlog[$pidx].subitems[$sidx].blockedBy // []) + [$blocker] | unique) |
        .backlog[$pidx].subitems[$sidx].status = "blocked" |
        .backlog[$pidx].subitems[$sidx].blockedAt //= $ts |
        (if $timeMs != "0" then .backlog[$pidx].subitems[$sidx].timeWorkedMs = ($timeMs | tonumber) else . end) |
        del(.backlog[$pidx].subitems[$sidx].activelyWorking) |
        del(.backlog[$pidx].subitems[$sidx].workStartedAt) |
        del(.backlog[$pidx].subitems[$sidx].worktree) |
        del(.backlog[$pidx].subitems[$sidx].worktreeBranch) |
        del(.backlog[$pidx].subitems[$sidx].worktreeWindowId) |
        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
        .backlog[$pidx].updatedAt = $ts |
        .lastUpdated = $ts
    ' --argjson pidx "$parent_idx" \
      --argjson sidx "$sub_idx" \
      --arg blocker "$blocker_id" \
      --arg ts "$timestamp" \
      --arg timeMs "$total_time_ms"
}

# Remove a blocker from a subitem (XACA-0025)
# Usage: _kb_remove_subitem_blocker <board_file> <subitem_id> <blocker_id>
# If blockedBy becomes empty, sets status back to "todo"
_kb_remove_subitem_blocker() {
    local board_file="$1"
    local subitem_id="$2"
    local blocker_id="$3"

    local indices timestamp
    indices=$(_kb_resolve_subitem_id "$board_file" "$subitem_id")

    if [[ "$indices" == "-1:-1" ]]; then
        echo "Error: Subitem not found: $subitem_id" >&2
        return 1
    fi

    local parent_idx="${indices%%:*}"
    local sub_idx="${indices##*:}"
    timestamp=$(_kb_get_timestamp)

    _kb_jq_update "$board_file" '
        .backlog[$pidx].subitems[$sidx].blockedBy = ((.backlog[$pidx].subitems[$sidx].blockedBy // []) - [$blocker]) |
        if (.backlog[$pidx].subitems[$sidx].blockedBy | length) == 0 then
            .backlog[$pidx].subitems[$sidx].status = "todo" |
            del(.backlog[$pidx].subitems[$sidx].blockedBy) |
            del(.backlog[$pidx].subitems[$sidx].blockedAt)
        else . end |
        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
        .backlog[$pidx].updatedAt = $ts |
        .lastUpdated = $ts
    ' --argjson pidx "$parent_idx" \
      --argjson sidx "$sub_idx" \
      --arg blocker "$blocker_id" \
      --arg ts "$timestamp"
}

# ============================================================================
# Activity Logging Helpers (XACA-0117)
# ============================================================================
# Fire-and-forget activity logging. Board operations are NEVER blocked by
# activity logging failures — errors go to stderr only.

# Map an item ID to a team name.
# Accepts item IDs (XACA-0117) or subitem IDs (XACA-0117-003).
# Delegates to _kb_get_team_from_code which parses the X<CODE>-#### pattern.
# Usage: _kb_item_id_to_team <item_id>
# Returns: team name string, or empty string if unknown
_kb_item_id_to_team() {
    local item_id="$1"

    # For subitem IDs like XACA-0117-003, strip the trailing -NNN to get XACA-0117.
    # _kb_get_team_from_code needs the X<CODE>-#### format to match its regex.
    local lookup_id
    if _kb_is_subitem_id "$item_id" 2>/dev/null; then
        lookup_id="${item_id%-*}"   # XACA-0117-003 → XACA-0117
    else
        lookup_id="$item_id"
    fi

    # _kb_get_team_from_code handles X<CODE>-#### format (e.g. "XACA-0117" → "academy")
    _kb_get_team_from_code "$lookup_id"
}

# Resolve the activity directory for a given item ID, creating it if needed.
# Usage: _kb_get_activity_dir <item_id>
# Returns: absolute path to the activity/ directory, or empty string on failure
_kb_get_activity_dir() {
    local item_id="$1"

    local team
    team=$(_kb_item_id_to_team "$item_id")

    if [[ -z "$team" ]]; then
        echo "Warning: _kb_get_activity_dir: unknown team for item '$item_id'" >&2
        return 1
    fi

    local kanban_dir
    kanban_dir=$(_kb_get_kanban_dir "$team")

    local activity_dir="${kanban_dir}/activity"

    # Create the activity directory if it doesn't exist
    if [[ ! -d "$activity_dir" ]]; then
        mkdir -p "$activity_dir" 2>/dev/null || {
            echo "Warning: _kb_get_activity_dir: could not create '$activity_dir'" >&2
            return 1
        }
    fi

    echo "$activity_dir"
}

# Log a kanban activity event to the per-item activity JSON file.
# Fire-and-forget: failures warn to stderr but never block the caller.
#
# Usage: _kb_log_activity <action> <target_id> <target_type> [field] [old_value] [new_value] [context]
#
# Args:
#   action      - Event type: status_change | field_update | item_created |
#                 subitem_added | subitem_status_change | comment_added | etc.
#   target_id   - Item ID (XACA-0117) or subitem ID (XACA-0117-003)
#   target_type - "item" or "subitem"
#   field       - (optional) Field name that changed
#   old_value   - (optional) Previous value
#   new_value   - (optional) New value
#   context     - (optional) Additional context string
_kb_log_activity() {
    local action="$1"
    local target_id="$2"
    local target_type="$3"
    local field="${4:-}"
    local old_value="${5:-}"
    local new_value="${6:-}"
    local context="${7:-}"

    # Run in a subshell so any failure cannot affect the caller
    # Double-subshell idiom suppresses zsh job control notifications
    ( (
        # --- Resolve agent identity ---
        local agent_id
        if [[ -n "${CLAUDE_AGENT_HANDLE:-}" ]]; then
            agent_id="$CLAUDE_AGENT_HANDLE"
        elif [[ -n "${CLAUDE_CODENAME:-}" ]]; then
            agent_id="$CLAUDE_CODENAME"
        elif [[ -n "${LCARS_SESSION_NAME:-}" ]]; then
            agent_id="$LCARS_SESSION_NAME"
        else
            # Fallback: resolve from tmux session name via amb-session-map.json
            local _session_name _map_file
            _session_name=""
            if [[ -n "${TMUX_PANE:-}" ]]; then
                _session_name=$(tmux display-message -t "$TMUX_PANE" -p '#S' 2>/dev/null) || _session_name=""
            elif [[ -n "${TMUX:-}" ]]; then
                _session_name=$(tmux display-message -p '#S' 2>/dev/null) || _session_name=""
            fi
            _map_file="${AITEAMFORGE_DIR}/amb-session-map.json"
            if [[ -n "$_session_name" ]] && [[ -f "$_map_file" ]]; then
                agent_id=$(jq -r --arg s "$_session_name" '.[$s] // "unknown"' "$_map_file" 2>/dev/null) || agent_id="unknown"
            else
                agent_id="unknown"
            fi
        fi

        # --- Resolve parent item ID (strip subitem suffix if present) ---
        local parent_item_id
        if _kb_is_subitem_id "$target_id" 2>/dev/null; then
            # XACA-0117-003 → XACA-0117  (strip last -NNN segment)
            parent_item_id="${target_id%-*}"
        else
            parent_item_id="$target_id"
        fi

        # --- Resolve activity directory ---
        local activity_dir
        activity_dir=$(_kb_get_activity_dir "$parent_item_id") || {
            echo "Warning: _kb_log_activity: could not resolve activity dir for '$parent_item_id'" >&2
            exit 0
        }

        local activity_file="${activity_dir}/${parent_item_id}.json"
        local lock_file="${activity_file}.lock"

        # --- Build the new entry as JSON ---
        local timestamp
        timestamp=$(date -u +"%Y-%m-%dT%H:%M:%SZ")

        local entry
        entry=$(jq -n \
            --arg action     "$action" \
            --arg target_id  "$target_id" \
            --arg target_type "$target_type" \
            --arg field      "$field" \
            --arg old_value  "$old_value" \
            --arg new_value  "$new_value" \
            --arg agent_id   "$agent_id" \
            --arg context    "$context" \
            --arg ts         "$timestamp" \
            '{
                timestamp:  $ts,
                agent:      $agent_id,
                action:     $action,
                target:     $target_id,
                targetType: $target_type
            }
            | if $field      != "" then . + {field:    $field}      else . end
            | if $old_value  != "" then . + {oldValue: $old_value}  else . end
            | if $new_value  != "" then . + {newValue: $new_value}  else . end
            | if $context    != "" then . + {context:  $context}    else . end
            ') || {
            echo "Warning: _kb_log_activity: jq entry construction failed" >&2
            exit 0
        }

        # --- Write filter to temp file (avoid zsh BANG_HIST escaping issues) ---
        local filter_file
        filter_file=$(mktemp "${TMPDIR:-/tmp}/kb-activity-filter.XXXXXX") || {
            echo "Warning: _kb_log_activity: mktemp failed" >&2
            exit 0
        }

        # jq filter: create file on first write, otherwise append entry
        printf '%s' '
            . as $existing |
            if ($existing | type) == "object" and ($existing | has("entries")) then
                $existing
                | .entries += [$new_entry]
                | .lastUpdated = $ts
            else
                {
                    entries: [$new_entry],
                    itemId: $item_id,
                    created: $ts,
                    lastUpdated: $ts
                }
            end
        ' > "$filter_file"

        # XACA-0935 (BLOCKING finding): the tmp file MUST be minted in the
        # SAME directory as $activity_file, not under $TMPDIR.
        # _kb_jq_atomic_write's success path uses rename(), which is atomic
        # but -- unlike the `mv` this used to shell out to, which falls back
        # to copy+unlink across devices -- cannot cross a filesystem
        # boundary. $TMPDIR is tmpfs on most Linux hosts/containers
        # (invisible on macOS, where /tmp and the repo are typically the same
        # device), so a tmp file minted there and an activity_file living
        # under the kanban dir's activity/ subdirectory can land on different
        # devices there and rename() fails EXDEV -- silently, since this
        # whole call is 2>/dev/null'd below, destroying the audit entry with
        # no visible error. $activity_dir is guaranteed to exist by this
        # point (_kb_get_activity_dir mkdir -p's it above), so minting the
        # tmp file inside it keeps the rename same-device -- the same pattern
        # _kb_jq_update uses for the board file ("${board_file}.tmp").
        local tmp_file
        tmp_file=$(mktemp "${activity_dir}/.${parent_item_id}.json.XXXXXX") || {
            rm -f "$filter_file"
            echo "Warning: _kb_log_activity: mktemp for tmp_file failed" >&2
            exit 0
        }

        # --- Ensure activity file exists with valid JSON before locking ---
        if [[ ! -f "$activity_file" ]]; then
            printf '{}' > "$activity_file" 2>/dev/null
        fi
        touch "$lock_file" 2>/dev/null

        # --- Exclusive flock write (shared atomic-write primitive, XACA-0935) ---
        # Same underlying mechanism as _kb_jq_update (see _kb_jq_atomic_write
        # above): jq's argv -- including the --argjson new_entry payload,
        # which is UNCONDITIONALLY multi-line (the entry is built by `jq -n`
        # without -c at the call site above) -- is passed as a literal Perl
        # system(LIST), never through a shell, so the dash-mangles-$'...'
        # quoting defect this replaces cannot recur here either. Failure
        # remains non-fatal/best-effort: this whole function already runs in
        # a backgrounded subshell that always exit 0s, and the 2>/dev/null
        # below keeps the primitive's own "ERROR: ..." line invisible
        # exactly as the old script's "Warning: ..." line was -- only the
        # explicit warning on the next line is ever surfaced.
        _kb_jq_atomic_write "$lock_file" "$tmp_file" "$activity_file" \
            "_kb_log_activity: write failed" \
            jq --argjson new_entry "$entry" --arg ts "$timestamp" --arg item_id "$parent_item_id" \
            -f "$filter_file" "$activity_file" \
            2>/dev/null || \
            echo "Warning: _kb_log_activity: flock write failed for '$activity_file'" >&2

        rm -f "$filter_file" "$tmp_file" 2>/dev/null
        exit 0
    ) & ) 2>/dev/null

    return 0
}

# ============================================================================
# Public Commands
# ============================================================================

# Set window status
# Usage: kb-status <status>
# Status: paused | ready | planning | coding | testing | commit | pr_review
# Note: For paused status, prefer kb-pause "reason" which stores the reason and previous status
kb-status() {
    local task_status="$1"
    local valid_statuses=("paused" "ready" "planning" "coding" "testing" "commit" "pr_review")

    if [[ -z "$task_status" ]]; then
        echo "Usage: kb-status <status>"
        echo "Valid statuses: ${valid_statuses[*]}"
        return 1
    fi

    if [[ ! " ${valid_statuses[*]} " =~ " ${task_status} " ]]; then
        echo "Error: Invalid status '$task_status'"
        echo "Valid statuses: ${valid_statuses[*]}"
        return 1
    fi

    # Get current task to preserve it
    local context team terminal window_index board_file window_id current_task
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    current_task=$(_kb_jq_read "$board_file" '(.activeWindows[] | select(.id == $id) | .task) // ""' --arg id "$window_id" -r 2>/dev/null || echo "")

    # Capture old status and workingOnId for activity log
    local old_status working_on_id
    old_status=$(_kb_jq_read "$board_file" '(.activeWindows[] | select(.id == $id) | .status) // ""' --arg id "$window_id" -r 2>/dev/null || echo "")
    working_on_id=$(_kb_jq_read "$board_file" '(.activeWindows[] | select(.id == $id) | .workingOnId) // ""' --arg id "$window_id" -r 2>/dev/null || echo "")

    _kb_update_window "$task_status" "$current_task"
    echo "Status updated to: $task_status"

    # Activity log: status change (only if working on a tracked item)
    if [[ -n "$working_on_id" ]]; then
        _kb_log_activity "status_change" "$working_on_id" "item" "status" "$old_status" "$task_status" ""
    fi
}

# Set current task description
# Usage: kb-task "description"
kb-task() {
    local task="$1"

    if [[ -z "$task" ]]; then
        echo "Usage: kb-task \"task description\""
        return 1
    fi

    # Get current status to preserve it
    local context team terminal window_index window_name board_file window_id curr_status
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    curr_status=$(_kb_jq_read "$board_file" '(.activeWindows[] | select(.id == $id) | .status) // "coding"' --arg id "$window_id" -r 2>/dev/null || echo "coding")

    _kb_update_window "$curr_status" "$task"
    echo "Task set: $task"
}

# Clear window from board (removes it entirely)
# Usage: kb-clear
kb-clear() {
    _kb_remove_window
    echo "Window cleared from board"
}

# Shortcut: Start planning a task
# Usage: kb-plan "task description"
kb-plan() {
    local task="$1"
    if [[ -z "$task" ]]; then
        echo "Usage: kb-plan \"task description\""
        return 1
    fi

    _kb_update_window "planning" "$task"
    echo "Planning: $task"
}

# Shortcut: Move to coding (keeps current task)
# Usage: kb-code
kb-code() {
    kb-status "coding"
}

# Shortcut: Move to testing
# Usage: kb-test
kb-test() {
    kb-status "testing"
}

# Shortcut: Move to commit
# Usage: kb-commit
kb-commit() {
    kb-status "commit"
}

# Shortcut: Move to PR review
# Usage: kb-pr
kb-pr() {
    kb-status "pr_review"
}

# Block current task with a reason
# DEPRECATED: Use kb-pause instead
# Usage: kb-block "reason"
# Backward-compatibility alias - calls kb-pause
# Note: "blocked" is being renamed to "paused" to free up "blocked" for dependency system
kb-block() {
    echo "⚠️  DEPRECATED: kb-block is now kb-pause (blocked → paused)"
    echo "   The command still works, but please update your muscle memory!"
    echo ""
    kb-pause "$@"
}

# DEPRECATED: Use kb-resume instead
# Usage: kb-unblock
# Backward-compatibility alias - calls kb-resume
# Note: "blocked/unblock" is being renamed to "paused/resume"
kb-unblock() {
    echo "⚠️  DEPRECATED: kb-unblock is now kb-resume (unblock → resume)"
    echo "   The command still works, but please update your muscle memory!"
    echo ""
    kb-resume "$@"
}

# Pause current task with a reason (external wait - manual resume required)
# Usage: kb-pause "reason"
# Moves card to paused column, stores reason and previous status for resuming
# Also persists paused state to backlog item for survival across terminal restarts
# Note: PAUSED = external wait (manual resume). Different from future dependency-based blocking.
kb-pause() {
    local reason="$1"

    if [[ -z "$reason" ]]; then
        echo "Usage: kb-pause \"reason for pausing\""
        return 1
    fi

    local context team terminal window_index window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get current status to store as previousStatus
    local current_status
    current_status=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $id) | .status) // "coding"' \
        --arg id "$window_id" -r 2>/dev/null || echo "coding")

    # Don't allow pausing if already paused
    if [[ "$current_status" == "paused" ]]; then
        echo "Error: Already paused. Use kb-resume first to change the reason."
        return 1
    fi

    # Get the workingOnId to update the backlog item as well
    local working_on_id
    working_on_id=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $id) | .workingOnId) // ""' \
        --arg id "$window_id" -r 2>/dev/null || echo "")

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Update the window AND the backlog item: set status to paused, store reason and previous status
    # Persisting to backlog item allows paused state to survive terminal restarts
    _kb_jq_update "$board_file" '
        # Update the activeWindow
        .activeWindows = [.activeWindows[] |
            if .id == $id then
                .status = "paused" |
                .pausedReason = $reason |
                .previousStatus = $prevStatus |
                .lastActivity = $timestamp
            else
                .
            end
        ] |
        # Also update the backlog item (if workingOnId is set)
        (if $workingOnId != "" then
            # Try to find and update the item or subitem
            .backlog = [.backlog[] |
                if .id == $workingOnId then
                    # Direct match on parent item
                    .pausedReason = $reason |
                    .pausedAt = $timestamp |
                    .pausedPreviousStatus = $prevStatus |
                    .updatedAt = $timestamp
                elif (.subitems // []) | any(.id == $workingOnId) then
                    # Match on a subitem - update the subitem
                    .subitems = [(.subitems // [])[] |
                        if .id == $workingOnId then
                            .pausedReason = $reason |
                            .pausedAt = $timestamp |
                            .pausedPreviousStatus = $prevStatus |
                            .updatedAt = $timestamp
                        else . end
                    ]
                else . end
            ]
        else . end) |
        .lastUpdated = $timestamp
    ' \
    --arg id "$window_id" \
    --arg reason "$reason" \
    --arg prevStatus "$current_status" \
    --arg workingOnId "$working_on_id" \
    --arg timestamp "$timestamp"

    echo "⏸️  PAUSED: $reason"
    echo "   (was: $current_status)"
    if [[ -n "$working_on_id" ]]; then
        echo "   (persisted to backlog item: $working_on_id)"
    fi

    # Activity log: item paused (use working_on_id if available, else log as window action)
    if [[ -n "$working_on_id" ]]; then
        _kb_log_activity "paused" "$working_on_id" "item" "status" "$current_status" "paused" "$reason"
    fi
}

# ============================================================================
# Crash-Recovery Reconciliation Engine (XACA-0778-001)
# ============================================================================
#
# Problem: a Mac/tmux crash kills the tmux server without running the graceful
# kanban-stop.py reconciler. activeWindows[] pointers in the board orphan
# silently -- nothing cross-checks them against LIVE tmux. The PERSISTENT
# truth for "what was being worked on" is backlog[].status == "in_progress"
# (item-level) and backlog[].subitems[].status == "in_progress" (subitem-
# level); this engine classifies each one as BOUND (a live tmux window still
# backs it) or ORPHANED (it does not).
#
# This is a pure READ-ONLY classifier. It NEVER writes to the board and NEVER
# touches tmux beyond querying it. Status mutation / resume-manifest emission
# / re-binding are the concern of downstream subitems (kb-recover XACA-0778-
# 002, kb-resume-rebind XACA-0778-004) that consume this function's output --
# do not fold that logic in here.
#
# ----------------------------------------------------------------------------
# OUTPUT CONTRACT (STABLE -- XACA-0778-002/004/005 are written against this
# exact shape; changing field names/types here is a breaking change for all
# three):
#
#   _kb_reconcile_inprogress emits a JSON array on stdout, one object per
#   in_progress item/subitem:
#
#     {
#       "id":              string        -- item id ("XACA-0761") or subitem id ("XACA-0761-003")
#       "title":           string
#       "team":            string        -- team slug the board belongs to
#       "parentId":        string|null   -- parent item id if this is a subitem, else null
#       "worktree":        string|null   -- worktree path recorded on the item/subitem
#       "branch":          string|null   -- worktreeBranch recorded on the item/subitem
#       "planDocPath":     string|null   -- kb-plan-doc-path dir, ONLY if it exists on disk
#       "lastKnownWindow": string|null   -- XACA-0668 stable window-id key "terminal:window_name"
#       "classification":  "BOUND" | "ORPHANED"
#     }
#
#   BOUND    = lastKnownWindow resolved to a tmux window that (a) is alive
#              right now on a REACHABLE socket -- see the socket-resolution
#              ladder on _kb_tmux_live_window_ids below (XACA-0830 Defect A)
#              -- AND (b) has a live Claude process running in at least one
#              of its panes (XACA-0830 Defect B: a window that merely still
#              EXISTS -- e.g. Claude was killed by jetsam and the pane
#              dropped to an idle shell prompt -- no longer counts).
#   ORPHANED = in_progress but no live-and-Claude-backed tmux window backs
#              it -- dead pointer, no pointer at all, a window that exists
#              but has no live Claude process in it (Defect B), or every
#              socket the resolution ladder tried was genuinely UNREACHABLE
#              (tmux missing, or truly nothing answered -- the real
#              post-crash case, NOT merely "the caller had no ambient
#              $TMUX", which was Defect A's actual failure mode pre-XACA-0830).
#              UNREACHABLE and REACHABLE-but-empty are now DISTINGUISHABLE
#              internally via _kb_tmux_live_window_ids's return code (see
#              below) even though both still classify ORPHANED here today --
#              conflating them silently is exactly what let Defect A hide
#              undetected for so long.
#
#   lastKnownWindow resolution priority per item:
#     1. the item/subitem's own .worktreeWindowId field (persistent -- lives
#        in board.json, survives a crash because it isn't tmux-derived).
#     2. fallback: an activeWindows[] entry whose .workingOnId == this id,
#        using that entry's .id (covers older items started before
#        worktreeWindowId existed).
# ----------------------------------------------------------------------------

# Internal: does ANY pid in whitespace-separated pane-pid list "$1" have a
# live Claude process among its descendants? (XACA-0830 Defect B /
# subitem 004.) Multi-pane windows: ANY pane running Claude makes the
# window live -- a pane layout can split a window into a Claude pane plus
# scratch/log panes, and the window is genuinely "in use" as long as one of
# them is Claude. That is a deliberate choice, documented here rather than
# picked silently.
#
# Liveness is determined by walking each pane's process DESCENDANTS, not by
# trusting #{pane_current_command} alone -- verified live on this machine
# (2026-07-29): a real academy Claude pane's OWN #{pane_current_command}
# reports a bare version string (e.g. "2.1.220"), never the literal string
# "claude", while `ps -o comm=` on that same pane's pane_pid's CHILD process
# shows COMM=claude. The shell in the pane (pane_pid) is the parent; Claude
# is a child (occasionally a grandchild, behind a wrapper) of it. A plain
# idle shell pane (verified against a real academy pane with nothing but a
# zsh prompt running in it) has zero such descendants.
#
# XACA-0830-004 PERFORMANCE (reopened a second time -- measured, not
# guessed: academy's 17 windows cost 17 `ps` forks and 17 `tmux list-panes`
# calls before this fix, ~9.8s just for _kb_tmux_live_window_ids, blowing
# past lcars-ui/server.py's 20s subprocess timeout on a slower run). This
# function no longer shells out to `tmux list-panes` itself, and
# _kb_pid_has_claude_descendant (below) no longer takes its own `ps`
# snapshot. Both now read PRE-BUILT, dynamically-scoped state --
# `_kb_tlwi_comm_of` / `_kb_tlwi_args_of` / `_kb_tlwi_children_map` /
# `_kb_tlwi_assume_live` -- that _kb_tmux_live_window_ids builds EXACTLY
# ONCE per call (one `tmux list-panes -a` for every pane on the whole
# socket, one `ps -eo ...` snapshot for the whole process table) and leaves
# in scope for this function and _kb_pid_has_claude_descendant via zsh's
# dynamic `local` scoping: those four names are declared `local` in
# _kb_tmux_live_window_ids and deliberately NEVER re-declared in this
# function or in _kb_pid_has_claude_descendant, so the whole call chain
# shares the SAME instances instead of re-fetching them per pane. See
# _kb_tmux_live_window_ids for where they're built and the TIE-BREAK logic
# (unchanged in spirit, just evaluated once per call instead of once per
# pane): if the snapshot/enumeration tooling was unavailable or failed,
# `_kb_tlwi_assume_live=1` and this function returns "live" immediately
# without touching the (empty) maps.
_kb_tmux_window_has_live_claude() {
    local pane_pids_str="${1-}"
    (( _kb_tlwi_assume_live )) && return 0   # tooling unavailable this call -> assume live, see TIE-BREAK on _kb_tmux_live_window_ids

    local pane_pid
    for pane_pid in ${=pane_pids_str}; do
        [[ -n "$pane_pid" ]] || continue
        _kb_pid_has_claude_descendant "$pane_pid" && return 0
    done
    return 1   # every pane in this window checked against the shared snapshot, no Claude anywhere -> genuinely dead
}

# Internal: bounded breadth-first scan of pid "$1"'s process descendants
# (depth- and visited-count-capped -- defends against pid-recycling cycles
# on a long-lived box) for a process that IS Claude. Checks the root pid
# itself too (harmless, and covers the edge case where Claude runs directly
# as the pane's foreground process with no wrapper shell in between).
#
# CHILD ENUMERATION -- `ps`, NOT `pgrep -P` (XACA-0830-004, reopened after
# review). The original implementation walked the tree with `pgrep -P
# "$pid"` per visited node. That has a reproducible ANCESTRY BLIND SPOT:
# `pgrep -P <pid>` returns EMPTY for a live child that is the CALLING
# process's own ancestor. Verified directly on this machine (5 consecutive
# samples, not a race):
#     pgrep -P 80878                       -> []            (WRONG -- misses it)
#     ps -eo pid=,ppid= | awk '$2==80878'  -> 90295          (correct)
#     ps -o comm=,args= -p 90295           -> claude / claude --permission-mode ...
#     ancestry: 90295 (claude) is a direct PARENT of the very process
#     evaluating this classifier (the classifier is running AS a Claude
#     Code session's subagent, whose ancestry chain runs back through that
#     same pane's Claude process).
# The practical consequence: `kb-recover`/`kb-sweep` invoked from a user's
# OWN pane would misclassify THAT pane's OWN, currently-alive window as
# ORPHANED -- Defect A reintroduced in the single most common invocation
# shape there is, and the exact failure direction to guard against (a
# broken check returning the reassuring-looking answer). `ps -eo` has no
# such blind spot -- confirmed it sees 90295 as 80878's child correctly.
#
# Fix (first pass): take ONE system-wide `ps -eo pid=,ppid=,comm=,args=`
# snapshot per call (not one ps/pgrep invocation per visited node), parse
# it into a ppid -> children-pid-list map plus per-pid comm/args lookups,
# and walk that in memory. `ps` reliably keeps one process per output line
# even when a process's own argv contains embedded newlines (verified
# against a real Claude process carrying a multi-line --append-system-
# prompt: `ps -eo ...` line count matched `ps -eo pid= | wc -l` exactly,
# and the reconstructed args value's byte length matched a direct
# single-pid `ps -o args= -p <pid>` almost exactly) -- so `${(f)$(...)}`
# newline-splitting the snapshot is safe.
#
# PERFORMANCE (second pass, XACA-0830-004 reopened again): "per call" above
# used to mean "per PANE" -- this function originally took its OWN `ps`
# snapshot every time it ran, and it runs once per pane. Measured on
# academy (17 windows): 17 `ps` forks, ~0.16s each, ~9.8s just for
# _kb_tmux_live_window_ids -- on a slower run this exceeded
# lcars-ui/server.py's 20s subprocess timeout outright, so the very
# consumer this whole ticket exists for could no longer call it
# successfully. The snapshot is now taken ONCE per _kb_tmux_live_window_ids
# CALL (not per pane) and shared down the call chain via zsh dynamic
# scoping -- see the comment on `_kb_tmux_window_has_live_claude` above and
# `_kb_tmux_live_window_ids` below for where `_kb_tlwi_comm_of` /
# `_kb_tlwi_args_of` / `_kb_tlwi_children_map` / `_kb_tlwi_assume_live` are
# actually built. This function is now PURE in-memory BFS -- it makes no
# `ps`/`pgrep`/`tmux` calls of its own at all. The snapshot is a
# POINT-IN-TIME view taken once at the start of the call; a pane whose
# Claude process dies mid-scan (between the snapshot and this walk) is
# classified from that snapshot, not from live state a few milliseconds
# later -- an acceptable, deliberate tradeoff for a read-only classifier
# that runs on a period poll, not a hard real-time liveness guarantee.
#
# Match rule (XACA-0830-020 review: NARROWED, then REOPENED and fixed twice
# more -- the any-token-anywhere shape this replaced was itself a
# false-positive source; the two narrower shapes that followed each broke
# on a DIFFERENT input the previous verification pass never exercised).
# `$comm_base` exactly "claude" (covers both a bare `claude` PATH lookup,
# where `comm` is already just "claude", and a full-path invocation like
# "/usr/local/bin/claude" -- both collapse to the same basename check) OR:
# `$comm_base` names a known shell/script interpreter
# (sh/bash/zsh/dash/ksh/python/python3/node/ruby/perl) AND the `args=`
# string, with the known `$comm` value stripped off its front as a literal
# (non-glob) prefix, STARTS WITH a path whose final component is "claude"
# -- the interpreted-wrapper shape, e.g. a real invocation
# "/bin/sh /path/to/bin/claude" or the standard npm-global Claude Code
# shape "/opt/homebrew/.../bin/node /opt/homebrew/.../bin/claude".
#
# THIRD-PASS FIX (current): `$comm` and the `args=` string used above both
# come from the two-snapshot, REST-OF-LINE-preserving parse documented on
# `_kb_tmux_live_window_ids` (search that function for "TWO SNAPSHOTS") --
# `comm` is read alone (`ps -eo pid=,comm=`, always the LAST column, never
# truncated) and `args` from a separate call with `comm` omitted entirely
# (`ps -eo pid=,ppid=,args=`, `args` again the LAST column). Neither value
# is ever produced by word-splitting a combined line. This matters because
# the SECOND pass's fix -- word-splitting `args=` into positional tokens
# via `${=args}` -- still broke, on a DIFFERENT input than what exposed the
# first pass's bug: an interpreter path containing a SPACE (verified live,
# real fixture, not a hypothetical -- this machine's actual node binary
# lives at "/Users/.../Library/Application Support/Herd/.../node") splits
# mid-path, so `argv[0]` as reconstructed from tokens becomes
# "/Users/.../Application" and the interpreter-basename check never sees
# "node" at all. The underlying defect was the same both times: treating a
# `ps` line (or a `ps`-derived string containing embedded spaces) as a
# blindly-splittable token stream instead of "one opaque value that may
# itself contain spaces". Fixed by never tokenizing `args` here either:
# `$comm` (untruncated, exact exec path) is stripped off the FRONT of
# `args` by CHARACTER-COUNT substring slicing (not pattern-based prefix
# removal, which would misread glob-special characters in a real path),
# and the remainder is pattern-matched only at its OWN START for a
# claude-ending path -- never scanned for "claude" appearing anywhere
# later in the line. This deliberately does NOT attempt to isolate argv[1]
# as a single discrete token (impossible in general if argv[1] itself
# contains a space, the exact class of bug this pass exists to close) --
# instead it asks a narrower, sufficient question: does the text
# immediately following the interpreter look like a path ending in
# "claude", terminated by end-of-string or the next argument boundary? See
# the implementation below for the exact anchoring and why it still
# excludes `vim claude` / `grep -rn claude .` (both have a `comm` that
# isn't in the interpreter list, so the whole branch never runs for them,
# independent of anything after that in their argv).
#
# What this deliberately does NOT do: scan every whitespace-separated
# token in the full command line for a "claude" basename anywhere (the
# original, first-pass shape). That false-positived on any process whose
# argv merely MENTIONS the word in an unrelated position -- reviewer-
# verified live: `grep -rn claude .` and `vim claude` both registered as a
# live Claude pane under that shape (false BOUND). `comm` alone is also
# insufficient on its own: tmux's own #{pane_current_command} can report
# something else entirely for a live Claude pane (observed, independently
# reconfirmed: `pane_cmd=2.1.220` on real live Claude panes, never the
# literal word "claude") -- this function deliberately does NOT use
# #{pane_current_command} at all, only `ps`, for that reason. Tradeoff
# accepted: a wrapper that inserts extra flags BEFORE the script path
# (e.g. `/bin/sh -x /path/to/bin/claude`) is not matched (the remainder
# after stripping the interpreter starts with "-x", not a claude-ending
# path) -- no such shape has been observed in this fleet; if one appears,
# the fix is to also skip a `-x`/flag-shaped leading token before applying
# the anchor, not to revert to a blanket token scan. The whole scan stays
# PID-scoped to this pane's own descendant tree via the ppid map, never a
# system-wide process-name search (a system-wide `pgrep -f claude` would
# false-positive on Claude Desktop's own helper processes, unrelated
# `claude` CLI invocations elsewhere on the box, etc. -- see real output
# captured during XACA-0830 verification).
_kb_pid_has_claude_descendant() {
    local root_pid="${1-}"
    [[ -n "$root_pid" ]] || return 1
    (( _kb_tlwi_assume_live )) && return 0   # tooling unavailable this call -> assume live, see TIE-BREAK above

    # BFS over the CALLER-BUILT, dynamically-scoped
    # `_kb_tlwi_children_map`/`_kb_tlwi_comm_of`/`_kb_tlwi_args_of` (no
    # ps/pgrep/tmux calls in this function at all -- see the PERFORMANCE
    # comment above). Loop-body locals declared once, before the loop.
    local -a queue=("$root_pid") next_queue
    local -i depth=0 visited=0 match
    local cur_pid child_pid comm comm_base full_args remainder
    # XACA-0830-020 (review, FOURTH pass -- see the "(b) interpreted-
    # wrapper" comment below this loop for the full story). Anchored
    # regex, not a zsh glob: `^(claude|[^[:space:]]+/claude)([[:space:]]|$)`
    # matches ONLY at the very start of `$remainder` (regex `^`, a true
    # anchor) -- either the bare word "claude" or a slash-terminated path
    # segment "claude" with no whitespace before the slash, followed by
    # either a space (next argument boundary) or end-of-string. Declared
    # once here, not inline in the loop body, matching this file's own
    # house style for `=~`-style patterns (see `ps_re_args`/`ps_re_comm`
    # on `_kb_tmux_live_window_ids`).
    local claude_re='^(claude|[^[:space:]]+/claude)([[:space:]]|$)'

    while (( ${#queue[@]} > 0 && depth < 6 && visited < 200 )); do
        next_queue=()
        for cur_pid in "${queue[@]}"; do
            [[ -n "$cur_pid" ]] || continue
            (( visited++ ))

            comm="${_kb_tlwi_comm_of[$cur_pid]-}"
            comm_base="${comm:t}"

            # (a) direct invocation: the exec'd path/name's own basename is
            # "claude" -- covers a bare `claude` lookup (comm already ==
            # "claude") and a full-path invocation like
            # "/usr/local/bin/claude" alike. `comm` here is the value built
            # by the two-snapshot parse above (`_kb_tlwi_comm_of`), always
            # UNTRUNCATED (see that snapshot's BUDGET/PARSING comment) and
            # equal to the exec path as passed to execve -- this single
            # check is a strictly more complete replacement for the old
            # separate "raw comm == claude" + "argv[0] basename == claude"
            # tests, now redundant with it.
            [[ "$comm_base" == "claude" ]] && return 0

            # (b) interpreted-wrapper. XACA-0830-020, THIRD review pass.
            # Both prior passes derived the interpreter identity and/or the
            # script path by WORD-SPLITTING the `args=` string (first via
            # `${_kb_tlwi_comm_of[...]:t}`, wrong because that read a
            # middle-column-truncated `comm`; then via `${=args}` /
            # positional-array indexing into a blind split, wrong because a
            # space embedded INSIDE one argv element is indistinguishable
            # from a space SEPARATING two argv elements once everything is
            # joined onto one `ps args=` line). Verified live, the exact
            # shape this ticket keeps rediscovering: this machine's real
            # node lives at "/Users/.../Library/Application
            # Support/Herd/.../node" (a space, mid-path) -- word-splitting
            # `args` for that process put "Application" where the
            # interpreter basename should be, never "node".
            #
            # Fixed by never tokenizing `args` at all. `$comm` (this
            # iteration's untruncated interpreter path, from the SAME
            # two-snapshot parse) already carries the interpreter's exec
            # path verbatim, spaces included. `ps -o args=` renders
            # argv0..argvN joined by single spaces IN ORDER, so if this
            # process really is "$comm $argv1 $argv2 ...", `args` MUST
            # begin with the literal `$comm` string. Strip that off as a
            # known-LENGTH prefix via character-count substring slicing
            # (`${full_args[1,${#comm}]}` / `${full_args[${#comm}+1,-1]}`)
            # -- not pattern-based prefix removal (`${var#$pattern}`),
            # which would misinterpret any glob-special character that
            # happens to appear in a real path (e.g. "*", "["). Whatever
            # remains after that prefix (plus exactly one separating space)
            # is "argv1 onward" -- itself still not safely tokenizable if
            # argv1 ALSO contains a space, so this deliberately does NOT
            # try to isolate argv1 as a single discrete token either.
            # Instead it pattern-matches the START of that remainder only:
            # does the text immediately following the interpreter look
            # like a path whose FINAL component is "claude", terminated
            # either by end-of-string or by a following space (the next
            # argument boundary)?
            #
            # XACA-0830-020, FOURTH review pass -- the THIRD pass's match
            # used a zsh GLOB, not a real anchor, and the comment here
            # asserted anchoring the glob did not actually provide:
            #   (claude|claude[[:space:]]*|*/claude|*/claude[[:space:]]*)
            # The first two alternatives ARE anchored (no leading `*`). The
            # last two are NOT: a leading `*` in a zsh glob matches
            # anything, including further spaces and slashes, so
            # `*/claude` means "ends with /claude" and
            # `*/claude[[:space:]]*` means "contains /claude ANYWHERE" --
            # both scan the WHOLE remainder, not just its start. In
            # practice this collapsed rule (b) back down to "comm is an
            # interpreter AND the command line mentions a /claude path
            # anywhere" -- the original any-token-anywhere false-positive,
            # reintroduced in the FALSE-BOUND direction, one glob-anchoring
            # mistake away from the exact bug this whole rule exists to
            # prevent. Verified live: `/bin/sh -c vim /Users/me/bin/claude`
            # and `/bin/sh -c 'sleep 25; : /tmp/fx/bin/claude'` both matched
            # under the old glob (comm="sh", but the /claude path is an
            # ARGUMENT to some other command entirely, not the script being
            # interpreted) -- and the round-3 verification never caught it
            # because its one adversarial case (`grep -rn claude .`)
            # happens to have no `/` immediately before "claude", the one
            # shape the broken alternatives don't false-positive on.
            #
            # Fixed with a real regex anchor (`$claude_re`, declared once
            # above this loop): `^(claude|[^[:space:]]+/claude)([[:space:]]|$)`.
            # `^` anchors to the actual start of `$remainder` (a true
            # regex anchor, unlike a glob's leading `*`). The alternation
            # is "claude" alone, or a slash-terminated path segment ending
            # in "claude" with NO whitespace between the slash and the
            # start of remainder (`[^[:space:]]+/claude` -- deliberately
            # NOT `.*`/`*`, which would reopen the same unanchored-scan
            # hole this pass exists to close), followed by a space or
            # end-of-string. TRADEOFF, deliberately accepted: a claude
            # SCRIPT PATH containing an embedded space no longer matches
            # (`[^[:space:]]+` forbids it) -- this is different from, and
            # does NOT affect, the space-containing INTERPRETER path from
            # the prior pass (this machine's real 95-char Herd node path):
            # that value is `$comm`, stripped off the FRONT of `args`
            # BEFORE this regex ever runs, so a space there was never
            # visible to `$claude_re` in the first place -- re-verified
            # live after this change, that fixture still resolves BOUND.
            # No script-path-with-space shape has been observed in this
            # fleet; if one appears, the fix is to loosen the character
            # class for that one alternative, not to revert to a scan.
            # Re-verified `vim claude` and `grep -rn claude .` both still
            # fail this cleanly (comm_base is "vim"/"grep", neither is in
            # the interpreter case list below, so this whole branch never
            # runs for them regardless of anything in their argv) --
            # unaffected by this pass, since the false-positive fix for
            # THAT shape lives in the `case` gate below, not in
            # `$claude_re` itself.
            #
            # XACA-0830-026 (review, re-checked against THIS mechanism,
            # third pass): does reading `$comm` from the new two-snapshot,
            # untruncated parse change the outcome for macOS Homebrew
            # FRAMEWORK Python, whose exec identity reports capitalized
            # "Python"? Re-verified live and still NO -- `ps -eo
            # pid=,comm=` (the exact call this loop's `$comm` now comes
            # from) reports
            # ".../Resources/Python.app/Contents/MacOS/Python" for a plain
            # `python3 script.py` invocation, same capitalization as
            # before. This was never a truncation artifact to begin with
            # (re-confirmed in the prior pass): framework Python re-execs
            # itself through an internal launcher stub that rewrites its
            # OWN exec identity, independent of which `ps` column or
            # snapshot strategy reads it. `node` re-checked side-by-side,
            # still does not exhibit this. DELIBERATELY STILL NOT WIDENED
            # to also match "Python"/"Python3": no evidence anywhere in
            # this fleet of Claude Code (a Node.js CLI) ever being
            # Python-wrapped; the python/python3 entries were speculative
            # coverage from the start. If a real python-wrapped `claude`
            # shape ever surfaces, the fix is a one-line case-insensitive
            # glob (zsh `(#i)` qualifier) on this `case`, not a growing
            # enumeration -- still deferred, documented gap, not silently
            # dropped.
            match=0
            case "$comm_base" in
                sh|bash|zsh|dash|ksh|python|python3|node|ruby|perl)
                    full_args="${_kb_tlwi_args_of[$cur_pid]-}"
                    if [[ -n "$comm" && "${full_args[1,${#comm}]}" == "$comm" ]]; then
                        remainder="${full_args[${#comm}+1,-1]}"
                        remainder="${remainder# }"
                        [[ "$remainder" =~ $claude_re ]] && match=1
                    fi
                    ;;
            esac
            (( match )) && return 0

            for child_pid in ${=${_kb_tlwi_children_map[$cur_pid]-}}; do
                next_queue+=("$child_pid")
            done
        done
        queue=("${next_queue[@]}")
        (( depth++ ))
    done
    return 1
}

# Internal (XACA-0830-002): run a single tmux probe under a bounded wall-
# clock deadline, so a socket file that accepts the connection but never
# speaks tmux's protocol (a hostile or merely-foreign listener bound to a
# path under tmux's socket dir) cannot hang the classifier forever. Rung 4
# of the ladder below connects to EVERY socket file it finds -- there is no
# guarantee any of them is actually a tmux server -- and a plain
# `tmux -S <sock> list-sessions` against such a listener blocks
# indefinitely: confirmed live with a Python AF_UNIX listener that binds +
# listens but never responds (see retro). Rungs 2/3 carry the identical
# exposure (an inherited $TMUX_SOCKET/$TMUX can point anywhere), so every
# probe in the ladder goes through here, not just rung 4's.
#
# No dependency on `timeout`/`gtimeout` -- macOS ships neither by default.
# Implemented with zsh's own `zselect` module (zsh/zselect, part of every
# zsh 5.x used here): a sibling watchdog subshell blocks in zsh's event
# loop via `zselect -t <centiseconds>` (no external exec) and SIGKILLs the
# probe if it's still running when the deadline hits. Whichever side
# finishes first wins; the loser is reaped immediately either way -- no
# process is left resident (verified via `ps` count before/after, see
# retro "constraint 4").
#
# TRI-STATE PRESERVED: a timed-out probe returns a KILLED (nonzero, 128+9)
# exit code -- the exact same shape a real "connection refused" already
# produces. Every call site's existing `(( $? == 0 )) || continue`
# fall-through therefore needs no changes: a timeout degrades into "try the
# next rung", never into "reached, and confirmed empty". Mistaking a
# timeout for a confirmed-empty REACHABLE result would reintroduce Defect A
# in a new costume -- see the TRI-STATE CONTRACT above
# _kb_tmux_live_window_ids.
#
# XACA-0830-018 (review): `zmodload zsh/zselect` CAN fail (module absent
# from a given zsh build/install). The original code swallowed the load
# failure and unconditionally set the "loaded" flag anyway, so every later
# call still tried to run the bare `zselect` command -- which, missing the
# module, is a plain "command not found" that fails IMMEDIATELY rather than
# blocking for the deadline. That means the watchdog subshell's `kill -KILL`
# line ran almost instantly instead of after `$timeout_cs`, SIGKILLing the
# real probe within milliseconds of starting it -- the exact same
# "guard reports success when it could not do its job" shape as the
# ticket's other defects, this time producing MASS FALSE UNREACHABLE (every
# probe looks "reached, timed out" when the real command never got a chance
# to answer). Fixed by checking zmodload's own exit status and falling back
# to a `sleep`-based watchdog (documented fallback, no module dependency --
# `sleep` accepts fractional seconds on both macOS/BSD and GNU coreutils)
# when the module genuinely isn't available.
#
# Usage: _kb_tmux_bounded_probe <timeout_centiseconds> <command...>
_kb_tmux_bounded_probe() {
    local -i timeout_cs="${1:-0}"
    (( timeout_cs > 0 )) || return 1
    shift
    (( $# > 0 )) || return 1

    if [[ -z "${_KB_TLWI_ZSELECT_LOADED:-}" ]]; then
        if zmodload zsh/zselect 2>/dev/null; then
            typeset -g _KB_TLWI_ZSELECT_LOADED=1
        else
            typeset -g _KB_TLWI_ZSELECT_LOADED=0
        fi
    fi

    local tmpfile
    tmpfile=$(mktemp "${TMPDIR:-/tmp}/kb-tmux-probe.XXXXXX" 2>/dev/null) || return 1

    "$@" >"$tmpfile" 2>/dev/null &
    local -i cmd_pid=$!

    if (( _KB_TLWI_ZSELECT_LOADED )); then
        ( zselect -t "$timeout_cs" 2>/dev/null; kill -KILL "$cmd_pid" 2>/dev/null ) &
    else
        # Fallback watchdog: no zsh/zselect module available. `sleep` takes
        # a plain floating-point argument on both macOS/BSD and GNU
        # coreutils -- timeout_cs is centiseconds, so divide by 100. (the
        # trailing dot forces zsh floating-point division; `local -i` is NOT
        # used for sleep_secs, it must stay a float.)
        local sleep_secs=$(( timeout_cs / 100. ))
        ( sleep "$sleep_secs" 2>/dev/null; kill -KILL "$cmd_pid" 2>/dev/null ) &
        # KNOWN, ACCEPTED LIMITATION (review, non-blocking): the zselect
        # path below is a zsh BUILTIN with no fork of its own, so killing
        # $watchdog_pid terminates it immediately. `sleep`, in contrast, is
        # a real forked/exec'd grandchild of $watchdog_pid -- SIGKILLing
        # the parent subshell does NOT kill it, so if the real probe
        # finishes early, this fallback leaves an orphaned `sleep` running
        # for up to the remainder of $sleep_secs (bounded by
        # PROBE_TIMEOUT_CS, i.e. <=1.5s at the default) before it exits on
        # its own. It reparents to launchd/init and is reaped normally --
        # not a zombie, not a leak, invisible to `pgrep -P $$` precisely
        # because it's no longer this process's child by the time anything
        # would check. Deliberately NOT chasing this down further (e.g.
        # tracking the sleep's own pid across the subshell boundary) --
        # this path only runs at all when zsh/zselect is unavailable, which
        # is itself the rare case, and the cost is a single short-lived
        # `sleep` process, not a resource leak. Not worth the added
        # complexity for a self-terminating, sub-2-second grandchild.
    fi
    local -i watchdog_pid=$!

    wait "$cmd_pid" 2>/dev/null
    local -i rc=$?

    kill -KILL "$watchdog_pid" 2>/dev/null
    wait "$watchdog_pid" 2>/dev/null

    cat "$tmpfile" 2>/dev/null
    rm -f "$tmpfile" 2>/dev/null
    return $rc
}

# Internal: resolve which tmux SOCKET actually hosts <team>'s sessions, then
# emit the set of LIVE, Claude-backed tmux window keys ("terminal:window_name",
# the XACA-0668 stable window-id) for that team, one per line. Reverses the
# SAME session-name convention _kb_detect_context uses to derive
# team/terminal: session = "<team>-<terminal>" (terminal = suffix after the
# LAST dash; team = everything before it -- correct even when team itself
# contains dashes, e.g. "freelance-doublenode-starwords").
#
# Usage: _kb_tmux_live_window_ids <team> [explicit_socket]
#   team             required.
#   explicit_socket  optional -L socket NAME. A caller that already knows
#                     which socket hosts this team can short-circuit the
#                     whole resolution ladder below by passing it (rung 1).
#
# SOCKET RESOLUTION LADDER (XACA-0830 Defect A). Teams run on NAMED tmux
# sockets, never the default one -- and parametric teams (runtime slug e.g.
# "legal-coparenting") run on their FAMILY socket ("legal"), not a socket
# matching the slug. A bare, unqualified `tmux` command only resolves
# correctly from INSIDE a live pane (where $TMUX tells it which socket);
# any other caller (cron, a detached subagent shell, kb-recover run from a
# plain terminal) used to hit tmux's default socket, find nothing, and
# report every in_progress item ORPHANED -- Defect A. The ladder below is
# tried in order until one candidate BOTH connects AND hosts a session
# matching this team's predicate:
#   1. $explicit_socket (caller-supplied -L name)
#   2. $TMUX_SOCKET, if set -- every team's *-startup.sh exports this
#      before opening any tmux tab/window.
#   3. the socket embedded in $TMUX itself (path before the first comma --
#      $TMUX is e.g. "/private/tmp/tmux-502/academy,80261,2")
#   4. scan every socket file in tmux's socket dir and ask each one "do you
#      host a session for this team" (the genuinely-detached case: no tmux
#      env at all -- launchd, cron, CI, a Claude Code hook)
#   5. bare tmux (default socket) -- last resort / backward compat, same as
#      the pre-XACA-0830 behavior.
#
# Rungs 2 and 3 are UNVERIFIED TRUST -- an inherited $TMUX_SOCKET/$TMUX can
# point at a real, reachable socket that hosts a DIFFERENT team (e.g. a
# subagent spawned from an academy pane, asked to classify team "ios"). If a
# candidate socket is reachable but hosts no session matching this team's
# predicate, we FALL THROUGH to the next rung rather than concluding
# "nothing is live" -- trusting a set-but-wrong env var would just
# reproduce Defect A in a new costume.
#
# RETURN-CODE / TRI-STATE CONTRACT:
#   0  REACHABLE.  At least one candidate socket in the ladder was
#      successfully queried (`tmux ... list-sessions` succeeded). Stdout is
#      the (possibly EMPTY) set of live+Claude-backed window ids. Empty
#      stdout + exit 0 means "I looked, and nothing is live" -- a confirmed
#      negative, not a failure to look.
#   1  UNREACHABLE. tmux isn't installed, OR every rung in the ladder failed
#      to connect to a socket at all, OR (XACA-0830-022/024) the rung-4
#      socket-directory scan was cut short by its overall deadline before
#      every candidate could be probed -- a truncated scan cannot honestly
#      claim "confirmed empty", even if an earlier, unrelated-team socket
#      happened to answer along the way. Stdout is empty. Callers must NOT
#      treat this the same as a confirmed-empty REACHABLE result when they
#      care about the distinction (see _kb_reconcile_inprogress below) --
#      conflating the two is precisely what let Defect A hide for so long.
#      This never raises an error; it degrades quietly ($TMUX-strict-mode
#      safe: no unset-variable references, no non-zero exit surprises for
#      set -u callers).
# TIE-BREAK (the label six comments in this file point at; it had no
# definition until XACA-0830 round 6 -- the references were dangling, which
# is its own small instance of a pointer that looks resolved and is not):
#
#   When the PROCESS-INSPECTION tooling itself cannot do its job -- `ps`
#   missing, either snapshot empty, either snapshot truncated or exiting
#   non-zero, or panes that cannot be enumerated -- `_kb_tlwi_assume_live`
#   is set and every window in the already-enumerated set is treated as
#   LIVE rather than dead.
#
#   Direction, and why: the two ways to be wrong are not symmetric.
#     * Assume-dead on tooling failure => mass false ORPHANED. That is
#       Defect A, the bug this whole ticket exists for, and it invites the
#       operator to run `kb-resume`, which MUTATES board state. Wrong and
#       destructive.
#     * Assume-live on tooling failure => a false BOUND, but ONLY for the
#       Defect-B subclass (the window genuinely exists; we merely could not
#       confirm whether Claude is still in it). It CANNOT manufacture a
#       window: the emitted set is still exactly what `list-panes -a`
#       reported, so the post-crash "window is gone entirely" case that
#       kb-recover primarily exists to surface is unaffected. Nothing
#       destructive consumes an ORPHANED result -- LCARS displays it and
#       crash-detect gates a nudge on count>0. Wrong and quiet.
#
#   Wrong-and-mutating is worse than wrong-and-quiet, so assume-live wins.
#   Note this is a TIE-BREAK on TOOLING failure only -- it is NOT the same
#   axis as the REACHABLE/UNREACHABLE tri-state above, which is about
#   whether the tmux SOCKET could be reached. A caller can get rc=0
#   (reachable) with assume_live set, and that combination is deliberate.
_kb_tmux_live_window_ids() {
    local team="${1-}"
    local explicit_socket="${2-}"
    [[ -n "$team" ]] || return 1
    command -v tmux >/dev/null 2>&1 || return 1

    # Build the candidate ladder as parallel flag/value arrays (rungs 1-5,
    # in priority order). Declared once, not inside any loop.
    local -a cand_flags=() cand_values=()

    [[ -n "$explicit_socket" ]] && { cand_flags+=("-L"); cand_values+=("$explicit_socket") }
    [[ -n "${TMUX_SOCKET-}" ]] && { cand_flags+=("-L"); cand_values+=("$TMUX_SOCKET") }
    if [[ -n "${TMUX-}" ]]; then
        local tmux_sock_path="${TMUX%%,*}"
        [[ -n "$tmux_sock_path" ]] && { cand_flags+=("-S"); cand_values+=("$tmux_sock_path") }
    fi

    # Rung 4: every live socket in tmux's socket dir -- the genuinely-
    # detached case (no tmux env at all: launchd, cron, CI, a hook). Zero
    # config, no team->family mapping, no path resolution across dev-vs-
    # consumer installs; generalizes the existing session-name predicate
    # instead of adding a second source of truth (see XACA-0830-007 recon:
    # a first-dash-split family mapping is an unenforced coincidence of
    # today's roster and was explicitly rejected as the primary mechanism).
    #
    # rung4_first_idx/rung4_last_idx (XACA-0830-002) bracket this rung's
    # slice of the flattened cand_flags/cand_values arrays so the main loop
    # below can enforce an OVERALL wall-clock deadline across the whole
    # rung-4 scan, not just a per-socket one -- see the "Budget arithmetic"
    # comment on that loop for why a per-probe cap alone is not enough.
    local -i rung4_first_idx=$(( ${#cand_flags[@]} + 1 ))
    local tmux_sockdir
    tmux_sockdir="${TMUX_TMPDIR:-/tmp}/tmux-$(id -u)"
    if [[ -d "$tmux_sockdir" ]]; then
        setopt LOCAL_OPTIONS NO_NOMATCH BARE_GLOB_QUAL
        local -a tmux_sockfiles
        local tmux_sockfile
        tmux_sockfiles=("${tmux_sockdir}"/*(N))
        for tmux_sockfile in "${tmux_sockfiles[@]}"; do
            [[ -S "$tmux_sockfile" ]] || continue
            cand_flags+=("-S"); cand_values+=("$tmux_sockfile")
        done
    fi
    local -i rung4_last_idx=${#cand_flags[@]}   # < rung4_first_idx means zero rung-4 candidates found

    cand_flags+=("")   # rung 5: bare tmux, last resort / backward compat
    cand_values+=("")

    # XACA-0830-002 BUDGET ARITHMETIC (Defect A re-emergence: rung-4 hang).
    # lcars-ui/server.py calls this whole function with a 20s subprocess
    # timeout. Every probe below is bounded via _kb_tmux_bounded_probe (see
    # that function's header for the mechanism) at PROBE_TIMEOUT_CS
    # centiseconds each, and the rung-4 socket-dir scan additionally carries
    # its own overall deadline (RUNG4_DEADLINE_S) so a directory full of
    # hostile/foreign sockets can't multiply (per-socket cap) x (socket
    # count) into a budget blowout on its own -- this machine currently has
    # 16 socket files; tomorrow it could have 40.
    #   PROBE_TIMEOUT_CS  = 150   (1.5s)  -- generous for a real tmux server
    #                                        under load; only the
    #                                        pathological "connected but
    #                                        never responds" case ever pays
    #                                        this in full (a dead socket /
    #                                        no listener fails in ~0s, well
    #                                        under the cap -- see
    #                                        Verification B).
    #   RUNG4_DEADLINE_S  = 6           -- caps the WHOLE rung-4 scan
    #                                        regardless of socket count.
    # Worst case: rungs 1-3 (up to 3 candidates, each capped) + rung 4
    # (capped as a whole) + rung 5 (1 candidate, capped) + the one
    # post-match list-panes probe (also capped) =
    #   (3 * 1.5s) + 6s + 1.5s + 1.5s = 13.5s
    # -- comfortably inside the 20s budget (6.5s margin for the ps snapshot,
    # JSON serialization, and everything else _kb_reconcile_inprogress /
    # the caller does around this call).
    local -i _kb_tlwi_probe_timeout_cs=${KB_TMUX_PROBE_TIMEOUT_CS:-150}
    local -i _kb_tlwi_rung4_deadline_s=${KB_TMUX_RUNG4_DEADLINE_S:-6}
    local -i _kb_tlwi_rung4_scan_start=0
    # XACA-0830 BLOCKER FIX (review, PR #730): $SECONDS is a legitimate value
    # of 0 for a shell's ENTIRE FIRST SECOND -- and lcars-ui/server.py spawns
    # the classifier as a freshly-forked `zsh -c`, so SECONDS==0 is the
    # COMMON case for the exact caller this deadline exists to protect, not
    # an edge case. `_kb_tlwi_rung4_scan_start > 0` as the "clock started"
    # sentinel is therefore ambiguous with "clock started at t=0" and never
    # fires for that population -- verified directly: fresh `zsh -c` shell,
    # SECONDS still 0 after sourcing this file. A dedicated armed flag
    # (set once, independent of the clock's actual value) replaces the
    # overloaded-zero sentinel.
    local -i _kb_tlwi_rung4_armed=0
    local -i _kb_tlwi_rung4_truncated=0

    # Loop-body locals declared ONCE before the loop (zsh: re-declaring
    # `local` inside a loop body can leak the assignment expression to
    # stdout on some zsh versions -- see kanban-helpers.sh house style).
    local -i reached=1   # flips to 0 the moment ANY candidate is queried successfully
    local -i i any_session_for_team
    local flag value session sess_terminal sess_team wname
    local -a tmux_args sessions windows

    # XACA-0830-004 PERFORMANCE (reopened a second time): once a candidate
    # socket is confirmed to host this team (any_session_for_team=1), the
    # OLD code called `list-windows` once per matching session and then
    # `list-panes` once per window inside THAT -- measured on academy (5
    # sessions, 17 windows): 5 list-windows + 17 list-panes + 17 per-pane
    # `ps` snapshots (see _kb_pid_has_claude_descendant) = ~38 tmux
    # invocations + 17 ps forks per call, ~9.8s, occasionally exceeding
    # lcars-ui/server.py's 20s subprocess timeout outright. Fixed by
    # collapsing ALL of that into: one `tmux list-panes -a` (every pane on
    # the whole socket, in one call -- also removes the need for a separate
    # `list-windows` call, since list-panes -a already reports each pane's
    # session/window name) + one `ps -eo ...` snapshot, both taken once
    # below and shared down the call chain via zsh dynamic `local` scoping
    # (`_kb_tlwi_*` -- see _kb_tmux_window_has_live_claude /
    # _kb_pid_has_claude_descendant above, which deliberately do NOT
    # re-declare these names so they see this exact instance). Declared
    # here, once, before the candidate loop -- populated only for the ONE
    # candidate that ends up matching (this loop returns immediately after,
    # so it can never populate them twice).
    local -A _kb_tlwi_comm_of _kb_tlwi_args_of _kb_tlwi_children_map
    local -i _kb_tlwi_assume_live=0
    local -A window_panes_map
    local -a panes_raw ps_snapshot ps_snapshot_comm
    local -i panes_rc
    local pane_line pane_combined pane_pid pane_session pane_window
    local pane_sess_terminal pane_sess_team window_key
    local ps_line ps_pid ps_ppid
    # XACA-0830-020 (third pass): REGEX patterns for the two-snapshot,
    # REST-OF-LINE-preserving `ps` parse -- see the BUDGET/PARSING comment
    # at the snapshot call site below for why these exist and are declared
    # ONCE here rather than inline in the loop body (house style: avoid
    # re-declaring `local` inside a loop body).
    local ps_re_args='^[[:space:]]*([0-9]+)[[:space:]]+([0-9]+)[[:space:]]*(.*)$'
    local ps_re_comm='^[[:space:]]*([0-9]+)[[:space:]]+(.*)$'

    for (( i = 1; i <= ${#cand_flags[@]}; i++ )); do
        # Rung-4 overall deadline (XACA-0830-002, see BUDGET ARITHMETIC
        # above): start the clock the moment we enter rung 4's index range,
        # and once RUNG4_DEADLINE_S has elapsed, skip straight to rung 5
        # instead of probing any further rung-4 candidates one at a time.
        # $SECONDS is a zsh special parameter (elapsed whole seconds since
        # shell start) -- no fork required to read it, unlike `date`.
        if (( rung4_last_idx >= rung4_first_idx && i == rung4_first_idx )); then
            _kb_tlwi_rung4_scan_start=$SECONDS
            _kb_tlwi_rung4_armed=1
        fi
        if (( _kb_tlwi_rung4_armed && i >= rung4_first_idx && i <= rung4_last_idx )); then
            if (( SECONDS - _kb_tlwi_rung4_scan_start >= _kb_tlwi_rung4_deadline_s )); then
                # XACA-0830-024: the rung-4 scan is being cut short with
                # candidates still un-probed. Record that fact so the
                # ladder-exhausted fallback below (and, transitively,
                # _kb_reconcile_inprogress's live_reachable) does not report
                # a confirmed-empty REACHABLE result off an incomplete scan
                # -- see the return-code logic after this loop.
                _kb_tlwi_rung4_truncated=1
                i=rung4_last_idx
                continue
            fi
        fi

        flag="${cand_flags[i]}"
        value="${cand_values[i]}"
        tmux_args=()
        [[ -n "$flag" ]] && tmux_args=("$flag" "$value")

        sessions=("${(f)$(_kb_tmux_bounded_probe "$_kb_tlwi_probe_timeout_cs" tmux "${tmux_args[@]}" list-sessions -F '#{session_name}')}")
        (( $? == 0 )) || continue   # this candidate is unreachable (or timed out) -- try the next rung
        reached=0

        any_session_for_team=0
        for session in "${sessions[@]}"; do
            [[ -n "$session" ]] || continue
            sess_team="${session%-*}"
            [[ "$sess_team" == "$team" ]] || continue
            any_session_for_team=1
        done

        if (( any_session_for_team )); then
            # ONE call for every pane on this whole socket (all sessions,
            # not just this team's -- cheap and avoids an extra per-session
            # round trip; irrelevant panes are filtered out below by the
            # same session-name predicate used everywhere else in this
            # function).
            # XACA-0830-019 (review): the format string puts the
            # VARIABLE-LENGTH field (session:window, and window names CAN
            # contain spaces) last, and #{pane_pid} (always exactly one
            # numeric token) first. `read -r pane_pid pane_combined` then
            # relies on `read`'s own last-variable behavior -- the final
            # named variable absorbs the REST of the line verbatim (internal
            # whitespace preserved), so a window name containing a space no
            # longer gets truncated/misparsed the way it did with the
            # fixed-field-first ordering. Verified against a window
            # literally named "myte st".
            panes_raw=("${(f)$(_kb_tmux_bounded_probe "$_kb_tlwi_probe_timeout_cs" tmux "${tmux_args[@]}" list-panes -a -F '#{pane_pid} #{session_name}:#{window_name}')}")
            panes_rc=$?

            window_panes_map=()
            if (( panes_rc == 0 )); then
                for pane_line in "${panes_raw[@]}"; do
                    [[ -n "$pane_line" ]] || continue
                    pane_pid="" pane_combined=""
                    read -r pane_pid pane_combined <<< "$pane_line"
                    [[ -n "$pane_combined" && -n "$pane_pid" ]] || continue
                    pane_session="${pane_combined%%:*}"
                    pane_window="${pane_combined#*:}"
                    pane_sess_terminal="${pane_session##*-}"
                    pane_sess_team="${pane_session%-*}"
                    [[ "$pane_sess_team" == "$team" ]] || continue
                    # NOTE (real zsh gotcha, caught in XACA-0830-004
                    # verification): the subscript must be a BARE variable
                    # reference here, NOT a quoted `"${a}:${b}"` expression
                    # inline in the assignment -- `map["${a}:${b}"]=x` on
                    # this zsh (5.9) stores the LITERAL quote characters as
                    # part of the key (verified via `typeset -p`), so every
                    # later lookup/iteration comes back with stray `"..."`
                    # wrapped around the key. Compute the key into its own
                    # variable first, then use it unquoted as the subscript.
                    window_key="${pane_sess_terminal}:${pane_window}"
                    window_panes_map[$window_key]+="$pane_pid "
                done
            fi

            # Build the shared process snapshot ONCE for this call. Point-
            # in-time: taken here, before the BFS walks below, so a pane
            # whose Claude process dies between this snapshot and the walk
            # is classified from the snapshot -- acceptable for a
            # periodic-poll classifier, not a hard real-time guarantee.
            _kb_tlwi_assume_live=0
            _kb_tlwi_comm_of=() _kb_tlwi_args_of=() _kb_tlwi_children_map=()
            if (( panes_rc != 0 )); then
                _kb_tlwi_assume_live=1   # couldn't even enumerate panes -> assume live, see TIE-BREAK
            elif ! command -v ps >/dev/null 2>&1; then
                _kb_tlwi_assume_live=1   # tooling unavailable -> assume live, see TIE-BREAK
            else
                # TWO SNAPSHOTS (XACA-0830-020, THIRD review pass). The
                # previous single combined `ps -eo pid=,ppid=,comm=,args=`
                # call is fundamentally unsound: `comm` and `args` can both
                # contain spaces (a real, live example on this machine:
                # node installed by Herd at
                # "/Users/.../Library/Application Support/Herd/.../node"),
                # and there is no way to reliably tell "a space that
                # separates two ps COLUMNS" from "a space that is part of
                # one column's own VALUE" once everything has been joined
                # onto one line and blind-split on whitespace -- whichever
                # column comes first eats extra tokens it shouldn't, and
                # every column after it shifts. This bit twice: first as
                # `comm=` truncating to 16 chars as a MIDDLE column
                # (XACA-0830-020 second pass), now as a plain word-splitting
                # bug even after that was fixed (`${cmd_tokens[1]}` split
                # mid-path on the embedded space, yielding "Application"
                # instead of the actual interpreter basename "node").
                # BOTH bugs share one root cause: treating a `ps` line as a
                # blindly-splittable token stream instead of "N fixed
                # single-token fields, then the true REST OF THE LINE".
                # Fixed structurally, not patched again: take `comm` and
                # `args` from SEPARATE `ps` calls, each with the
                # space-containing field placed LAST (`ps` does not
                # truncate a LAST column, confirmed live: 16-char-truncated
                # as a middle column vs. the same process's full path when
                # `comm=` is the only/last field requested) and parsed via
                # a REGEX capturing "leading numeric field(s), then
                # everything else" -- never `${=line}` word-splitting or
                # positional-array indexing into a blind split, for either
                # call. Two `ps` forks instead of one; measured cost of the
                # extra call ~0.04s on this machine (full system-wide
                # snapshot), and the regex-based parse is not a regression
                # either -- benchmarked at ~0.02s+0.01s for both snapshots
                # combined on a ~1150-line system-wide table, actually
                # *faster* than the `read -r ... <<<` approach this file
                # deliberately moved away from in XACA-0830-004 (0.26s) and
                # comparable to the word-splitting approach that approach
                # replaced it with (0.01s) -- `[[ str =~ pattern ]]` is a
                # zsh builtin regex evaluation, no per-line fork/here-string
                # setup either way. Total added latency is well inside the
                # existing ~12-28x margin under lcars-ui/server.py's 20s
                # subprocess timeout (re-verified after this change).
                # Capture each `ps` EXIT STATUS, not just its output
                # (XACA-0830-027). These were the only 2 of 7 external calls
                # in this function whose rc was discarded. Emptiness alone is
                # not a sufficient signal: a TRUNCATED snapshot (ps emits some
                # lines, then fails) leaves element [1] populated, sails past
                # the guard below, and silently drops whichever pids never got
                # written -- including, possibly, the live claude we are
                # looking for. That yields ORPHANED with an empty stderr: the
                # same reassuring-wrong-answer shape this whole ticket is
                # about. zsh preserves $? across the array assignment (the
                # command substitution is the last thing evaluated), so
                # capture it on the very next line -- NOT after any other
                # command, and never through a pipe (`$?` after `cmd | tail`
                # is tail's status).
                ps_snapshot=("${(f)$(ps -eo pid=,ppid=,args= 2>/dev/null)}")
                local -i ps_rc_args=$?
                ps_snapshot_comm=("${(f)$(ps -eo pid=,comm= 2>/dev/null)}")
                local -i ps_rc_comm=$?
                # BOTH snapshots must be tested, not just the first. XACA-0830
                # round-5: the guard originally checked only `ps_snapshot`.
                # `_kb_tlwi_comm_of` is populated exclusively from
                # `ps_snapshot_comm`, and it is the sole source of `$comm` for
                # BOTH match rules -- so if the second `ps` returned nothing
                # while the first succeeded, the comm loop iterated an empty
                # array, every lookup missed, `_kb_tlwi_assume_live` was never
                # armed, and EVERY window classified dead. Worse, the caller
                # had already succeeded at `list-sessions`/`list-panes`, so
                # `_kb_tmux_live_window_ids` returned 0 and `kb-recover` set
                # live_reachable=1 -- SUPPRESSING the "tmux state could not be
                # confirmed" caveat while reporting everything ORPHANED. That
                # is Defect A with its own warning switched off, and it
                # violates this file's TRI-STATE CONTRACT (see ~2926-2929:
                # failed snapshot tooling must arm assume_live).
                # Guard on BOTH emptiness AND exit status, for BOTH snapshots.
                # A non-zero rc with partial output is the truncation case
                # described above; emptiness alone would miss it.
                if [[ -z "${ps_snapshot[1]-}" || -z "${ps_snapshot_comm[1]-}" ]] \
                   || (( ps_rc_args != 0 || ps_rc_comm != 0 )); then
                    _kb_tlwi_assume_live=1   # ps produced nothing usable, or failed part-way -> assume live, see TIE-BREAK
                else
                    # `ps_re_args` captures: (1) pid, (2) ppid, (3) the
                    # REST OF THE LINE verbatim as `args` -- group 3 starts
                    # right after the mandatory pid/ppid separator and
                    # includes every remaining character, embedded spaces
                    # included. `[[:space:]]*` (not `+`) before group 3
                    # tolerates a process with genuinely empty args (no
                    # trailing separator at all) without failing the whole
                    # match. Assigned to a variable (declared once, above
                    # this candidate loop -- see house style note there),
                    # not inlined at the `=~` call site, per zsh's own
                    # recommended idiom for patterns containing characters
                    # `=~`'s glob-flavored inline-pattern parsing could
                    # otherwise misinterpret.
                    for ps_line in "${ps_snapshot[@]}"; do
                        [[ -n "$ps_line" ]] || continue
                        [[ "$ps_line" =~ $ps_re_args ]] || continue
                        ps_pid="${match[1]}"
                        ps_ppid="${match[2]}"
                        _kb_tlwi_children_map[$ps_ppid]+="$ps_pid "
                        _kb_tlwi_args_of[$ps_pid]="${match[3]}"
                    done
                    # `ps_re_comm` captures: (1) pid, (2) the REST OF THE
                    # LINE verbatim as `comm` -- `comm` is requested here as
                    # the ONLY other field besides `pid`, i.e. it is always
                    # the LAST column, which `ps` does not truncate
                    # (confirmed live: the identical process's `comm`
                    # truncates to 16 chars when requested as a middle
                    # column alongside `ppid=,args=`, but comes back full
                    # when requested alone like this).
                    #
                    # NOTE (real zsh gotcha, same class as the one already
                    # documented on `window_panes_map` above, caught here
                    # live during XACA-0830-020 third-pass verification --
                    # every entry silently unreadable despite the map's
                    # `${#...}` size growing correctly): the subscript MUST
                    # be a bare variable reference, NOT a quoted
                    # `"${match[1]}"` expression inline in the assignment --
                    # `map["${match[1]}"]=x` on this zsh (5.9) stores the
                    # LITERAL QUOTE CHARACTERS as part of the key (confirmed
                    # via a targeted debug trace: the map's element COUNT
                    # incremented on every iteration, but a subsequent
                    # lookup by the clean, unquoted pid -- `$cur_pid` in
                    # `_kb_pid_has_claude_descendant` -- came back empty
                    # every time; entries existed under a mangled key, not
                    # a missing one). Extract into its own variable first,
                    # then use it UNQUOTED as the subscript, exactly like
                    # the pid/ppid loop just above this one already does.
                    for ps_line in "${ps_snapshot_comm[@]}"; do
                        [[ -n "$ps_line" ]] || continue
                        [[ "$ps_line" =~ $ps_re_comm ]] || continue
                        ps_pid="${match[1]}"
                        _kb_tlwi_comm_of[$ps_pid]="${match[2]}"
                    done
                fi
            fi

            if (( panes_rc != 0 )); then
                # Extremely rare: list-sessions on this socket just
                # succeeded, but the immediately-following list-panes -a
                # failed. We still know WHICH sessions match (from the
                # loop above) but have no pane data -- fall back to a
                # plain per-session list-windows call, bounded to this one
                # already-confirmed socket, purely to learn window NAMES so
                # they can still be emitted. Liveness is "assume live" for
                # all of them via _kb_tlwi_assume_live above, matching the
                # pre-existing per-window tie-break for this failure shape.
                for session in "${sessions[@]}"; do
                    [[ -n "$session" ]] || continue
                    sess_terminal="${session##*-}"
                    sess_team="${session%-*}"
                    [[ "$sess_team" == "$team" ]] || continue
                    windows=("${(f)$(_kb_tmux_bounded_probe "$_kb_tlwi_probe_timeout_cs" tmux "${tmux_args[@]}" list-windows -t "$session" -F '#{window_name}')}")
                    for wname in "${windows[@]}"; do
                        [[ -n "$wname" ]] || continue
                        printf '%s:%s\n' "$sess_terminal" "$wname"
                    done
                done
            else
                for window_key in "${(k)window_panes_map[@]}"; do
                    _kb_tmux_window_has_live_claude "${window_panes_map[$window_key]}" || continue
                    printf '%s\n' "$window_key"
                done
            fi
        fi

        # This candidate socket genuinely hosts (a) session(s) for this
        # team -- it IS the team's socket, whether or not any window on it
        # turned out to be live+Claude-backed. Stop the ladder here; do NOT
        # keep trying further rungs (that would risk picking up an
        # unrelated team's stray session on a later candidate).
        (( any_session_for_team )) && return 0
        # else: reachable but hosts none of this team's sessions -- fall
        # through to the next rung rather than concluding "nothing is
        # live" (see UNVERIFIED TRUST above).
    done

    # Exhausted every rung without finding a socket that hosts this team.
    #
    # XACA-0830-022/024 (same fix; -022's failure shape is subsumed by -024's
    # truncation tracking): `reached` alone is not sufficient evidence of a
    # confirmed-empty result. `reached` flips to 0 the moment ANY candidate
    # answers -- including a rung-2/3 socket that turns out to host a
    # DIFFERENT team (UNVERIFIED TRUST, see header comment above). If that
    # happens and the team's OWN socket lives in rung 4 but the rung-4 scan
    # is then cut short by the overall deadline before reaching it
    # (_kb_tlwi_rung4_truncated), the old code still reported REACHABLE
    # (confirmed empty) purely off the earlier wrong-team hit -- a scan that
    # never actually checked the team's real socket masquerading as "I
    # checked, nothing's there". Gate the confirmed-empty verdict on the
    # scan having run to completion: a truncated rung-4 scan degrades to
    # UNREACHABLE instead, so callers treat it as "I could not fully look"
    # rather than "I looked and it's clear" (see TRI-STATE CONTRACT above
    # and _kb_reconcile_inprogress's live_reachable handling).
    if (( reached == 0 )); then
        (( _kb_tlwi_rung4_truncated )) && return 1
        return 0   # REACHABLE somewhere, confirmed empty for this team
    fi
    return 1                          # UNREACHABLE: nothing in the ladder ever connected
}

# Internal: resolve a plan-doc directory for an item/subitem id IF it exists
# on disk, else emit nothing. kb-plan-doc-path only accepts parent-item shape
# (XABC-1234, no subitem suffix) since plan docs live at the parent
# granularity -- callers must pass the PARENT id for subitems.
_kb_reconcile_plan_doc_path() {
    local parent_id="${1-}"
    [[ -n "$parent_id" ]] || return 0
    local p
    p=$(kb-plan-doc-path "$parent_id" 2>/dev/null) || return 0
    [[ -n "$p" && -d "$p" ]] && printf '%s' "$p"
    return 0
}

# The reconciliation engine. Pure read-only classifier -- see OUTPUT CONTRACT
# above. NEVER mutates the board and NEVER mutates tmux.
#
# Usage: _kb_reconcile_inprogress <team> [board_file]
#   team        Team slug (required -- used both to resolve the default board
#               file and to scope the live-tmux-session match).
#   board_file  Optional override (defaults to `_kb_get_board_file <team>`).
#
# Emits a JSON array on stdout (see contract). Emits "[]" (not an error) for
# a missing/unreadable board file -- a team with no board has no in_progress
# work to reconcile.
#
# STDOUT IS A STABLE JSON CONTRACT (three consumers: XACA-0778-002/004/005)
# -- nothing below may print anything else to stdout. XACA-0830-021/015: the
# tmux-reachability distinction (see the RETURN-CODE / TRI-STATE CONTRACT on
# _kb_tmux_live_window_ids) is real, useful operator information -- "I
# checked, nothing's orphaned" vs "I could not check tmux at all" -- but it
# cannot be added as a field on the per-item result object without breaking
# that contract. It is instead surfaced OUT OF BAND on STDERR (see the
# live_reachable block below): every call site in this file captures this
# function via `$(...)` command substitution, which forks a genuine
# subshell -- a `typeset -g` write from inside that subshell (tried first,
# during development of this fix) is invisible to the caller once the
# subshell exits, since command substitution only pipes back STDOUT, not
# process memory. STDERR, unlike a global variable, is a real file
# descriptor shared with the parent and survives the subshell boundary
# intact -- confirmed the only channel that actually works here without
# restructuring every call site off `$(...)` capture. `kb-recover --json` /
# `kb-reconcile-inprogress --json` never touch stderr for this -- they stay
# byte-clean JSON on stdout exactly as before; the caveat line only ever
# lands on stderr, whether or not the caller asked for --json.
_kb_reconcile_inprogress() {
    local team="${1-}"
    local board_file="${2-}"

    if [[ -z "$team" ]]; then
        echo "Usage: _kb_reconcile_inprogress <team> [board_file]" >&2
        return 1
    fi

    if [[ -z "$board_file" ]]; then
        board_file=$(_kb_get_board_file "$team" 2>/dev/null)
    fi

    if [[ -z "$board_file" || ! -f "$board_file" ]]; then
        echo "[]"
        return 0
    fi

    # Single locked read: every in_progress item AND in_progress subitem,
    # with lastKnownWindow resolved per the priority rule documented above.
    # win_for($id) is the activeWindows[] fallback (priority 2).
    local candidates
    candidates=$(_kb_jq_read "$board_file" '
        (.activeWindows // []) as $windows
        | def win_for($id): (($windows | map(select(.workingOnId == $id)) | first) // {}).id // null;
        (
            [ (.backlog // [])[] | select(.status == "in_progress") | {
                id: .id,
                title: .title,
                parentId: null,
                worktree: (.worktree // null),
                branch: (.worktreeBranch // null),
                lastKnownWindow: (.worktreeWindowId // win_for(.id))
              }
            ]
        ) + (
            [ (.backlog // [])[] as $parent
              | (($parent.subitems // [])[] | select(.status == "in_progress")) as $sub
              | {
                  id: $sub.id,
                  title: $sub.title,
                  parentId: $parent.id,
                  worktree: ($sub.worktree // $parent.worktree // null),
                  branch: ($sub.worktreeBranch // $parent.worktreeBranch // null),
                  lastKnownWindow: ($sub.worktreeWindowId // win_for($sub.id))
                }
            ]
        )
    ' -c 2>/dev/null)

    if [[ -z "$candidates" || "$candidates" == "null" ]]; then
        echo "[]"
        return 0
    fi

    # Live, Claude-backed tmux window set for this team (XACA-0830: already
    # resolved through the socket ladder and filtered by process liveness --
    # see _kb_tmux_live_window_ids). Empty is a valid, expected result and
    # NOT a fatal condition -- but it now has two genuinely distinct causes,
    # DISTINGUISHABLE via the function's own return code even though this
    # reconciler maps both to the same ORPHANED classification below today:
    #   rc=0 (REACHABLE), empty output -- we successfully reached a tmux
    #        socket that either belongs to this team or was the last rung
    #        tried, and confirmed nothing is live for this team right now.
    #        This is the real post-crash case (tmux server down, or every
    #        Claude for this team has genuinely exited).
    #   rc=1 (UNREACHABLE) -- nothing in the whole XACA-0830 socket-
    #        resolution ladder could be reached at all (tmux missing, or a
    #        deeply broken environment). Conflating this with the confirmed-
    #        empty case above -- treating "I could not look" the same as "I
    #        looked and it's clear" -- is EXACTLY what let Defect A hide
    #        undetected for so long: a bare `tmux` call with no ambient
    #        $TMUX used to silently degrade into this bucket even when a
    #        real, reachable, team-owned socket existed. $live_reachable is
    #        captured here so a future non-breaking consumer (e.g. an LCARS
    #        "liveness check degraded" banner) can key off it without
    #        touching the STABLE output contract documented above -- it is
    #        deliberately NOT added as a JSON field on the per-item result
    #        object in this pass.
    #
    # XACA-0830-021/015 (review): this used to be dead -- captured, never
    # read by anything. UX separately filed that an operator running
    # kb-recover has no way to tell "I checked, nothing orphaned" from "I
    # could not check tmux at all" -- both render identically today. Fix
    # both by publishing the value to STDERR (see the STDOUT-CONTRACT
    # comment above this function for why stderr, not a global variable, is
    # the only channel that survives the `$(...)` subshell every call site
    # uses to capture this function). kb-recover's human-readable path
    # relies on this line reaching the terminal/caller's stderr as-is; it
    # does NOT re-derive or duplicate the check itself.
    local live_windows live_reachable live_rc
    live_windows=$(_kb_tmux_live_window_ids "$team")
    live_rc=$?
    [[ $live_rc -eq 0 ]] && live_reachable=1 || live_reachable=0
    if (( ! live_reachable )); then
        echo "kb-recover: tmux state could not be confirmed for team '$team' (socket ladder unreachable/truncated) -- ORPHANED results below may be incomplete" >&2
    fi

    # Loop-body locals declared ONCE before the loop (zsh: re-declaring
    # `local` inside a loop body can leak the assignment expression to
    # stdout on some zsh versions -- see kanban-helpers.sh house style).
    local cand_json cand_id cand_title cand_worktree cand_branch cand_parent cand_lkw
    local plan_target plan_doc_path classification result_line
    local -a result_lines=()

    while IFS= read -r cand_json; do
        [[ -n "$cand_json" ]] || continue

        cand_id=$(printf '%s' "$cand_json" | jq -r '.id // empty' 2>/dev/null)
        [[ -n "$cand_id" ]] || continue
        cand_title=$(printf '%s' "$cand_json" | jq -r '.title // empty' 2>/dev/null)
        cand_worktree=$(printf '%s' "$cand_json" | jq -r '.worktree // empty' 2>/dev/null)
        cand_branch=$(printf '%s' "$cand_json" | jq -r '.branch // empty' 2>/dev/null)
        cand_parent=$(printf '%s' "$cand_json" | jq -r '.parentId // empty' 2>/dev/null)
        cand_lkw=$(printf '%s' "$cand_json" | jq -r '.lastKnownWindow // empty' 2>/dev/null)

        # planDocPath resolves at the PARENT granularity (kb-plan-doc-path
        # rejects subitem-shaped ids); use the id itself when this candidate
        # IS a top-level item (parentId is null/empty).
        plan_target="${cand_parent:-$cand_id}"
        plan_doc_path=$(_kb_reconcile_plan_doc_path "$plan_target")

        # BOUND requires a lastKnownWindow pointer AND that exact
        # "terminal:window_name" key present in the live set right now.
        # No pointer, or a live set that doesn't contain it (including an
        # entirely empty live set post-crash) => ORPHANED.
        classification="ORPHANED"
        if [[ -n "$cand_lkw" && -n "$live_windows" ]] && printf '%s\n' "$live_windows" | grep -qxF -- "$cand_lkw"; then
            classification="BOUND"
        fi

        result_line=$(jq -nc \
            --arg id "$cand_id" \
            --arg title "$cand_title" \
            --arg team "$team" \
            --arg parentId "$cand_parent" \
            --arg worktree "$cand_worktree" \
            --arg branch "$cand_branch" \
            --arg planDocPath "$plan_doc_path" \
            --arg lastKnownWindow "$cand_lkw" \
            --arg classification "$classification" \
            '{
                id: $id,
                title: $title,
                team: $team,
                parentId: (if $parentId == "" then null else $parentId end),
                worktree: (if $worktree == "" then null else $worktree end),
                branch: (if $branch == "" then null else $branch end),
                planDocPath: (if $planDocPath == "" then null else $planDocPath end),
                lastKnownWindow: (if $lastKnownWindow == "" then null else $lastKnownWindow end),
                classification: $classification
            }' 2>/dev/null)

        [[ -n "$result_line" ]] && result_lines+=("$result_line")
    done < <(printf '%s' "$candidates" | jq -c '.[]' 2>/dev/null)

    if [[ ${#result_lines[@]} -eq 0 ]]; then
        echo "[]"
        return 0
    fi

    printf '%s\n' "${result_lines[@]}" | jq -sc '.' 2>/dev/null || echo "[]"
}

# Thin manual/debug CLI over _kb_reconcile_inprogress -- NOT the user-facing
# crash-recovery command (that's kb-recover, XACA-0778-002, built on top of
# this). Useful for spot-checking reconciliation state without waiting on 002.
#
# Usage: kb-reconcile-inprogress [--team <team>] [--all-teams] [--json]
#   (no flags)     current team (via _kb_detect_context), human-readable table
#   --team <team>  scan one specific team's board
#   --all-teams    scan every team registered in team-paths.json
#   --json         emit the raw JSON array (or {team: [...]} map for --all-teams)
kb-reconcile-inprogress() {
    _kb_ensure_jq || return 1

    local target_team="" all_teams=0 emit_json=0

    while [[ $# -gt 0 ]]; do
        case "${1-}" in
            --team)
                target_team="${2-}"
                shift 2
                ;;
            --all-teams)
                all_teams=1
                shift
                ;;
            --json)
                emit_json=1
                shift
                ;;
            -h|--help)
                cat <<'USAGE'
Usage: kb-reconcile-inprogress [--team <team>] [--all-teams] [--json]

Classifies every in_progress item/subitem as BOUND (live tmux window backs
it) or ORPHANED (it does not) -- e.g. after a Mac/tmux crash. Read-only:
never mutates the board or tmux. See _kb_reconcile_inprogress in
kanban-helpers.sh for the full output contract.

  --team <team>   Scan one specific team's board (default: current team)
  --all-teams     Scan every team registered in ~/.aiteamforge/team-paths.json
  --json          Emit raw JSON instead of the human-readable table
USAGE
                return 0
                ;;
            *)
                echo "Unknown argument: ${1-}" >&2
                echo "Run 'kb-reconcile-inprogress --help' for usage." >&2
                return 2
                ;;
        esac
    done

    local -a teams_to_scan=()
    if [[ "$all_teams" -eq 1 ]]; then
        local teams_json="$HOME/.aiteamforge/team-paths.json"
        if [[ ! -f "$teams_json" ]]; then
            echo "Error: cannot read $teams_json" >&2
            return 2
        fi
        local raw_teams t
        raw_teams=$(jq -r '.teams | keys[]' "$teams_json" 2>/dev/null)
        while IFS= read -r t; do
            [[ -n "$t" ]] && teams_to_scan+=("$t")
        done <<< "$raw_teams"
    elif [[ -n "$target_team" ]]; then
        teams_to_scan=("$target_team")
    else
        local context
        context=$(_kb_detect_context)
        if [[ "$context" == ERROR:* ]]; then
            echo "Error: could not detect team context. Pass --team <team> or --all-teams." >&2
            return 2
        fi
        teams_to_scan=("${context%%:*}")
    fi

    # team → results map, accumulated across the scan
    local report="{}"
    local scan_team team_results
    for scan_team in "${teams_to_scan[@]}"; do
        [[ -n "$scan_team" ]] || continue
        team_results=$(_kb_reconcile_inprogress "$scan_team")
        report=$(jq -c --arg t "$scan_team" --argjson r "${team_results:-[]}" '.[$t] = $r' <<< "$report" 2>/dev/null) || report="{}"
    done

    if [[ "$emit_json" -eq 1 ]]; then
        printf '%s\n' "$report" | jq '.'
        return 0
    fi

    local bound_count orphan_count total
    bound_count=$(printf '%s' "$report" | jq '[.[][] | select(.classification == "BOUND")] | length' 2>/dev/null || echo 0)
    orphan_count=$(printf '%s' "$report" | jq '[.[][] | select(.classification == "ORPHANED")] | length' 2>/dev/null || echo 0)
    total=$(( bound_count + orphan_count ))

    if [[ "$total" -eq 0 ]]; then
        echo "No in_progress items/subitems found across ${#teams_to_scan[@]} team(s)."
        return 0
    fi

    printf '%s' "$report" | jq -r '
        to_entries[] | .key as $team | .value[] |
        "[\(.classification)] \($team) \(.id) — \(.title)\n    worktree: \(.worktree // "-")  branch: \(.branch // "-")  lastKnownWindow: \(.lastKnownWindow // "-")\n    planDocPath: \(.planDocPath // "-")"
    '
    echo ""
    echo "Summary: $total in_progress ($bound_count BOUND, $orphan_count ORPHANED) across ${#teams_to_scan[@]} team(s)."
    if [[ "$orphan_count" -gt 0 ]]; then
        echo "Run kb-recover to resume orphaned work (XACA-0778-002)."
    fi
}

# The user-facing crash-recovery command (XACA-0778-002). Answers "what was I
# doing?" after a Mac/tmux crash: filters _kb_reconcile_inprogress's output
# down to ORPHANED entries only (BOUND work needs no recovery) and renders a
# resume manifest -- id, title, worktree, branch, plan-doc path, last-known
# window. Pure read-only, same as the engine it's built on. To re-bind an
# orphan to the CURRENT live window, run `kb-resume <ID>` (XACA-0778-004).
#
# Usage: kb-recover [--team <team>] [--all-teams] [--json]
#   (no flags)     current team (via _kb_detect_context)
#   --team <team>  scan one specific team's board
#   --all-teams    scan every team registered in team-paths.json -- a crash
#                  hits every board, not just the one you happen to be in
#   --json         emit the raw resume-manifest JSON: a flat array for the
#                  single-team case, a {team: [...]} map for --all-teams
kb-recover() {
    _kb_ensure_jq || return 1

    local target_team="" all_teams=0 emit_json=0

    while [[ $# -gt 0 ]]; do
        case "${1-}" in
            --team)
                target_team="${2-}"
                shift 2
                ;;
            --all-teams)
                all_teams=1
                shift
                ;;
            --json)
                emit_json=1
                shift
                ;;
            -h|--help)
                cat <<'USAGE'
Usage: kb-recover [--team <team>] [--all-teams] [--json]

Resume manifest: lists in_progress items/subitems ORPHANED by a crash (no
live tmux window backs them) -- "what was I doing?" after a Mac/tmux crash.
Read-only: never mutates the board or tmux.

  --team <team>   Scan one specific team's board (default: current team)
  --all-teams     Scan every team registered in ~/.aiteamforge/team-paths.json
  --json          Emit the raw resume-manifest JSON instead of the report

To re-bind an orphan to THIS window: kb-resume <ID>
USAGE
                return 0
                ;;
            *)
                echo "Unknown argument: ${1-}" >&2
                echo "Run 'kb-recover --help' for usage." >&2
                return 2
                ;;
        esac
    done

    if [[ "$all_teams" -eq 1 ]]; then
        local teams_json="$HOME/.aiteamforge/team-paths.json"
        if [[ ! -f "$teams_json" ]]; then
            echo "Error: cannot read $teams_json" >&2
            return 2
        fi
        local -a teams_to_scan=()
        local raw_teams t
        raw_teams=$(jq -r '.teams | keys[]' "$teams_json" 2>/dev/null)
        while IFS= read -r t; do
            [[ -n "$t" ]] && teams_to_scan+=("$t")
        done <<< "$raw_teams"

        # team → ORPHANED-only results map. XACA-0830-021/015: any
        # tmux-unreachable team along the way already printed its own
        # caveat to STDERR from inside _kb_reconcile_inprogress (see that
        # function's comment) -- nothing further needed here, and nothing
        # here touches $report / the JSON output.
        local report="{}"
        local scan_team team_results orphaned
        for scan_team in "${teams_to_scan[@]}"; do
            [[ -n "$scan_team" ]] || continue
            team_results=$(_kb_reconcile_inprogress "$scan_team")
            orphaned=$(printf '%s' "${team_results:-[]}" | jq -c '[.[] | select(.classification == "ORPHANED")]' 2>/dev/null)
            report=$(jq -c --arg t "$scan_team" --argjson r "${orphaned:-[]}" '.[$t] = $r' <<< "$report" 2>/dev/null) || report="{}"
        done

        if [[ "$emit_json" -eq 1 ]]; then
            printf '%s\n' "$report" | jq '.'
            return 0
        fi

        local orphan_count
        orphan_count=$(printf '%s' "$report" | jq '[.[][]] | length' 2>/dev/null || echo 0)

        if [[ "$orphan_count" -eq 0 ]]; then
            echo "✓ Nothing orphaned across ${#teams_to_scan[@]} team(s) -- all in_progress work is bound to a live window."
            return 0
        fi

        echo "Resume manifest -- $orphan_count orphaned in_progress item(s)/subitem(s) across ${#teams_to_scan[@]} team(s):"
        echo ""
        printf '%s' "$report" | jq -r '
            to_entries[] | .key as $team | .value[] |
            "[\($team)] \(.id) — \(.title)\n    worktree:          \(.worktree // "-")\n    branch:            \(.branch // "-")\n    plan doc:          \(.planDocPath // "-")\n    last known window: \(.lastKnownWindow // "-")\n"
        '
        echo "To pick this work back up in THIS window: kb-resume <ID>"
        return 0
    fi

    # Single-team path (default: current team via context; or --team override)
    local team
    if [[ -n "$target_team" ]]; then
        team="$target_team"
    else
        local context
        context=$(_kb_detect_context)
        if [[ "$context" == ERROR:* ]]; then
            echo "Error: could not detect team context. Pass --team <team> or --all-teams." >&2
            return 2
        fi
        team="${context%%:*}"
    fi

    local team_results orphaned
    team_results=$(_kb_reconcile_inprogress "$team")
    orphaned=$(printf '%s' "${team_results:-[]}" | jq -c '[.[] | select(.classification == "ORPHANED")]' 2>/dev/null)
    [[ -n "$orphaned" ]] || orphaned="[]"

    if [[ "$emit_json" -eq 1 ]]; then
        printf '%s\n' "$orphaned" | jq '.'
        return 0
    fi

    local orphan_count
    orphan_count=$(printf '%s' "$orphaned" | jq 'length' 2>/dev/null || echo 0)

    # XACA-0830-021/015: if tmux state could not be confirmed for this team,
    # _kb_reconcile_inprogress already printed its own caveat to STDERR
    # above (see that function's comment for why stderr, not a variable, is
    # the channel) -- nothing further needed here.

    if [[ "$orphan_count" -eq 0 ]]; then
        echo "✓ Nothing orphaned for team '$team' -- all in_progress work is bound to a live window."
        return 0
    fi

    echo "Resume manifest for team '$team' -- $orphan_count orphaned in_progress item(s)/subitem(s):"
    echo ""
    printf '%s' "$orphaned" | jq -r '
        .[] |
        "\(.id) — \(.title)\n    worktree:          \(.worktree // "-")\n    branch:            \(.branch // "-")\n    plan doc:          \(.planDocPath // "-")\n    last known window: \(.lastKnownWindow // "-")\n"
    '
    echo "To pick this work back up in THIS window: kb-resume <ID>"
}

# Re-bind an ORPHANED in_progress item/subitem to the CURRENT live tmux
# window (XACA-0778-004). This is the `kb-resume <ID>` overload path -- NOT
# the no-arg pause/resume toggle below (that stays untouched).
#
# Pointer re-bind ONLY: does not change status (the item is already
# in_progress) and does not touch pausedReason/previousStatus (those belong
# to the pause/resume flow). It sets worktreeWindowId on the item/subitem to
# THIS window and refreshes the matching activeWindows[] entry via
# _kb_update_window, so the Workflow tab shows it BOUND again immediately.
# Classification comes from _kb_reconcile_inprogress (XACA-0778-001) -- never
# hand-rolled here.
#
# Usage: kb-resume <ID>   (item id "XACA-0761" or subitem id "XACA-0761-003")
_kb_resume_rebind() {
    local target_id="${1-}"

    _kb_ensure_jq || return 1

    local context team terminal window_index window_name board_file window_id
    context=$(_kb_detect_context)
    if [[ "$context" == ERROR:* ]]; then
        echo "Error: could not detect the current window context." >&2
        echo "kb-resume <ID> re-binds an orphaned item to the CURRENT live tmux window --" >&2
        echo "run it from inside the tmux window you want to bind to." >&2
        return 1
    fi
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'" >&2
        return 1
    fi

    # Classify via the reconciliation engine (read-only, single source of
    # truth for BOUND/ORPHANED).
    local reconciled match_json classification current_lkw title parent_id
    reconciled=$(_kb_reconcile_inprogress "$team" "$board_file")
    match_json=$(printf '%s' "$reconciled" | jq -c --arg id "$target_id" '[.[] | select(.id == $id)] | first // empty' 2>/dev/null)

    if [[ -z "$match_json" || "$match_json" == "null" ]]; then
        echo "Error: '$target_id' is not an in_progress item/subitem on team '$team'." >&2
        echo "Run 'kb-recover' to see the current resume manifest." >&2
        return 1
    fi

    classification=$(printf '%s' "$match_json" | jq -r '.classification')
    current_lkw=$(printf '%s' "$match_json" | jq -r '.lastKnownWindow // empty')
    title=$(printf '%s' "$match_json" | jq -r '.title // empty')
    parent_id=$(printf '%s' "$match_json" | jq -r '.parentId // empty')

    if [[ "$classification" == "BOUND" ]]; then
        if [[ "$current_lkw" == "$window_id" ]]; then
            echo "'$target_id' is already bound to this window ($window_id). Nothing to do."
        else
            echo "'$target_id' is already BOUND to a live window ($current_lkw), not this one ($window_id)."
            echo "Refusing to steal a live binding -- stop it there first, or resume it from that window."
        fi
        return 0
    fi

    # ORPHANED -- warn (don't block) if the current worktree is already
    # claimed by another actively-working item/subitem, same advisory guard
    # kb-run/kb-pick run before binding a window to a task (XACA-0778-018).
    local worktree conflict
    worktree=$(_kb_get_worktree)
    if [[ -n "$worktree" ]]; then
        conflict=$(_kb_check_worktree_conflict "$board_file" "$target_id" "$worktree")
        if [[ -n "$conflict" ]]; then
            _kb_warn_worktree_conflict "$conflict"
        fi
    fi

    # ORPHANED -- re-point the persistent worktreeWindowId to THIS window.
    local idx sidx timestamp
    timestamp=$(_kb_get_timestamp)

    if [[ -n "$parent_id" ]]; then
        local resolved
        resolved=$(_kb_resolve_subitem_id "$board_file" "$target_id")
        idx="${resolved%%:*}"
        sidx="${resolved#*:}"
        if [[ "$idx" == "-1" || "$sidx" == "-1" ]]; then
            echo "Error: could not resolve subitem '$target_id' on the board." >&2
            return 1
        fi
        _kb_jq_update "$board_file" \
           '.backlog[$pidx].subitems[$sidx].worktreeWindowId = $wid |
            .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
            .backlog[$pidx].updatedAt = $ts |
            .lastUpdated = $ts' \
           --argjson pidx "$idx" \
           --argjson sidx "$sidx" \
           --arg wid "$window_id" \
           --arg ts "$timestamp"
    else
        idx=$(_kb_find_by_id "$board_file" "$target_id")
        if [[ "$idx" == "-1" ]]; then
            echo "Error: could not resolve item '$target_id' on the board." >&2
            return 1
        fi
        _kb_jq_update "$board_file" \
           '.backlog[$idx].worktreeWindowId = $wid |
            .backlog[$idx].updatedAt = $ts |
            .lastUpdated = $ts' \
           --argjson idx "$idx" \
           --arg wid "$window_id" \
           --arg ts "$timestamp"
    fi

    # Refresh/create the activeWindows[] entry for THIS window so the
    # Workflow tab reflects the re-bind immediately. _kb_update_window
    # re-derives context internally and preserves persistent fields
    # (startedAt, statusHistory, ...) from any prior entry with this window
    # id. "coding" mirrors the status kb-run/kb-backlog-sub-start set when a
    # task is (re)claimed by a window.
    _kb_update_window "coding" "$title"
    _kb_set_working_on "$target_id" "DEV"

    echo "✓ Re-bound [$target_id] to this window ($window_id): $title"
    echo "  (was ORPHANED -- previous pointer: ${current_lkw:-none})"

    local target_type="item"
    [[ -n "$parent_id" ]] && target_type="subitem"
    _kb_log_activity "resume_rebind" "$target_id" "$target_type" "worktreeWindowId" "${current_lkw:-}" "$window_id" ""
}

# Resume a paused task and return to previous status
# Usage: kb-resume [<ID>]
# No args: returns card to its previous status before pausing (and clears
#   paused state from the backlog item) -- unchanged legacy behavior.
# With an ID (XACA-0778-004): re-binds an ORPHANED in_progress item/subitem
#   to THIS live window instead -- see _kb_resume_rebind above.
kb-resume() {
    if [[ $# -gt 0 ]]; then
        _kb_resume_rebind "$@"
        return $?
    fi

    local context team terminal window_index window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_index="${rest%%:*}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get current status and previous status
    local current_status previous_status
    current_status=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $id) | .status) // ""' \
        --arg id "$window_id" -r 2>/dev/null || echo "")

    if [[ "$current_status" != "paused" ]]; then
        echo "Error: Not currently paused. Nothing to resume."
        return 1
    fi

    previous_status=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $id) | .previousStatus) // "coding"' \
        --arg id "$window_id" -r 2>/dev/null || echo "coding")

    # Get the workingOnId to clear paused state from the backlog item as well
    local working_on_id
    working_on_id=$(_kb_jq_read "$board_file" \
        '(.activeWindows[] | select(.id == $id) | .workingOnId) // ""' \
        --arg id "$window_id" -r 2>/dev/null || echo "")

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Update the window AND backlog item: restore previous status, clear paused fields
    _kb_jq_update "$board_file" '
        # Update the activeWindow
        .activeWindows = [.activeWindows[] |
            if .id == $id then
                .status = $prevStatus |
                del(.pausedReason) |
                del(.previousStatus) |
                .lastActivity = $timestamp
            else
                .
            end
        ] |
        # Also clear paused fields from the backlog item (if workingOnId is set)
        (if $workingOnId != "" then
            .backlog = [.backlog[] |
                if .id == $workingOnId then
                    # Direct match on parent item
                    del(.pausedReason) |
                    del(.pausedAt) |
                    del(.pausedPreviousStatus) |
                    .updatedAt = $timestamp
                elif (.subitems // []) | any(.id == $workingOnId) then
                    # Match on a subitem - clear from the subitem
                    .subitems = [(.subitems // [])[] |
                        if .id == $workingOnId then
                            del(.pausedReason) |
                            del(.pausedAt) |
                            del(.pausedPreviousStatus) |
                            .updatedAt = $timestamp
                        else . end
                    ]
                else . end
            ]
        else . end) |
        .lastUpdated = $timestamp
    ' \
    --arg id "$window_id" \
    --arg prevStatus "$previous_status" \
    --arg workingOnId "$working_on_id" \
    --arg timestamp "$timestamp"

    echo "▶️  RESUMED! Returned to: $previous_status"
    if [[ -n "$working_on_id" ]]; then
        echo "   (cleared from backlog item: $working_on_id)"
    fi

    # Activity log: item resumed (use working_on_id if available)
    if [[ -n "$working_on_id" ]]; then
        _kb_log_activity "resumed" "$working_on_id" "item" "status" "paused" "$previous_status" ""
    fi
}

# Review all subitems for the current active kanban item and report their statuses
# Usage: kb-sweep [item-id]
# If item-id is provided, reviews subitems for that item
# Otherwise, reviews subitems for the item currently being worked on
# Returns 0 if all subitems are completed or cancelled (ready to close)
# Returns 1 if any subitems are still todo or in_progress (not ready)
kb-sweep() {
    _kb_ensure_jq || return 1

    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get working_id from argument or from activeWindows
    local working_id
    if [[ -n "$1" ]]; then
        # Use provided item ID
        working_id="$1"

        # When explicit ID is provided, derive correct board file from ID prefix
        local id_team
        id_team=$(_kb_get_team_from_code "$working_id")
        if [[ -n "$id_team" ]]; then
            board_file=$(_kb_get_board_file "$id_team")
        fi
    else
        # Get current workingOnId from activeWindows
        working_id=$(_kb_jq_read "$board_file" \
            '.activeWindows[] | select(.id == $wid) | .workingOnId // empty' \
            --arg wid "$window_id" -r)
    fi

    if [[ -z "$working_id" ]]; then
        echo "Error: No item ID provided and not currently working on any item"
        echo "Usage: kb-sweep [item-id]"
        return 1
    fi

    # Only applicable to main items (not subitems)
    if [[ "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        echo "Note: kb-sweep applies to main items only, not subitems."
        echo "Parent item: ${working_id%-*}"
        return 0
    fi

    # Find the item index
    local item_idx
    item_idx=$(_kb_find_by_id "$board_file" "$working_id")
    if [[ "$item_idx" -lt 0 ]]; then
        echo "Error: Item not found: $working_id"
        return 1
    fi

    # Get subitem count
    local subitem_count
    subitem_count=$(_kb_jq_read "$board_file" \
        '.backlog[$idx].subitems // [] | length' \
        --argjson idx "$item_idx" -r 2>/dev/null)

    echo ""
    echo "═══════════════════════════════════════════════════════"
    echo "  SUBITEM STATUS SWEEP: $working_id"
    echo "═══════════════════════════════════════════════════════"

    if [[ -z "$subitem_count" ]] || [[ "$subitem_count" -eq 0 ]]; then
        echo "  No subitems found — ready to close."
        echo "═══════════════════════════════════════════════════════"
        echo ""
        return 0
    fi

    echo ""

    # Print each subitem with status icon
    local completed_count=0 cancelled_count=0 in_progress_count=0 todo_count=0 blocked_count=0
    local icon sub_status sub_id sub_title

    # Read subitems as newline-delimited lines: STATUS|ID|TITLE
    local subitem_lines
    subitem_lines=$(_kb_jq_read "$board_file" \
        '.backlog[$idx].subitems[] | "\(.status)|\(.id)|\(.title)"' \
        --argjson idx "$item_idx" -r 2>/dev/null)

    while IFS="|" read -r sub_status sub_id sub_title; do
        [[ -z "$sub_status" ]] && continue
        case "$sub_status" in
            completed)  icon="[✓]" ; completed_count=$((completed_count + 1)) ;;
            cancelled)  icon="[/]" ; cancelled_count=$((cancelled_count + 1)) ;;
            in_progress) icon="[●]" ; in_progress_count=$((in_progress_count + 1)) ;;
            blocked)    icon="[!]" ; blocked_count=$((blocked_count + 1)) ;;
            todo)       icon="[ ]" ; todo_count=$((todo_count + 1)) ;;
            *)          icon="[?]" ; todo_count=$((todo_count + 1)) ;;
        esac
        printf "  %s %s: %s\n" "$icon" "$sub_id" "$sub_title"
    done <<< "$subitem_lines"

    echo ""

    local resolved_count=$((completed_count + cancelled_count))
    local remaining_count=$((in_progress_count + todo_count + blocked_count))

    echo "  Legend: [✓] completed  [/] cancelled  [●] in_progress  [!] blocked  [ ] todo"
    echo ""

    # Retrospective file validation (blocking — prevents kb-done if retro file is missing)
    # Check if there's a completed "Retrospective" subitem and validate the file exists
    local has_retro_subitem=false retro_subitem_completed=false retro_blocking=false
    while IFS="|" read -r rs_status rs_id rs_title; do
        [[ -z "$rs_status" ]] && continue
        # Match the standard "Retrospective and Knowledge Capture" subitem
        # Must start with "Retrospective" to avoid matching subitems that merely mention retros
        if [[ "$rs_title" == Retrospective* ]]; then
            has_retro_subitem=true
            if [[ "$rs_status" == "completed" ]]; then
                retro_subitem_completed=true
            fi
        fi
    done <<< "$subitem_lines"

    if $retro_subitem_completed; then
        # Use kb-retro-path to check if the retrospective file exists
        local retro_path
        retro_path=$(kb-retro-path "$working_id" 2>/dev/null)
        if [[ -n "$retro_path" ]]; then
            if [[ -f "$retro_path" ]]; then
                echo "  ✅ Retrospective file found: $(basename "$retro_path")"
            else
                echo "  🚫 BLOCKING: Retrospective subitem marked complete but file not found:"
                echo "     Expected: $retro_path"
                echo "     Run: kb-retro-path $working_id"
                retro_blocking=true
            fi
        else
            echo "  🚫 BLOCKING: Could not resolve retrospective path for $working_id"
            echo "     (No plan document found — cannot derive filename)"
            retro_blocking=true
        fi

        # Check for at least one knowledge entry referencing this item
        local kanban_dir knowledge_dir knowledge_count=0
        id_team=$(_kb_get_team_from_code "$working_id")
        if [[ -n "$id_team" ]]; then
            kanban_dir=$(_kb_get_kanban_dir "$id_team")
            knowledge_dir="${kanban_dir}/knowledge"
            if [[ -d "$knowledge_dir" ]]; then
                knowledge_count=$(grep -rl "$working_id" "$knowledge_dir" 2>/dev/null | wc -l | tr -d ' ')
            fi
        fi
        if [[ "$knowledge_count" -gt 0 ]]; then
            echo "  ✅ Knowledge entries referencing $working_id: $knowledge_count"
        else
            echo "  🚫 BLOCKING: No knowledge entries found referencing $working_id"
            echo "     Retrospectives should produce at least 1 knowledge entry."
            echo "     See: ~/knowledge/templates/knowledge_entry_template.md"
            retro_blocking=true
        fi
        echo ""

        if $retro_blocking; then
            echo "  Retrospective validation FAILED — cannot close item until retro file and knowledge entries exist."
            echo ""
            remaining_count=$((remaining_count + 1))
        fi
    fi

    if [[ "$remaining_count" -eq 0 ]]; then
        echo "  $resolved_count of $subitem_count subitems resolved. Ready to close."
        echo "═══════════════════════════════════════════════════════"
        echo ""
        return 0
    else
        echo "  $resolved_count of $subitem_count subitems resolved. $remaining_count remaining — address before closing."
        echo "═══════════════════════════════════════════════════════"
        echo ""
        return 1
    fi
}

# Shortcut: Mark as completed and remove from board
# Usage: kb-done [item-id]
# If item-id is provided, marks that item as completed
# Otherwise, marks the item currently being worked on as completed
kb-done() {
    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get working_id from argument or from activeWindows
    local working_id explicit_id_provided=false
    if [[ -n "$1" ]]; then
        # Use provided item ID
        working_id="$1"
        explicit_id_provided=true

        # When explicit ID is provided, derive correct board file from ID prefix
        local id_team
        id_team=$(_kb_get_team_from_code "$working_id")
        if [[ -n "$id_team" ]]; then
            board_file=$(_kb_get_board_file "$id_team")
        fi
    else
        # Get current workingOnId from activeWindows
        working_id=$(_kb_jq_read "$board_file" \
            '.activeWindows[] | select(.id == $wid) | .workingOnId // empty' \
            --arg wid "$window_id" -r)
    fi

    if [[ -z "$working_id" ]]; then
        echo "Error: No item ID provided and not currently working on any item"
        return 1
    fi

    # Check for --force flag (allows completing items with incomplete subitems)
    # --force is restricted to user-only usage. Agents must NOT use this flag.
    local force_complete=false
    if [[ "$1" == "--force" ]] || [[ "$2" == "--force" ]]; then
        force_complete=true
        echo "WARNING: --force bypasses subitem completion checks."
        echo "WARNING: This flag is reserved for the user only. Agents must NOT use --force."
        echo "WARNING: Proceeding with force..."
        echo ""
    fi

    local timestamp item_found=false
    timestamp=$(_kb_get_timestamp)

    # Check if it's a subitem or item and mark as completed
    if [[ "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        # Subitem - mark completed with timestamp
        local parent_id="${working_id%-*}"
        local parent_idx
        parent_idx=$(_kb_find_by_id "$board_file" "$parent_id")
        if [[ "$parent_idx" -ge 0 ]]; then
            # Capture old status before update
            local sub_old_status
            sub_old_status=$(_kb_jq_read "$board_file" \
                '[.backlog[$pidx].subitems[] | select(.id == $subId)] | first | .status // "todo"' \
                --argjson pidx "$parent_idx" --arg subId "$working_id" -r 2>/dev/null || echo "todo")
            if ! _kb_jq_update "$board_file" '
                .backlog[$pidx].subitems = [.backlog[$pidx].subitems[] |
                    if .id == $subId then
                        .status = "completed" |
                        .completedAt = $ts |
                        .updatedAt = $ts |
                        del(.activelyWorking, .workStartedAt, .worktree, .worktreeBranch, .worktreeWindowId)
                    else . end
                ] |
                .backlog[$pidx].updatedAt = $ts |
                .lastUpdated = $ts
            ' --argjson pidx "$parent_idx" --arg subId "$working_id" --arg ts "$timestamp"; then
                echo "❌ kb-done: board write failed (jq transform produced no output). Task NOT completed." >&2
                return 1
            fi
            item_found=true
            # Activity log: subitem completed via kb-done
            _kb_log_activity "subitem_status_change" "$working_id" "subitem" "status" "$sub_old_status" "completed" ""
        fi
    else
        # Main item - mark completed with timestamp
        local item_idx
        item_idx=$(_kb_find_by_id "$board_file" "$working_id")
        if [[ "$item_idx" -ge 0 ]]; then
            # Check if all subitems are resolved (unless --force is used)
            # kb-sweep handles the full status sweep and returns 1 if any remain
            if [[ "$force_complete" == "false" ]]; then
                if ! kb-sweep "$working_id" 2>/dev/null; then
                    echo "❌ Cannot complete: unresolved subitems detected."
                    echo "   Resolve all subitems above before closing."
                    echo "   To bypass (user only): kb-done $working_id --force"
                    return 1
                fi
            fi

            if ! _kb_jq_update "$board_file" \
                '.backlog[$idx].status = "completed" |
                 .backlog[$idx].completedAt = $ts |
                 .backlog[$idx].updatedAt = $ts |
                 del(.backlog[$idx].activelyWorking) |
                 del(.backlog[$idx].workStartedAt) |
                 del(.backlog[$idx].worktree) |
                 del(.backlog[$idx].worktreeBranch) |
                 del(.backlog[$idx].worktreeWindowId) |
                 .lastUpdated = $ts' \
                --argjson idx "$item_idx" --arg ts "$timestamp"; then
                echo "❌ kb-done: board write failed (jq transform produced no output). Task NOT completed." >&2
                return 1
            fi
            item_found=true
            # Activity log: main item completed
            _kb_log_activity "status_change" "$working_id" "item" "status" "" "completed" ""
        fi
    fi

    if [[ "$item_found" == "false" ]]; then
        echo "Error: Item not found: $working_id"
        return 1
    fi

    echo "Task completed!"

    # XACA-0100: Knowledge capture reminder for completed main items (non-blocking)
    # Only fires for main items (not subitems) since retros are per-item, not per-subitem
    if [[ ! "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        local kb_kanban_dir
        kb_kanban_dir=$(_kb_get_kanban_dir "$team")
        local kb_item_lower
        kb_item_lower=$(echo "$working_id" | tr '[:upper:]' '[:lower:]')

        # Search for retrospective file matching the item ID
        local kb_retro_file=""

        # Primary: check kanban/ dir for ITEM_ID_*_RETROSPECTIVE.md (canonical location)
        kb_retro_file=$(find "${kb_kanban_dir}" -maxdepth 1 -type f -name "${working_id}_*_RETROSPECTIVE.md" 2>/dev/null | head -1)

        # Fallback: check knowledge directories
        if [[ -z "$kb_retro_file" ]]; then
            local kb_search_dirs=()
            [[ -d "${kb_kanban_dir}/knowledge" ]] && kb_search_dirs+=("${kb_kanban_dir}/knowledge")
            for kb_dir in "${kb_search_dirs[@]}"; do
                if [[ -d "$kb_dir" ]]; then
                    kb_retro_file=$(find "$kb_dir" -maxdepth 3 -type f -name "*${kb_item_lower}*" 2>/dev/null | head -1)
                    [[ -n "$kb_retro_file" ]] && break
                fi
            done
        fi

        if [[ -n "$kb_retro_file" ]]; then
            echo "  Retrospective found for ${working_id}: $(basename "$kb_retro_file")"
        else
            echo ""
            echo "  ╔══════════════════════════════════════════════════════════╗"
            echo "  ║  KNOWLEDGE CAPTURE REMINDER                             ║"
            echo "  ║                                                         ║"
            printf "  ║  No retrospective found for %-29s║\n" "${working_id}"
            echo "  ║                                                         ║"
            echo "  ║  Consider capturing what you learned:                   ║"
            echo "  ║  Template: ~/knowledge/templates/retrospective...  ║"
            printf "  ║  Save to:  kanban/%-40s║\n" "${working_id}_*_RETROSPECTIVE.md"
            echo "  ║                                                         ║"
            echo "  ║  Run: kb-retro-check to see all items missing retros    ║"
            echo "  ╚══════════════════════════════════════════════════════════╝"
            echo ""
        fi
    fi

    # XACA-0054: Sync to release manifests via LCARS server
    _kb_release_sync "$working_id"

    # Auto-unblock dependents when a main item is completed (XACA-0020)
    if [[ ! "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        local unblocked_items
        unblocked_items=$(_kb_check_unblock_dependents "$board_file" "$working_id")
        if [[ -n "$unblocked_items" ]]; then
            echo "─────────────────────────────────────"
            echo "🔓 Auto-unblocked items: $unblocked_items"
        fi
    fi

    _kb_remove_window
}

# Cancel the current item/subitem without completing it
# Usage: kb-cancel [item-id] [--reason "text"]
kb-cancel() {
    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get working_id from argument or from activeWindows
    local working_id explicit_id_provided=false reason=""
    if [[ -n "$1" ]] && [[ "$1" != "--reason" ]]; then
        # Use provided item ID
        working_id="$1"
        explicit_id_provided=true
        shift

        # When explicit ID is provided, derive correct board file from ID prefix
        local id_team
        id_team=$(_kb_get_team_from_code "$working_id")
        if [[ -n "$id_team" ]]; then
            board_file=$(_kb_get_board_file "$id_team")
        fi
    else
        # Get current workingOnId from activeWindows
        working_id=$(_kb_jq_read "$board_file" \
            '.activeWindows[] | select(.id == $wid) | .workingOnId // empty' \
            --arg wid "$window_id" -r)
    fi

    # Parse --reason flag
    if [[ "$1" == "--reason" ]]; then
        reason="$2"
    elif [[ "$2" == "--reason" ]]; then
        reason="$3"
    fi

    if [[ -z "$working_id" ]]; then
        echo "Error: No item ID provided and not currently working on any item"
        return 1
    fi

    # Check for --force flag (allows cancelling items with incomplete subitems)
    local force_cancel=false
    if [[ "$1" == "--force" ]] || [[ "$2" == "--force" ]] || [[ "$3" == "--force" ]]; then
        force_cancel=true
    fi

    local timestamp item_found=false
    timestamp=$(_kb_get_timestamp)

    # Check if it's a subitem or item and mark as cancelled
    if [[ "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        # Subitem - mark cancelled with timestamp
        local parent_id="${working_id%-*}"
        local parent_idx
        parent_idx=$(_kb_find_by_id "$board_file" "$parent_id")
        if [[ "$parent_idx" -ge 0 ]]; then
            local update_jq='.backlog[$pidx].subitems = [.backlog[$pidx].subitems[] |
                if .id == $subId then
                    .status = "cancelled" |
                    .cancelledAt = $ts |
                    .updatedAt = $ts |
                    del(.activelyWorking, .workStartedAt, .worktree, .worktreeBranch, .worktreeWindowId)'
            if [[ -n "$reason" ]]; then
                update_jq="$update_jq | .cancelledReason = \$reason"
            fi
            update_jq="$update_jq else . end
            ] |
            .backlog[\$pidx].updatedAt = \$ts |
            .lastUpdated = \$ts"

            if [[ -n "$reason" ]]; then
                _kb_jq_update "$board_file" "$update_jq" \
                    --argjson pidx "$parent_idx" --arg subId "$working_id" \
                    --arg ts "$timestamp" --arg reason "$reason"
            else
                _kb_jq_update "$board_file" "$update_jq" \
                    --argjson pidx "$parent_idx" --arg subId "$working_id" \
                    --arg ts "$timestamp"
            fi
            item_found=true
        fi
    else
        # Main item - mark cancelled with timestamp
        local item_idx
        item_idx=$(_kb_find_by_id "$board_file" "$working_id")
        if [[ "$item_idx" -ge 0 ]]; then
            # Check if all subitems are resolved (unless --force is used)
            # kb-sweep handles the full status sweep and returns 1 if any remain
            if [[ "$force_cancel" == "false" ]]; then
                if ! kb-sweep "$working_id" 2>/dev/null; then
                    echo "❌ Cannot cancel: unresolved subitems detected."
                    echo "   Resolve all subitems above before cancelling."
                    echo "   To bypass (user only): kb-cancel $working_id --force"
                    return 1
                fi
            fi

            local update_jq='.backlog[$idx].status = "cancelled" |
                .backlog[$idx].cancelledAt = $ts |
                .backlog[$idx].updatedAt = $ts |
                del(.backlog[$idx].activelyWorking) |
                del(.backlog[$idx].workStartedAt) |
                del(.backlog[$idx].worktree) |
                del(.backlog[$idx].worktreeBranch) |
                del(.backlog[$idx].worktreeWindowId)'
            if [[ -n "$reason" ]]; then
                update_jq="$update_jq | .backlog[\$idx].cancelledReason = \$reason"
            fi
            update_jq="$update_jq | .lastUpdated = \$ts"

            if [[ -n "$reason" ]]; then
                _kb_jq_update "$board_file" "$update_jq" \
                    --argjson idx "$item_idx" --arg ts "$timestamp" --arg reason "$reason"
            else
                _kb_jq_update "$board_file" "$update_jq" \
                    --argjson idx "$item_idx" --arg ts "$timestamp"
            fi
            item_found=true
        fi
    fi

    if [[ "$item_found" == "false" ]]; then
        echo "Error: Item not found: $working_id"
        return 1
    fi

    echo "Task cancelled!"

    # XACA-0054: Sync to release manifests via LCARS server
    if type _kb_release_sync >/dev/null 2>&1; then
        _kb_release_sync "$working_id"
    fi

    # Auto-unblock dependents when a main item is cancelled (XACA-0075)
    if [[ ! "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        local unblocked_items
        unblocked_items=$(_kb_check_unblock_dependents "$board_file" "$working_id")
        if [[ -n "$unblocked_items" ]]; then
            echo "─────────────────────────────────────"
            echo "🔓 Auto-unblocked items: $unblocked_items"
        fi
    fi

    _kb_remove_window
}

# Stop working on the current item/subitem without completing it
# Usage: kb-stop-working
kb-stop-working() {
    local context team terminal window_name board_file window_id
    context=$(_kb_detect_context)
    team="${context%%:*}"
    local rest="${context#*:}"
    terminal="${rest%%:*}"
    rest="${rest#*:}"
    window_name="${rest#*:}"
    board_file=$(_kb_get_board_file "$team")
    window_id=$(_kb_get_window_id "$terminal" "$window_name")

    # Get current workingOnId
    local working_id
    working_id=$(_kb_jq_read "$board_file" \
        '.activeWindows[] | select(.id == $wid) | .workingOnId // empty' \
        --arg wid "$window_id" -r)

    if [[ -z "$working_id" ]]; then
        echo "Not currently working on any item"
        return 0
    fi

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Check if it's a subitem (format: XFRE-0001-001) or item (format: XFRE-0001)
    if [[ "$working_id" =~ ^X[A-Z]{3}-[0-9]+-[0-9]+$ ]]; then
        # It's a subitem - extract parent ID and find subitem by ID
        local parent_id="${working_id%-*}"
        local parent_idx
        parent_idx=$(_kb_find_by_id "$board_file" "$parent_id")

        if [[ "$parent_idx" -ge 0 ]]; then
            # Find subitem index by ID and clear its activelyWorking flag and worktree info
            _kb_jq_update "$board_file" '
                .backlog[$pidx].subitems = [.backlog[$pidx].subitems[] |
                    if .id == $subId then del(.activelyWorking, .workStartedAt, .worktree, .worktreeBranch, .worktreeWindowId) else . end
                ] |
                .lastUpdated = $ts
            ' --argjson pidx "$parent_idx" --arg subId "$working_id" --arg ts "$timestamp"
            echo "Cleared activelyWorking on subitem: $working_id"
        fi
    else
        # It's a main item
        local item_idx
        item_idx=$(_kb_find_by_id "$board_file" "$working_id")

        if [[ "$item_idx" -ge 0 ]]; then
            _kb_jq_update "$board_file" \
                'del(.backlog[$idx].activelyWorking) |
                 del(.backlog[$idx].workStartedAt) |
                 del(.backlog[$idx].worktree) |
                 del(.backlog[$idx].worktreeBranch) |
                 del(.backlog[$idx].worktreeWindowId) |
                 .lastUpdated = $ts' \
                --argjson idx "$item_idx" --arg ts "$timestamp"
            echo "Cleared activelyWorking on item: $working_id"
        fi
    fi

    # Clear workingOnId from window
    _kb_clear_working_on
    echo "Stopped working on: $working_id"
}

# Unified backlog management
# Usage: kb-backlog <command> [args...]
kb-backlog() {
    _kb_ensure_jq || return 1

    local cmd="$1"
    shift 2>/dev/null

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    case "$cmd" in
        add)
            local task="$1"
            local priority="${2:-medium}"
            local description="${3:-}"
            local jira_id="${4:-}"
            local os_param="${5:-}"

            # Normalize priority shortcuts
            [[ "$priority" == "med" ]] && priority="medium"
            [[ "$priority" == "crit" ]] && priority="critical"
            [[ "$priority" == "block" ]] && priority="blocked"

            # Validate priority
            local valid_priorities=("low" "medium" "high" "critical" "blocked")
            if [[ ! " ${valid_priorities[*]} " =~ " ${priority} " ]]; then
                echo "Error: Invalid priority '$priority'"
                echo "Valid priorities: ${valid_priorities[*]}"
                return 1
            fi

            # Validate and normalize OS parameter (case-insensitive)
            local normalized_os=""
            if [[ -n "$os_param" ]]; then
                local os_lower="${os_param,,}"  # Convert to lowercase
                case "$os_lower" in
                    ios) normalized_os="iOS" ;;
                    android) normalized_os="Android" ;;
                    firebase) normalized_os="Firebase" ;;
                    *)
                        echo "Error: Invalid OS '$os_param'"
                        echo "Valid OS values: iOS | Android | Firebase"
                        return 1
                        ;;
                esac
            fi

            if [[ -z "$task" ]]; then
                echo "Usage: kb-backlog add \"task\" [priority] [\"description\"] [jira-id] [os]"
                echo "Priority: low | med | medium | high | crit | critical | block | blocked"
                echo "Description: Optional multi-line description (max 5 lines displayed)"
                echo "JIRA ID: Optional JIRA ticket ID (e.g., ME-123, PROJ-456)"
                echo "OS: Optional platform - iOS | Android | Firebase"
                return 1
            fi

            local timestamp item_id
            timestamp=$(_kb_get_timestamp)
            item_id=$(_kb_generate_id "$board_file" "$team")

            # Build the backlog item with optional fields
            local jq_filter='.backlog += [{"id": $id, "title": $title, "priority": $priority, "addedAt": $timestamp'
            local jq_args=(--arg id "$item_id" --arg title "$task" --arg priority "$priority" --arg timestamp "$timestamp")

            if [[ -n "$description" ]]; then
                jq_filter+=', "description": $desc'
                jq_args+=(--arg desc "$description")
            fi

            if [[ -n "$jira_id" ]]; then
                jq_filter+=', "jiraId": $jira'
                jq_args+=(--arg jira "$jira_id")
            fi

            # Add OS as first element of tags array if specified
            if [[ -n "$normalized_os" ]]; then
                jq_filter+=', "tags": [$os]'
                jq_args+=(--arg os "$normalized_os")
            fi

            jq_filter+='}] | .lastUpdated = $timestamp'

            # Add with exclusive locking and increment ID counter
            _kb_jq_update "$board_file" "$jq_filter" "${jq_args[@]}"
            _kb_increment_id "$board_file"

            echo "✓ Added [$item_id]: $task [$priority]"
            [[ -n "$jira_id" ]] && echo "  JIRA: $jira_id"
            [[ -n "$normalized_os" ]] && echo "  OS: $normalized_os"
            [[ -n "$description" ]] && echo "  Description: ${description:0:50}..."

            # Activity log: item created
            _kb_log_activity "item_created" "$item_id" "item" "title" "" "$task" "priority=$priority"
            ;;

        list|ls)
            local count
            count=$(_kb_jq_read "$board_file" '.backlog | length')

            echo "Backlog for ${team}: ($count items)"
            echo "─────────────────────────────────────"
            if [[ "$count" -eq 0 ]]; then
                echo "  (empty)"
            else
                _kb_jq_read "$board_file" '.backlog[] | "  [\(.id // "?")] \(.priority | ascii_upcase | .[0:3]) \(.title)"' -r
            fi
            echo "─────────────────────────────────────"
            ;;

        change|edit)
            local selector="$1"
            local arg2="$2"
            local arg3="$3"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog change <id> [\"new title\"] [priority]"
                echo "Examples:"
                echo "  kb-backlog change XFRE-0001 \"Updated title\""
                echo "  kb-backlog change XFRE-0001 high"
                echo "  kb-backlog change XFRE-0001 \"Updated title\" high"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists (with locking)
            local current_title current_priority item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            current_priority=$(_kb_jq_read "$board_file" ".backlog[$index].priority // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local new_title="$current_title"
            local new_priority="$current_priority"

            # Detect what arg2 is (title or priority)
            if [[ -n "$arg2" ]]; then
                if [[ "$arg2" =~ ^(low|med|medium|high|crit|critical|block|blocked)$ ]]; then
                    new_priority="$arg2"
                    [[ "$new_priority" == "med" ]] && new_priority="medium"
                    [[ "$new_priority" == "crit" ]] && new_priority="critical"
                    [[ "$new_priority" == "block" ]] && new_priority="blocked"
                else
                    new_title="$arg2"
                fi
            fi

            # arg3 is always priority if provided
            if [[ -n "$arg3" ]]; then
                new_priority="$arg3"
                [[ "$new_priority" == "med" ]] && new_priority="medium"
                [[ "$new_priority" == "crit" ]] && new_priority="critical"
                [[ "$new_priority" == "block" ]] && new_priority="blocked"
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Update with exclusive locking (add updatedAt timestamp)
            _kb_jq_update "$board_file" \
               '.backlog[$idx].title = $title | .backlog[$idx].priority = $priority | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
               --argjson idx "$index" \
               --arg title "$new_title" \
               --arg priority "$new_priority" \
               --arg timestamp "$timestamp"

            echo "✓ Updated [$item_id]: $new_title [$new_priority]"

            # Activity log: field updates for title and/or priority
            if [[ "$new_title" != "$current_title" ]]; then
                _kb_log_activity "field_update" "$item_id" "item" "title" "$current_title" "$new_title" ""
            fi
            if [[ "$new_priority" != "$current_priority" ]]; then
                _kb_log_activity "field_update" "$item_id" "item" "priority" "$current_priority" "$new_priority" ""
            fi

            # Sync to release manifests (best-effort)
            _kb_release_sync "$item_id"
            ;;

        remove|rm)
            local selector="$1"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog remove <id>"
                echo "Example: kb-backlog remove XFRE-0001"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local title item_id timestamp
            title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)
            timestamp=$(_kb_get_timestamp)

            if [[ -z "$title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Remove with exclusive locking
            _kb_jq_update "$board_file" \
               'del(.backlog[$idx]) | .lastUpdated = $timestamp' \
               --argjson idx "$index" \
               --arg timestamp "$timestamp"
            echo "✓ Removed [$item_id]: $title"
            ;;

        jira)
            local selector="$1"
            local new_jira="$2"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog jira <id> <JIRA-ID>"
                echo "       kb-backlog jira <id> -        (clear JIRA ID)"
                echo ""
                echo "Set or update the JIRA ID for a backlog item."
                echo "Example: kb-backlog jira XFRE-0001 ME-123"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Handle clearing JIRA ID with "-"
            if [[ "$new_jira" == "-" ]]; then
                _kb_jq_update "$board_file" \
                   'del(.backlog[$idx].jiraId) | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Cleared JIRA ID for [$item_id]: $current_title"
                # Activity log: jira link cleared
                _kb_log_activity "jira_linked" "$item_id" "item" "jiraId" "" "" "cleared"
            elif [[ -n "$new_jira" ]]; then
                # Validate Jira ID (warns but allows)
                _kb_validate_jira_id "$new_jira"

                _kb_jq_update "$board_file" \
                   '.backlog[$idx].jiraId = $jira | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg jira "$new_jira" \
                   --arg timestamp "$timestamp"
                echo "✓ Set JIRA ID for [$item_id]: $current_title"
                echo "  JIRA: $new_jira"
                # Activity log: jira linked
                _kb_log_activity "jira_linked" "$item_id" "item" "jiraId" "" "$new_jira" ""
            else
                # Show current JIRA ID
                local current_jira
                current_jira=$(_kb_jq_read "$board_file" ".backlog[$index].jiraId // empty" -r)
                echo "[$item_id] $current_title"
                if [[ -n "$current_jira" ]]; then
                    echo "  JIRA: $current_jira"
                else
                    echo "  (no JIRA ID)"
                fi
            fi
            ;;

        github|gh)
            local selector="$1"
            local new_github="$2"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog github <id> <issue-ref>"
                echo "       kb-backlog github <id> -          (clear GitHub issue)"
                echo ""
                echo "Set or update the GitHub issue for a backlog item."
                echo ""
                echo "Issue formats:"
                echo "  #123              Shorthand (uses team default repo)"
                echo "  owner/repo#123    Full format (explicit repo)"
                echo ""
                echo "Team default repos:"
                echo "  academy   -> {{ORG_SLUG}}/dev-team"
                echo "  dns       -> {{ORG_SLUG}}/dns-framework"
                echo "  freelance -> {{ORG_SLUG}}/dev-team"
                echo ""
                echo "Examples:"
                echo "  kb-backlog github XFRE-0001 #42"
                echo "  kb-backlog github XFRE-0001 anthropics/claude-code#123"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Handle clearing GitHub issue with "-"
            if [[ "$new_github" == "-" ]]; then
                _kb_jq_update "$board_file" \
                   'del(.backlog[$idx].githubIssue) | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Cleared GitHub issue for [$item_id]: $current_title"
                # Activity log: github link cleared
                _kb_log_activity "github_linked" "$item_id" "item" "githubIssue" "" "" "cleared"
            elif [[ -n "$new_github" ]]; then
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].githubIssue = $gh | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg gh "$new_github" \
                   --arg timestamp "$timestamp"
                echo "✓ Set GitHub issue for [$item_id]: $current_title"
                echo "  GitHub: $new_github"
                # Activity log: github linked
                _kb_log_activity "github_linked" "$item_id" "item" "githubIssue" "" "$new_github" ""
            else
                # Show current GitHub issue
                local current_github
                current_github=$(_kb_jq_read "$board_file" ".backlog[$index].githubIssue // empty" -r)
                echo "[$item_id] $current_title"
                if [[ -n "$current_github" ]]; then
                    echo "  GitHub: $current_github"
                else
                    echo "  (no GitHub issue)"
                fi
            fi
            ;;

        desc|description)
            local selector="$1"
            local new_desc="$2"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog desc <id> \"description\""
                echo "       kb-backlog desc <id> -       (clear description)"
                echo ""
                echo "Set or update the description for a backlog item."
                echo "Descriptions are displayed under the title (max 5 lines)."
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Handle clearing description with "-"
            if [[ "$new_desc" == "-" ]]; then
                local old_desc_val
                old_desc_val=$(_kb_jq_read "$board_file" ".backlog[$index].description // empty" -r)
                _kb_jq_update "$board_file" \
                   'del(.backlog[$idx].description) | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Cleared description for [$item_id]: $current_title"
                # Activity log: description cleared
                _kb_log_activity "field_update" "$item_id" "item" "description" "${old_desc_val:0:100}" "" "cleared"
            elif [[ -n "$new_desc" ]]; then
                local old_desc_val
                old_desc_val=$(_kb_jq_read "$board_file" ".backlog[$index].description // empty" -r)
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].description = $desc | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg desc "$new_desc" \
                   --arg timestamp "$timestamp"
                echo "✓ Set description for [$item_id]: $current_title"
                echo "  ${new_desc:0:60}..."
                # Activity log: description updated
                _kb_log_activity "field_update" "$item_id" "item" "description" "${old_desc_val:0:100}" "${new_desc:0:100}" ""
            else
                # Show current description
                local current_desc
                current_desc=$(_kb_jq_read "$board_file" ".backlog[$index].description // empty" -r)
                echo "[$item_id] $current_title"
                if [[ -n "$current_desc" ]]; then
                    echo "─────────────────────────────────────"
                    echo "$current_desc"
                else
                    echo "(no description)"
                fi
            fi
            ;;

        tag|tags)
            local selector="$1"
            shift 2>/dev/null
            local tag_args=("$@")

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog tag <id> [add|rm|clear] [tag-name...]"
                echo ""
                echo "Manage tags for a backlog item. Tags appear as clickable pills in LCARS UI."
                echo ""
                echo "Commands:"
                echo "  kb-backlog tag <id>                   View current tags"
                echo "  kb-backlog tag <id> add \"tag1\" ...   Add one or more tags"
                echo "  kb-backlog tag <id> rm \"tag1\" ...    Remove specific tags"
                echo "  kb-backlog tag <id> clear             Remove all tags"
                echo "  kb-backlog tag <id> \"tag1\" \"tag2\"    Set tags (replaces existing)"
                echo ""
                echo "Examples:"
                echo "  kb-backlog tag XFRE-0001 add iOS refactor"
                echo "  kb-backlog tag XFRE-0001 rm testing"
                echo "  kb-backlog tag XFRE-0001 feature iOS urgent"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # No args - show current tags
            if [[ ${#tag_args[@]} -eq 0 ]]; then
                local current_tags
                current_tags=$(_kb_jq_read "$board_file" ".backlog[$index].tags // [] | join(\", \")" -r)
                echo "[$item_id] $current_title"
                if [[ -n "$current_tags" ]]; then
                    echo "  Tags: $current_tags"
                else
                    echo "  (no tags)"
                fi
                return 0
            fi

            local subcmd="${tag_args[1]}"

            case "$subcmd" in
                add)
                    # Add tags to existing array
                    shift
                    local new_tags=("${tag_args[@]:1}")
                    if [[ ${#new_tags[@]} -eq 0 ]]; then
                        echo "Usage: kb-backlog tag <id> add \"tag1\" \"tag2\" ..."
                        return 1
                    fi
                    local tags_json
                    tags_json=$(printf '%s\n' "${new_tags[@]}" | jq -R . | jq -s .)
                    _kb_jq_update "$board_file" \
                       '.backlog[$idx].tags = ((.backlog[$idx].tags // []) + $tags | unique) | .backlog[$idx].updatedAt = $ts | .lastUpdated = $ts' \
                       --argjson idx "$index" \
                       --argjson tags "$tags_json" \
                       --arg ts "$timestamp"
                    echo "✓ Added tags to [$item_id]: ${new_tags[*]}"
                    # Activity log: tags added
                    _kb_log_activity "tag_added" "$item_id" "item" "tags" "" "${new_tags[*]}" ""

                    # Sync to release manifests (best-effort)
                    _kb_release_sync "$item_id"
                    ;;

                rm|remove)
                    # Remove specific tags
                    shift
                    local rm_tags=("${tag_args[@]:1}")
                    if [[ ${#rm_tags[@]} -eq 0 ]]; then
                        echo "Usage: kb-backlog tag <id> rm \"tag1\" \"tag2\" ..."
                        return 1
                    fi
                    local rm_json
                    rm_json=$(printf '%s\n' "${rm_tags[@]}" | jq -R . | jq -s .)
                    _kb_jq_update "$board_file" \
                       '.backlog[$idx].tags = ((.backlog[$idx].tags // []) - $tags) | .backlog[$idx].updatedAt = $ts | .lastUpdated = $ts' \
                       --argjson idx "$index" \
                       --argjson tags "$rm_json" \
                       --arg ts "$timestamp"
                    echo "✓ Removed tags from [$item_id]: ${rm_tags[*]}"
                    # Activity log: tags removed
                    _kb_log_activity "tag_removed" "$item_id" "item" "tags" "${rm_tags[*]}" "" ""

                    # Sync to release manifests (best-effort)
                    _kb_release_sync "$item_id"
                    ;;

                clear)
                    # Remove all tags
                    _kb_jq_update "$board_file" \
                       'del(.backlog[$idx].tags) | .backlog[$idx].updatedAt = $ts | .lastUpdated = $ts' \
                       --argjson idx "$index" \
                       --arg ts "$timestamp"
                    echo "✓ Cleared all tags from [$item_id]: $current_title"
                    # Activity log: all tags cleared
                    _kb_log_activity "tag_removed" "$item_id" "item" "tags" "(all)" "" "cleared"

                    # Sync to release manifests (best-effort)
                    _kb_release_sync "$item_id"
                    ;;

                *)
                    # Set tags directly (replaces existing)
                    local set_tags=("${tag_args[@]}")
                    local set_json
                    set_json=$(printf '%s\n' "${set_tags[@]}" | jq -R . | jq -s .)
                    _kb_jq_update "$board_file" \
                       '.backlog[$idx].tags = $tags | .backlog[$idx].updatedAt = $ts | .lastUpdated = $ts' \
                       --argjson idx "$index" \
                       --argjson tags "$set_json" \
                       --arg ts "$timestamp"
                    echo "✓ Set tags for [$item_id]: ${set_tags[*]}"
                    # Activity log: tags set (replaces)
                    _kb_log_activity "tag_added" "$item_id" "item" "tags" "" "${set_tags[*]}" "set"

                    # Sync to release manifests (best-effort)
                    _kb_release_sync "$item_id"
                    ;;
            esac
            ;;

        priority|pri)
            local selector="$1"
            local new_priority="$2"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog priority <id> [priority]"
                echo "       kb-backlog priority <id> -        (clear/reset to medium)"
                echo ""
                echo "Set, view, or reset the priority for a backlog item."
                echo ""
                echo "Valid priorities:"
                echo "  critical (crit) - Urgent, needs immediate attention"
                echo "  high            - Important, prioritize soon"
                echo "  medium (med)    - Normal priority (default)"
                echo "  low             - Can wait, lower importance"
                echo "  blocked (block) - Waiting on external dependency"
                echo ""
                echo "Example: kb-backlog priority XFRE-0001 high"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id current_priority
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)
            current_priority=$(_kb_jq_read "$board_file" ".backlog[$index].priority // \"medium\"" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Handle clearing/resetting priority with "-"
            if [[ "$new_priority" == "-" ]]; then
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].priority = "medium" | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Reset priority to medium for [$item_id]: $current_title"
                # Activity log: priority reset to medium
                _kb_log_activity "field_update" "$item_id" "item" "priority" "$current_priority" "medium" "reset"

                # Sync to release manifests (best-effort)
                _kb_release_sync "$item_id"
            elif [[ -n "$new_priority" ]]; then
                # Normalize priority aliases
                case "$new_priority" in
                    med) new_priority="medium" ;;
                    crit) new_priority="critical" ;;
                    block) new_priority="blocked" ;;
                esac

                # Validate priority
                if [[ ! "$new_priority" =~ ^(low|medium|high|critical|blocked)$ ]]; then
                    echo "Error: Invalid priority. Use: low, medium (med), high, critical (crit), or blocked (block)"
                    return 1
                fi

                _kb_jq_update "$board_file" \
                   '.backlog[$idx].priority = $priority | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg priority "$new_priority" \
                   --arg timestamp "$timestamp"
                echo "✓ Set priority for [$item_id]: $current_title"
                echo "  Priority: $new_priority"
                # Activity log: priority changed
                _kb_log_activity "field_update" "$item_id" "item" "priority" "$current_priority" "$new_priority" ""

                # Sync to release manifests (best-effort)
                _kb_release_sync "$item_id"
            else
                # Show current priority
                echo "[$item_id] $current_title"
                echo "  Priority: $current_priority"
            fi
            ;;

        due|deadline)
            local selector="$1"
            local new_due="$2"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog due <id> <YYYY-MM-DD>"
                echo "       kb-backlog due <id> -        (clear due date)"
                echo ""
                echo "Set or clear the due date for a backlog item."
                echo "Due dates appear as colored pills in LCARS UI."
                echo ""
                echo "Color coding:"
                echo "  Overdue: Red (pulsing)"
                echo "  Today: Orange"
                echo "  1-7 days: Green→Orange gradient"
                echo "  8+ days: Dark green"
                echo ""
                echo "Example: kb-backlog due XFRE-0001 2026-01-20"
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Handle clearing due date with "-"
            if [[ "$new_due" == "-" ]]; then
                local old_due_val
                old_due_val=$(_kb_jq_read "$board_file" ".backlog[$index].dueDate // empty" -r)
                _kb_jq_update "$board_file" \
                   'del(.backlog[$idx].dueDate) | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Cleared due date for [$item_id]: $current_title"
                # Activity log: due date cleared
                _kb_log_activity "field_update" "$item_id" "item" "dueDate" "$old_due_val" "" "cleared"
            elif [[ -n "$new_due" ]]; then
                # Validate date format (YYYY-MM-DD)
                if [[ ! "$new_due" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
                    echo "Error: Invalid date format. Use YYYY-MM-DD (e.g., 2026-01-20)"
                    return 1
                fi
                local old_due_val
                old_due_val=$(_kb_jq_read "$board_file" ".backlog[$index].dueDate // empty" -r)
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].dueDate = $due | .backlog[$idx].updatedAt = $timestamp | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg due "$new_due" \
                   --arg timestamp "$timestamp"
                echo "✓ Set due date for [$item_id]: $current_title"
                echo "  Due: $new_due"
                # Activity log: due date set
                _kb_log_activity "field_update" "$item_id" "item" "dueDate" "$old_due_val" "$new_due" ""
            else
                # Show current due date
                local current_due
                current_due=$(_kb_jq_read "$board_file" ".backlog[$index].dueDate // empty" -r)
                echo "[$item_id] $current_title"
                if [[ -n "$current_due" ]]; then
                    echo "  Due: $current_due"
                else
                    echo "  (no due date)"
                fi
            fi
            ;;

        toggle)
            local selector="$1"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog toggle <id>"
                echo "Toggle collapsed state for a backlog item with subitems."
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp current_collapsed
            timestamp=$(_kb_get_timestamp)
            # Note: Can't use // true because jq treats false the same as null
            current_collapsed=$(_kb_jq_read "$board_file" "if .backlog[$index].collapsed == null then true else .backlog[$index].collapsed end" -r)

            if [[ "$current_collapsed" == "true" ]]; then
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].collapsed = false | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Expanded [$item_id]: $current_title"
            else
                _kb_jq_update "$board_file" \
                   '.backlog[$idx].collapsed = true | .lastUpdated = $timestamp' \
                   --argjson idx "$index" \
                   --arg timestamp "$timestamp"
                echo "✓ Collapsed [$item_id]: $current_title"
            fi
            ;;

        unpick)
            local selector="$1"

            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog unpick <id>"
                echo "Clears the actively working flag on a backlog item."
                return 1
            fi

            # Resolve selector to index
            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")

            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            # Check if item exists
            local current_title item_id
            current_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // empty" -r)
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // empty" -r)

            if [[ -z "$current_title" ]]; then
                echo "Error: Item not found: $selector"
                return 1
            fi

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Clear activelyWorking flag and worktree info
            _kb_jq_update "$board_file" \
               'del(.backlog[$idx].activelyWorking) |
                del(.backlog[$idx].workStartedAt) |
                del(.backlog[$idx].worktree) |
                del(.backlog[$idx].worktreeBranch) |
                del(.backlog[$idx].worktreeWindowId) |
                .lastUpdated = $timestamp' \
               --argjson idx "$index" \
               --arg timestamp "$timestamp"

            echo "✓ Stopped working on [$item_id]: $current_title"
            ;;

        sub|subitem)
            local subcmd="$1"
            shift 2>/dev/null

            case "$subcmd" in
                add)
                    local parent_selector="$1"
                    local sub_title="$2"
                    local sub_jira="$3"
                    local sub_os_param="$4"

                    if [[ -z "$parent_selector" ]] || [[ -z "$sub_title" ]]; then
                        echo "Usage: kb-backlog sub add <parent-id> \"title\" [jira-id] [os]"
                        echo "OS: Optional platform - iOS | Android | Firebase"
                        return 1
                    fi

                    # Validate and normalize OS parameter (case-insensitive)
                    local sub_normalized_os=""
                    if [[ -n "$sub_os_param" ]]; then
                        local sub_os_lower="${sub_os_param,,}"  # Convert to lowercase
                        case "$sub_os_lower" in
                            ios) sub_normalized_os="iOS" ;;
                            android) sub_normalized_os="Android" ;;
                            firebase) sub_normalized_os="Firebase" ;;
                            *)
                                echo "Error: Invalid OS '$sub_os_param'"
                                echo "Valid OS values: iOS | Android | Firebase"
                                return 1
                                ;;
                        esac
                    fi

                    # Resolve parent selector
                    local parent_idx
                    parent_idx=$(_kb_resolve_selector "$board_file" "$parent_selector")

                    if [[ "$parent_idx" == "-1" ]]; then
                        echo "Error: Parent item not found: $parent_selector"
                        return 1
                    fi

                    # Check parent exists
                    local parent_title parent_id
                    parent_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].title // empty" -r)
                    parent_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].id // empty" -r)
                    if [[ -z "$parent_title" ]]; then
                        echo "Error: Parent item not found: $parent_selector"
                        return 1
                    fi

                    local timestamp sub_id sub_count
                    timestamp=$(_kb_get_timestamp)
                    # Generate subitem ID: <parent-id>-### (3 digits starting at 001)
                    sub_count=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems // [] | length" -r)
                    sub_id=$(printf "%s-%03d" "$parent_id" "$((sub_count + 1))")

                    # Build subitem with optional JIRA and OS
                    local jq_filter='.backlog[$idx].subitems = ((.backlog[$idx].subitems // []) + [{"id": $subid, "title": $title, "status": "todo", "addedAt": $ts'
                    local jq_args=(--argjson idx "$parent_idx" --arg subid "$sub_id" --arg title "$sub_title" --arg ts "$timestamp")

                    if [[ -n "$sub_jira" ]]; then
                        jq_filter+=', "jiraKey": $jira'
                        jq_args+=(--arg jira "$sub_jira")
                    fi

                    # Add OS as first element of tags array if specified
                    if [[ -n "$sub_normalized_os" ]]; then
                        jq_filter+=', "tags": [$os]'
                        jq_args+=(--arg os "$sub_normalized_os")
                    fi

                    jq_filter+='}]) | .lastUpdated = $ts'

                    _kb_jq_update "$board_file" "$jq_filter" "${jq_args[@]}"
                    echo "✓ Added subitem to [$parent_id]: $sub_title"
                    [[ -n "$sub_normalized_os" ]] && echo "  OS: $sub_normalized_os"

                    # Activity log: subitem added (target is subitem ID, logged under parent)
                    _kb_log_activity "subitem_added" "$sub_id" "subitem" "title" "" "$sub_title" "parent=$parent_id"
                    ;;

                list|ls)
                    local parent_idx="$1"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub list <parent-index>"
                        return 1
                    fi

                    local parent_title
                    parent_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].title // empty" -r)
                    if [[ -z "$parent_title" ]]; then
                        echo "Error: No item at index $parent_idx"
                        return 1
                    fi

                    local sub_count
                    sub_count=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems // [] | length" -r)

                    echo "[$parent_idx] $parent_title"
                    echo "─────────────────────────────────────"
                    if [[ "$sub_count" -eq 0 ]]; then
                        echo "  (no subitems)"
                    else
                        _kb_jq_read "$board_file" ".backlog[$parent_idx].subitems | to_entries[] | \"  [\(.key)] [\(.value.status | ascii_upcase | .[0:4])] \(.value.title)\(if .value.jiraKey then \" (\(.value.jiraKey))\" else \"\" end)\"" --argjson idx "$parent_idx" -r
                    fi
                    ;;

                remove|rm)
                    local parent_idx="$1"
                    local sub_idx="$2"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub remove <parent-index> <subitem-index>"
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    _kb_jq_update "$board_file" \
                       'del(.backlog[$pidx].subitems[$sidx]) | .lastUpdated = $ts' \
                       --argjson pidx "$parent_idx" \
                       --argjson sidx "$sub_idx" \
                       --arg ts "$timestamp"
                    echo "✓ Removed subitem: $sub_title"
                    ;;

                done)
                    local arg1="$1"
                    local arg2="$2"
                    local parent_idx sub_idx

                    if [[ -z "$arg1" ]]; then
                        echo "Usage: kb-backlog sub done <subitem-id>"
                        echo "   or: kb-backlog sub done <parent-id> <subitem-index>"
                        echo "Marks subitem as completed."
                        return 1
                    fi

                    # Check if it's a single subitem ID (e.g., XFRE-0001-001)
                    if [[ -z "$arg2" ]] && [[ "$arg1" =~ ^X[A-Z]{2,4}-[0-9]+-[0-9]+$ ]]; then
                        # Single argument: subitem ID
                        local resolved
                        resolved=$(_kb_resolve_subitem_id "$board_file" "$arg1")
                        parent_idx="${resolved%%:*}"
                        sub_idx="${resolved##*:}"

                        if [[ "$parent_idx" == "-1" ]]; then
                            echo "Error: Subitem not found: $arg1"
                            return 1
                        fi
                    elif [[ -n "$arg2" ]] && [[ "$arg2" =~ ^[0-9]+$ ]]; then
                        # Two arguments: parent selector + subitem index
                        parent_idx=$(_kb_resolve_selector "$board_file" "$arg1")
                        sub_idx="$arg2"

                        if [[ "$parent_idx" == "-1" ]]; then
                            echo "Error: Parent item not found: $arg1"
                            return 1
                        fi
                    else
                        echo "Usage: kb-backlog sub done <subitem-id>"
                        echo "   or: kb-backlog sub done <parent-id> <subitem-index>"
                        return 1
                    fi

                    local sub_title sub_id sub_old_status
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    sub_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].id // empty" -r)
                    sub_old_status=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].status // \"todo\"" -r)

                    if [[ -z "$sub_title" ]]; then
                        echo "Error: Subitem not found at index $sub_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    # XACA-0029: Calculate and accumulate work time
                    local work_started_at existing_time_ms total_time_ms
                    work_started_at=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].workStartedAt // empty" -r)
                    existing_time_ms=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].timeWorkedMs // 0")
                    total_time_ms="$existing_time_ms"

                    if [[ -n "$work_started_at" ]]; then
                        # Calculate elapsed time in milliseconds
                        local start_epoch now_epoch elapsed_ms
                        # Strip Z suffix and parse as UTC (macOS date -j -f ignores timezone suffix)
                        start_epoch=$(TZ=UTC date -j -f "%Y-%m-%dT%H:%M:%S" "${${work_started_at%\.[0-9]*}%Z}" "+%s" 2>/dev/null || echo "0")
                        now_epoch=$(date -u "+%s")
                        if [[ "$start_epoch" != "0" ]] && [[ "$start_epoch" -gt 0 ]]; then
                            elapsed_ms=$(( (now_epoch - start_epoch) * 1000 ))
                            total_time_ms=$(( existing_time_ms + elapsed_ms ))
                        fi
                    fi

                    _kb_jq_update "$board_file" \
                       '.backlog[$pidx].subitems[$sidx].status = "completed" |
                        .backlog[$pidx].subitems[$sidx].completedAt = $ts |
                        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                        .backlog[$pidx].subitems[$sidx].timeWorkedMs = ($timeMs | tonumber) |
                        .backlog[$pidx].updatedAt = $ts |
                        del(.backlog[$pidx].subitems[$sidx].activelyWorking) |
                        del(.backlog[$pidx].subitems[$sidx].workStartedAt) |
                        del(.backlog[$pidx].subitems[$sidx].worktree) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeBranch) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeWindowId) |
                        .lastUpdated = $ts' \
                       --argjson pidx "$parent_idx" \
                       --argjson sidx "$sub_idx" \
                       --arg ts "$timestamp" \
                       --arg timeMs "$total_time_ms"
                    echo "✓ Completed [$sub_id]: $sub_title"

                    # XACA-0125: Blocking retrospective file check
                    # If this is a Retrospective subitem, validate that the retro file AND
                    # at least one knowledge entry exist before allowing completion.
                    if [[ "$sub_title" == Retrospective* ]]; then
                        local retro_parent_id retro_path retro_ok=true
                        retro_parent_id="${sub_id%-*}"

                        retro_path=$(kb-retro-path "$retro_parent_id" 2>/dev/null)
                        if [[ -z "$retro_path" ]] || [[ ! -f "$retro_path" ]]; then
                            echo ""
                            echo "🚫 BLOCKING: Retrospective file missing for $retro_parent_id"
                            if [[ -n "$retro_path" ]]; then
                                echo "   Expected: $retro_path"
                            else
                                echo "   Could not resolve path (no plan document found)."
                            fi
                            echo "   Create the retrospective file before marking this subitem done."
                            echo "   Template: ${AITEAMFORGE_DIR}/~/knowledge/templates/retrospective_template.md"
                            retro_ok=false
                        fi

                        if $retro_ok; then
                            # Also check for at least one knowledge entry
                            local retro_knowledge_dir retro_id_team retro_kanban_dir retro_knowledge_count=0
                            retro_id_team=$(_kb_get_team_from_code "$retro_parent_id")
                            if [[ -n "$retro_id_team" ]]; then
                                retro_kanban_dir=$(_kb_get_kanban_dir "$retro_id_team")
                                retro_knowledge_dir="${retro_kanban_dir}/knowledge"
                                if [[ -d "$retro_knowledge_dir" ]]; then
                                    retro_knowledge_count=$(grep -rl "$retro_parent_id" "$retro_knowledge_dir" 2>/dev/null | wc -l | tr -d ' ')
                                fi
                            fi
                            if [[ "$retro_knowledge_count" -eq 0 ]]; then
                                echo ""
                                echo "🚫 BLOCKING: No knowledge entries referencing $retro_parent_id found."
                                echo "   Create at least one knowledge entry before marking this subitem done."
                                echo "   See: ~/knowledge/templates/knowledge_entry_template.md"
                                retro_ok=false
                            fi
                        fi

                        if ! $retro_ok; then
                            # Revert status back to in_progress
                            _kb_jq_update "$board_file" \
                               '.backlog[$pidx].subitems[$sidx].status = "in_progress" |
                                .backlog[$pidx].subitems[$sidx].activelyWorking = true |
                                .backlog[$pidx].subitems[$sidx].workStartedAt = $ts |
                                .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                                del(.backlog[$pidx].subitems[$sidx].completedAt) |
                                .backlog[$pidx].updatedAt = $ts |
                                .lastUpdated = $ts' \
                               --argjson pidx "$parent_idx" \
                               --argjson sidx "$sub_idx" \
                               --arg ts "$timestamp"
                            echo "   Status reverted to [in_progress]. Complete the retrospective requirements and try again."
                            # Log the attempted completion and revert
                            _kb_log_activity "subitem_status_change" "$sub_id" "subitem" "status" "$sub_old_status" "in_progress" "retro validation failed — reverted"
                            return 1
                        fi

                        echo "  ✅ Retrospective file verified: $(basename "$retro_path")"
                        echo "  ✅ Knowledge entries found: $retro_knowledge_count"
                    fi

                    # Activity log: subitem status changed to completed
                    _kb_log_activity "subitem_status_change" "$sub_id" "subitem" "status" "$sub_old_status" "completed" ""

                    # XACA-0054: Sync to release manifests via LCARS server
                    _kb_release_sync "$sub_id"

                    # Clear working-on state since subitem is done
                    _kb_clear_working_on

                    # XACA-0025: Trigger auto-unblock for items blocked by this subitem
                    if [[ -n "$sub_id" ]]; then
                        _kb_check_unblock_dependents "$board_file" "$sub_id"
                    fi
                    ;;

                cancel)
                    local arg1="$1"
                    local arg2="$2"
                    local arg3="$3"
                    local parent_idx sub_idx reason=""

                    # Parse --reason flag
                    if [[ "$arg1" == "--reason" ]]; then
                        reason="$arg2"
                        arg1="$arg3"
                        arg2=""
                    elif [[ "$arg2" == "--reason" ]]; then
                        reason="$arg3"
                        arg2=""
                    fi

                    if [[ -z "$arg1" ]]; then
                        echo "Usage: kb-backlog sub cancel <subitem-id> [--reason \"text\"]"
                        echo "Marks subitem as cancelled."
                        return 1
                    fi

                    # Check if it's a single subitem ID (e.g., XFRE-0001-001)
                    if [[ -z "$arg2" ]] && [[ "$arg1" =~ ^X[A-Z]{2,4}-[0-9]+-[0-9]+$ ]]; then
                        # Single argument: subitem ID
                        local resolved
                        resolved=$(_kb_resolve_subitem_id "$board_file" "$arg1")
                        parent_idx="${resolved%%:*}"
                        sub_idx="${resolved##*:}"

                        if [[ "$parent_idx" == "-1" ]]; then
                            echo "Error: Subitem not found: $arg1"
                            return 1
                        fi
                    else
                        echo "Usage: kb-backlog sub cancel <subitem-id> [--reason \"text\"]"
                        return 1
                    fi

                    local sub_title sub_id sub_old_status
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    sub_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].id // empty" -r)
                    sub_old_status=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].status // \"todo\"" -r)

                    if [[ -z "$sub_title" ]]; then
                        echo "Error: Subitem not found at index $sub_idx"
                        return 1
                    fi

                    # XACA-0113: Soft warning for [Review] and [Test] subitems
                    if [[ "${sub_title:l}" == *"[review]"* ]] || [[ "${sub_title:l}" == *"[test]"* ]]; then
                        echo "⚠️  PROTECTED SUBITEM: '[Review]'/'[Test]' subitems require user approval to cancel."
                        echo "If you are an agent, STOP and ask the user for permission before proceeding."
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    local update_jq='.backlog[$pidx].subitems[$sidx].status = "cancelled" |
                       .backlog[$pidx].subitems[$sidx].cancelledAt = $ts |
                       .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                       .backlog[$pidx].updatedAt = $ts |
                       del(.backlog[$pidx].subitems[$sidx].activelyWorking) |
                       del(.backlog[$pidx].subitems[$sidx].workStartedAt) |
                       del(.backlog[$pidx].subitems[$sidx].worktree) |
                       del(.backlog[$pidx].subitems[$sidx].worktreeBranch) |
                       del(.backlog[$pidx].subitems[$sidx].worktreeWindowId)'
                    if [[ -n "$reason" ]]; then
                        update_jq="$update_jq | .backlog[\$pidx].subitems[\$sidx].cancelledReason = \$reason"
                    fi
                    update_jq="$update_jq | .lastUpdated = \$ts"

                    if [[ -n "$reason" ]]; then
                        _kb_jq_update "$board_file" "$update_jq" \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp" \
                           --arg reason "$reason"
                    else
                        _kb_jq_update "$board_file" "$update_jq" \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp"
                    fi
                    echo "✓ Cancelled [$sub_id]: $sub_title"

                    # Activity log: subitem cancelled
                    _kb_log_activity "subitem_cancelled" "$sub_id" "subitem" "status" "$sub_old_status" "cancelled" "${reason:-}"

                    # XACA-0054: Sync to release manifests via LCARS server
                    if type _kb_release_sync >/dev/null 2>&1; then
                        _kb_release_sync "$sub_id"
                    fi

                    # Clear working-on state since subitem is cancelled
                    _kb_clear_working_on

                    # XACA-0075: Trigger auto-unblock for items blocked by this subitem
                    if [[ -n "$sub_id" ]]; then
                        _kb_check_unblock_dependents "$board_file" "$sub_id"
                    fi
                    ;;

                todo)
                    local parent_idx="$1"
                    local sub_idx="$2"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub todo <parent-index> <subitem-index>"
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    # XACA-0029: Calculate and accumulate work time if actively working
                    local work_started_at existing_time_ms total_time_ms
                    work_started_at=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].workStartedAt // empty" -r)
                    existing_time_ms=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].timeWorkedMs // 0")
                    total_time_ms="$existing_time_ms"

                    if [[ -n "$work_started_at" ]]; then
                        # Calculate elapsed time in milliseconds
                        local start_epoch now_epoch elapsed_ms
                        # Strip Z suffix and parse as UTC (macOS date -j -f ignores timezone suffix)
                        start_epoch=$(TZ=UTC date -j -f "%Y-%m-%dT%H:%M:%S" "${${work_started_at%\.[0-9]*}%Z}" "+%s" 2>/dev/null || echo "0")
                        now_epoch=$(date -u "+%s")
                        if [[ "$start_epoch" != "0" ]] && [[ "$start_epoch" -gt 0 ]]; then
                            elapsed_ms=$(( (now_epoch - start_epoch) * 1000 ))
                            total_time_ms=$(( existing_time_ms + elapsed_ms ))
                        fi
                    fi

                    _kb_jq_update "$board_file" \
                       '.backlog[$pidx].subitems[$sidx].status = "todo" |
                        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                        (if $timeMs != "0" then .backlog[$pidx].subitems[$sidx].timeWorkedMs = ($timeMs | tonumber) else . end) |
                        del(.backlog[$pidx].subitems[$sidx].activelyWorking) |
                        del(.backlog[$pidx].subitems[$sidx].workStartedAt) |
                        del(.backlog[$pidx].subitems[$sidx].worktree) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeBranch) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeWindowId) |
                        .lastUpdated = $ts' \
                       --argjson pidx "$parent_idx" \
                       --argjson sidx "$sub_idx" \
                       --arg ts "$timestamp" \
                       --arg timeMs "$total_time_ms"
                    echo "✓ Reset to todo: $sub_title"
                    ;;

                jira)
                    local parent_idx="$1"
                    local sub_idx="$2"
                    local jira_id="$3"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub jira <parent-index> <subitem-index> <JIRA-ID>"
                        echo "       kb-backlog sub jira <parent-index> <subitem-index> -  (clear)"
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    if [[ "$jira_id" == "-" ]]; then
                        _kb_jq_update "$board_file" \
                           'del(.backlog[$pidx].subitems[$sidx].jiraKey) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp"
                        echo "✓ Cleared JIRA ID for: $sub_title"
                    elif [[ -n "$jira_id" ]]; then
                        # Validate Jira ID (warns but allows)
                        _kb_validate_jira_id "$jira_id"

                        _kb_jq_update "$board_file" \
                           '.backlog[$pidx].subitems[$sidx].jiraKey = $jira | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg jira "$jira_id" \
                           --arg ts "$timestamp"
                        echo "✓ Set JIRA ID for: $sub_title -> $jira_id"
                    else
                        local current_jira
                        current_jira=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].jiraKey // empty" -r)
                        echo "Subitem: $sub_title"
                        if [[ -n "$current_jira" ]]; then
                            echo "  JIRA: $current_jira"
                        else
                            echo "  (no JIRA ID)"
                        fi
                    fi
                    ;;

                github|gh)
                    local parent_idx="$1"
                    local sub_idx="$2"
                    local gh_issue="$3"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub github <parent-index> <subitem-index> <issue-ref>"
                        echo "       kb-backlog sub github <parent-index> <subitem-index> -  (clear)"
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    if [[ "$gh_issue" == "-" ]]; then
                        _kb_jq_update "$board_file" \
                           'del(.backlog[$pidx].subitems[$sidx].githubIssue) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp"
                        echo "✓ Cleared GitHub issue for: $sub_title"
                    elif [[ -n "$gh_issue" ]]; then
                        _kb_jq_update "$board_file" \
                           '.backlog[$pidx].subitems[$sidx].githubIssue = $gh | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg gh "$gh_issue" \
                           --arg ts "$timestamp"
                        echo "✓ Set GitHub issue for: $sub_title -> $gh_issue"
                    else
                        local current_gh
                        current_gh=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].githubIssue // empty" -r)
                        echo "Subitem: $sub_title"
                        if [[ -n "$current_gh" ]]; then
                            echo "  GitHub: $current_gh"
                        else
                            echo "  (no GitHub issue)"
                        fi
                    fi
                    ;;

                start)
                    local arg1="$1"
                    local arg2="$2"
                    local parent_idx sub_idx

                    if [[ -z "$arg1" ]]; then
                        echo "Usage: kb-backlog sub start <subitem-id>"
                        echo "   or: kb-backlog sub start <parent-id> <subitem-index>"
                        echo "Marks subitem as in_progress and sets it as actively working."
                        return 1
                    fi

                    # Check if it's a single subitem ID (e.g., XFRE-0001-001)
                    if [[ -z "$arg2" ]] && [[ "$arg1" =~ ^X[A-Z]{2,4}-[0-9]+-[0-9]+$ ]]; then
                        # Single argument: subitem ID
                        local resolved
                        resolved=$(_kb_resolve_subitem_id "$board_file" "$arg1")
                        parent_idx="${resolved%%:*}"
                        sub_idx="${resolved##*:}"

                        if [[ "$parent_idx" == "-1" ]]; then
                            echo "Error: Subitem not found: $arg1"
                            return 1
                        fi
                    elif [[ -n "$arg2" ]] && [[ "$arg2" =~ ^[0-9]+$ ]]; then
                        # Two arguments: parent selector + subitem index
                        parent_idx=$(_kb_resolve_selector "$board_file" "$arg1")
                        sub_idx="$arg2"

                        if [[ "$parent_idx" == "-1" ]]; then
                            echo "Error: Parent item not found: $arg1"
                            return 1
                        fi
                    else
                        echo "Usage: kb-backlog sub start <subitem-id>"
                        echo "   or: kb-backlog sub start <parent-id> <subitem-index>"
                        return 1
                    fi

                    local sub_title sub_id sub_old_status
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    sub_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].id // empty" -r)
                    sub_old_status=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].status // \"todo\"" -r)

                    if [[ -z "$sub_title" ]]; then
                        echo "Error: Subitem not found at index $sub_idx"
                        return 1
                    fi

                    local timestamp worktree worktree_branch window_id
                    timestamp=$(_kb_get_timestamp)
                    worktree=$(_kb_get_worktree)
                    worktree_branch=$(git branch --show-current 2>/dev/null || echo "")

                    # Get window ID for linking
                    local wt_context wt_rest wt_terminal wt_window_name
                    wt_context=$(_kb_detect_context)
                    wt_rest="${wt_context#*:}"
                    wt_terminal="${wt_rest%%:*}"
                    wt_rest="${wt_rest#*:}"
                    wt_window_name="${wt_rest#*:}"
                    window_id=$(_kb_get_window_id "$wt_terminal" "$wt_window_name")

                    # Check for worktree conflicts before starting
                    if [[ -n "$worktree" ]]; then
                        local conflict
                        conflict=$(_kb_check_worktree_conflict "$board_file" "$sub_id" "$worktree")
                        if [[ -n "$conflict" ]]; then
                            _kb_warn_worktree_conflict "$conflict"
                        fi
                    fi

                    # Mark subitem as in_progress and actively working with worktree info
                    _kb_jq_update "$board_file" \
                       '.backlog[$pidx].subitems[$sidx].status = "in_progress" |
                        .backlog[$pidx].subitems[$sidx].activelyWorking = true |
                        .backlog[$pidx].subitems[$sidx].workStartedAt = $ts |
                        .backlog[$pidx].subitems[$sidx].startedAt //= $ts |
                        .backlog[$pidx].subitems[$sidx].worktree = $wt |
                        .backlog[$pidx].subitems[$sidx].worktreeBranch = $wtb |
                        .backlog[$pidx].subitems[$sidx].worktreeWindowId = $wid |
                        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                        .backlog[$pidx].updatedAt = $ts |
                        .lastUpdated = $ts' \
                       --argjson pidx "$parent_idx" \
                       --argjson sidx "$sub_idx" \
                       --arg ts "$timestamp" \
                       --arg wt "$worktree" \
                       --arg wtb "$worktree_branch" \
                       --arg wid "$window_id"

                    # Start planning with this task and set working item (use subitem ID)
                    kb-plan "$sub_title"
                    _kb_set_working_on "$sub_id" "DEV"
                    echo "✓ Started subitem [$sub_id]: $sub_title"

                    # Activity log: subitem status changed to in_progress
                    _kb_log_activity "subitem_status_change" "$sub_id" "subitem" "status" "$sub_old_status" "in_progress" ""
                    ;;

                stop)
                    local parent_idx="$1"
                    local sub_idx="$2"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub stop <parent-index> <subitem-index>"
                        echo "Clears the actively working flag on a subitem."
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    # XACA-0029: Calculate and accumulate work time
                    local work_started_at existing_time_ms total_time_ms
                    work_started_at=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].workStartedAt // empty" -r)
                    existing_time_ms=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].timeWorkedMs // 0")
                    total_time_ms="$existing_time_ms"

                    if [[ -n "$work_started_at" ]]; then
                        # Calculate elapsed time in milliseconds
                        local start_epoch now_epoch elapsed_ms
                        # Strip Z suffix and parse as UTC (macOS date -j -f ignores timezone suffix)
                        start_epoch=$(TZ=UTC date -j -f "%Y-%m-%dT%H:%M:%S" "${${work_started_at%\.[0-9]*}%Z}" "+%s" 2>/dev/null || echo "0")
                        now_epoch=$(date -u "+%s")
                        if [[ "$start_epoch" != "0" ]] && [[ "$start_epoch" -gt 0 ]]; then
                            elapsed_ms=$(( (now_epoch - start_epoch) * 1000 ))
                            total_time_ms=$(( existing_time_ms + elapsed_ms ))
                        fi
                    fi

                    # Clear activelyWorking flag and worktree info, accumulate time
                    _kb_jq_update "$board_file" \
                       '(if $timeMs != "0" then .backlog[$pidx].subitems[$sidx].timeWorkedMs = ($timeMs | tonumber) else . end) |
                        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                        del(.backlog[$pidx].subitems[$sidx].activelyWorking) |
                        del(.backlog[$pidx].subitems[$sidx].workStartedAt) |
                        del(.backlog[$pidx].subitems[$sidx].worktree) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeBranch) |
                        del(.backlog[$pidx].subitems[$sidx].worktreeWindowId) |
                        .lastUpdated = $ts' \
                       --argjson pidx "$parent_idx" \
                       --argjson sidx "$sub_idx" \
                       --arg ts "$timestamp" \
                       --arg timeMs "$total_time_ms"

                    echo "✓ Stopped working on: $sub_title"
                    ;;

                tag|tags)
                    local parent_idx="$1"
                    local sub_idx="$2"
                    shift 2 2>/dev/null
                    local tag_args=("$@")

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub tag <parent-idx> <sub-idx> [add|rm|clear] [tags...]"
                        echo ""
                        echo "Manage tags for a subitem. Tags appear as clickable pills in LCARS UI."
                        echo ""
                        echo "Commands:"
                        echo "  kb-backlog sub tag <p> <s>                View current tags"
                        echo "  kb-backlog sub tag <p> <s> add tag1 ...   Add tags"
                        echo "  kb-backlog sub tag <p> <s> rm tag1 ...    Remove tags"
                        echo "  kb-backlog sub tag <p> <s> clear          Clear all tags"
                        echo "  kb-backlog sub tag <p> <s> tag1 tag2      Set tags (replaces)"
                        return 1
                    fi

                    local sub_title parent_item_id
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    parent_item_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].id // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    # No args - show current tags
                    if [[ ${#tag_args[@]} -eq 0 ]]; then
                        local current_tags
                        current_tags=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].tags // [] | join(\", \")" -r)
                        echo "[$parent_idx.$sub_idx] $sub_title"
                        if [[ -n "$current_tags" ]]; then
                            echo "  Tags: $current_tags"
                        else
                            echo "  (no tags)"
                        fi
                        return 0
                    fi

                    local tag_subcmd="${tag_args[1]}"

                    case "$tag_subcmd" in
                        add)
                            local new_tags=("${tag_args[@]:1}")
                            if [[ ${#new_tags[@]} -eq 0 ]]; then
                                echo "Usage: kb-backlog sub tag <p> <s> add tag1 tag2 ..."
                                return 1
                            fi
                            local tags_json
                            tags_json=$(printf '%s\n' "${new_tags[@]}" | jq -R . | jq -s .)
                            _kb_jq_update "$board_file" \
                               '.backlog[$pidx].subitems[$sidx].tags = ((.backlog[$pidx].subitems[$sidx].tags // []) + $tags | unique) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                               --argjson pidx "$parent_idx" \
                               --argjson sidx "$sub_idx" \
                               --argjson tags "$tags_json" \
                               --arg ts "$timestamp"
                            echo "✓ Added tags to [$parent_idx.$sub_idx]: ${new_tags[*]}"

                            # Sync parent item to release manifests (best-effort)
                            _kb_release_sync "$parent_item_id"
                            ;;

                        rm|remove)
                            local rm_tags=("${tag_args[@]:1}")
                            if [[ ${#rm_tags[@]} -eq 0 ]]; then
                                echo "Usage: kb-backlog sub tag <p> <s> rm tag1 tag2 ..."
                                return 1
                            fi
                            local rm_json
                            rm_json=$(printf '%s\n' "${rm_tags[@]}" | jq -R . | jq -s .)
                            _kb_jq_update "$board_file" \
                               '.backlog[$pidx].subitems[$sidx].tags = ((.backlog[$pidx].subitems[$sidx].tags // []) - $tags) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                               --argjson pidx "$parent_idx" \
                               --argjson sidx "$sub_idx" \
                               --argjson tags "$rm_json" \
                               --arg ts "$timestamp"
                            echo "✓ Removed tags from [$parent_idx.$sub_idx]: ${rm_tags[*]}"

                            # Sync parent item to release manifests (best-effort)
                            _kb_release_sync "$parent_item_id"
                            ;;

                        clear)
                            _kb_jq_update "$board_file" \
                               'del(.backlog[$pidx].subitems[$sidx].tags) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                               --argjson pidx "$parent_idx" \
                               --argjson sidx "$sub_idx" \
                               --arg ts "$timestamp"
                            echo "✓ Cleared all tags from [$parent_idx.$sub_idx]: $sub_title"

                            # Sync parent item to release manifests (best-effort)
                            _kb_release_sync "$parent_item_id"
                            ;;

                        *)
                            # Set tags directly (replaces existing)
                            local set_tags=("${tag_args[@]}")
                            local set_json
                            set_json=$(printf '%s\n' "${set_tags[@]}" | jq -R . | jq -s .)
                            _kb_jq_update "$board_file" \
                               '.backlog[$pidx].subitems[$sidx].tags = $tags | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                               --argjson pidx "$parent_idx" \
                               --argjson sidx "$sub_idx" \
                               --argjson tags "$set_json" \
                               --arg ts "$timestamp"
                            echo "✓ Set tags for [$parent_idx.$sub_idx]: ${set_tags[*]}"

                            # Sync parent item to release manifests (best-effort)
                            _kb_release_sync "$parent_item_id"
                            ;;
                    esac
                    ;;

                priority|pri)
                    local parent_idx="$1"
                    local sub_idx="$2"
                    local new_priority="$3"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub priority <parent-idx> <sub-idx> [priority]"
                        echo "       kb-backlog sub priority <parent-idx> <sub-idx> -  (reset to medium)"
                        echo ""
                        echo "Valid priorities: low, medium (med), high, critical (crit), blocked (block)"
                        return 1
                    fi

                    local sub_title current_priority parent_item_id
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    current_priority=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].priority // \"medium\"" -r)
                    parent_item_id=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].id // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    if [[ "$new_priority" == "-" ]]; then
                        _kb_jq_update "$board_file" \
                           '.backlog[$pidx].subitems[$sidx].priority = "medium" | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp"
                        echo "✓ Reset priority to medium for: $sub_title"

                        # Sync parent item to release manifests (best-effort)
                        _kb_release_sync "$parent_item_id"
                    elif [[ -n "$new_priority" ]]; then
                        # Normalize priority aliases
                        case "$new_priority" in
                            med) new_priority="medium" ;;
                            crit) new_priority="critical" ;;
                            block) new_priority="blocked" ;;
                        esac

                        # Validate priority
                        if [[ ! "$new_priority" =~ ^(low|medium|high|critical|blocked)$ ]]; then
                            echo "Error: Invalid priority. Use: low, medium (med), high, critical (crit), or blocked (block)"
                            return 1
                        fi
                        _kb_jq_update "$board_file" \
                           '.backlog[$pidx].subitems[$sidx].priority = $priority | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg priority "$new_priority" \
                           --arg ts "$timestamp"
                        echo "✓ Set priority for: $sub_title -> $new_priority"

                        # Sync parent item to release manifests (best-effort)
                        _kb_release_sync "$parent_item_id"
                    else
                        echo "[$parent_idx.$sub_idx] $sub_title"
                        echo "  Priority: $current_priority"
                    fi
                    ;;

                due|deadline)
                    local parent_idx="$1"
                    local sub_idx="$2"
                    local new_due="$3"

                    if [[ -z "$parent_idx" ]] || [[ ! "$parent_idx" =~ ^[0-9]+$ ]] || [[ -z "$sub_idx" ]] || [[ ! "$sub_idx" =~ ^[0-9]+$ ]]; then
                        echo "Usage: kb-backlog sub due <parent-idx> <sub-idx> <YYYY-MM-DD>"
                        echo "       kb-backlog sub due <parent-idx> <sub-idx> -  (clear)"
                        return 1
                    fi

                    local sub_title
                    sub_title=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].title // empty" -r)
                    if [[ -z "$sub_title" ]]; then
                        echo "Error: No subitem at index $sub_idx in item $parent_idx"
                        return 1
                    fi

                    local timestamp
                    timestamp=$(_kb_get_timestamp)

                    if [[ "$new_due" == "-" ]]; then
                        _kb_jq_update "$board_file" \
                           'del(.backlog[$pidx].subitems[$sidx].dueDate) | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg ts "$timestamp"
                        echo "✓ Cleared due date for: $sub_title"
                    elif [[ -n "$new_due" ]]; then
                        # Validate date format (YYYY-MM-DD)
                        if [[ ! "$new_due" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
                            echo "Error: Invalid date format. Use YYYY-MM-DD (e.g., 2026-01-20)"
                            return 1
                        fi
                        _kb_jq_update "$board_file" \
                           '.backlog[$pidx].subitems[$sidx].dueDate = $due | .backlog[$pidx].subitems[$sidx].updatedAt = $ts | .backlog[$pidx].updatedAt = $ts | .lastUpdated = $ts' \
                           --argjson pidx "$parent_idx" \
                           --argjson sidx "$sub_idx" \
                           --arg due "$new_due" \
                           --arg ts "$timestamp"
                        echo "✓ Set due date for: $sub_title -> $new_due"
                    else
                        local current_due
                        current_due=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].dueDate // empty" -r)
                        echo "[$parent_idx.$sub_idx] $sub_title"
                        if [[ -n "$current_due" ]]; then
                            echo "  Due: $current_due"
                        else
                            echo "  (no due date)"
                        fi
                    fi
                    ;;

                *)
                    echo "Usage: kb-backlog sub <command> [args...]"
                    echo ""
                    echo "Subitem Commands:"
                    echo "  add <parent-idx> \"title\" [jira] [os]  Add subitem to backlog item"
                    echo "  list <parent-idx>                   List subitems"
                    echo "  remove <parent-idx> <sub-idx>       Remove subitem"
                    echo "  done <parent-idx> <sub-idx>         Mark subitem completed"
                    echo "  todo <parent-idx> <sub-idx>         Reset subitem to todo"
                    echo "  jira <parent-idx> <sub-idx> [id]    Set/view/clear JIRA ID"
                    echo "  github <parent-idx> <sub-idx> [ref] Set/view/clear GitHub issue"
                    echo "  tag <parent-idx> <sub-idx> [...]    Manage subitem tags"
                    echo "  priority <parent-idx> <sub-idx> [p] Set/view/reset priority"
                    echo "  due <parent-idx> <sub-idx> [date]   Set/view/clear due date"
                    echo "  start <parent-idx> <sub-idx>        Start working on subitem"
                    echo "  stop <parent-idx> <sub-idx>         Clear actively working flag"
                    echo ""
                    echo "OS: Optional platform - iOS | Android | Firebase"
                    echo ""
                    echo "Examples:"
                    echo "  kb-backlog sub add 0 \"Implement login\""
                    echo "  kb-backlog sub add 0 \"Fix logout\" ME-456"
                    echo "  kb-backlog sub add 0 \"iOS fix\" ME-789 iOS"
                    echo "  kb-backlog sub list 0"
                    echo "  kb-backlog sub done 0 1"
                    echo "  kb-backlog sub tag 0 1 iOS testing"
                    echo "  kb-backlog sub due 0 1 2026-01-20"
                    echo "  kb-backlog sub start 0 0"
                    echo "  kb-backlog sub stop 0 0"
                    return 1
                    ;;
            esac
            ;;

        cleanup)
            # Clear orphaned activelyWorking/worktree fields from items
            # that reference windows that no longer exist
            local window_id
            local terminal window_name

            # Parse current context
            local context_full
            context_full=$(_kb_detect_context)
            terminal="${context_full#*:}"
            terminal="${terminal%%:*}"
            window_name="${context_full##*:}"
            window_id="${terminal}:${window_name}"

            echo "Cleaning orphaned items for window: $window_id"

            # Call Python cleanup function
            python3 -c "
import sys
import importlib.util
spec = importlib.util.spec_from_file_location('kanban_stop', '${AITEAMFORGE_DIR}/kanban-hooks/kanban-stop.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
result = mod.clear_orphaned_item_fields('$team', '$terminal', '$window_name')
if result:
    print('✓ Cleanup complete')
else:
    print('No orphaned items found (or no changes needed)')
" 2>/dev/null

            ;;

        cleanup-all)
            # Clear ALL orphaned activelyWorking/worktree fields from items
            # regardless of which window they reference
            echo "Cleaning ALL orphaned items..."

            local timestamp
            timestamp=$(_kb_get_timestamp)

            # Find and clear all items with worktreeWindowId that don't have matching active windows
            _kb_jq_update "$board_file" '
                .activeWindows as $windows |
                ($windows | map(.id) | unique) as $active_ids |
                .backlog = [.backlog[] |
                    if (.worktreeWindowId != null) and ((.worktreeWindowId | IN($active_ids[])) | not) then
                        del(.activelyWorking, .worktree, .worktreeBranch, .worktreeWindowId) | .updatedAt = $ts
                    else . end |
                    .subitems = ((.subitems // []) | [.[] |
                        if (.worktreeWindowId != null) and ((.worktreeWindowId | IN($active_ids[])) | not) then
                            del(.activelyWorking, .worktree, .worktreeBranch, .worktreeWindowId) | .updatedAt = $ts
                        else . end
                    ])
                ] |
                .lastUpdated = $ts
            ' --arg ts "$timestamp"

            echo "✓ Cleanup complete"
            ;;

        block)
            # Block an item or subitem by one or more other items/subitems (XACA-0025)
            local target_id="$1"
            shift 2>/dev/null
            local blocker_ids=("$@")

            if [[ -z "$target_id" ]] || [[ ${#blocker_ids[@]} -eq 0 ]]; then
                echo "Usage: kb-backlog block <item-id|subitem-id> <blocker-id> [blocker-id2...]"
                echo ""
                echo "Mark an item or subitem as blocked by one or more other items/subitems."
                echo "The target will not be workable until all blockers are completed."
                echo ""
                echo "Examples:"
                echo "  kb-backlog block XACA-0016 XACA-0017           # Item blocked by item"
                echo "  kb-backlog block XACA-0016-001 XACA-0016-002   # Subitem blocked by subitem"
                echo "  kb-backlog block XACA-0016-003 XACA-0017       # Subitem blocked by item"
                return 1
            fi

            # Determine if target is a subitem (XACA-0025)
            if _kb_is_subitem_id "$target_id"; then
                # Target is a subitem - use subitem blocker functions
                for blocker_id in "${blocker_ids[@]}"; do
                    if _kb_add_subitem_blocker "$board_file" "$target_id" "$blocker_id"; then
                        echo "✓ $target_id blocked by $blocker_id"
                    fi
                done
            else
                # Existing parent item logic
                # Resolve target
                local target_index
                target_index=$(_kb_resolve_selector "$board_file" "$target_id")
                if [[ "$target_index" == "-1" ]]; then
                    echo "Error: Target item not found: $target_id"
                    return 1
                fi

                # Get the actual item ID (in case selector was an index)
                local actual_target_id
                actual_target_id=$(_kb_jq_read "$board_file" ".backlog[$target_index].id // empty" -r)

                # Add each blocker
                for blocker_id in "${blocker_ids[@]}"; do
                    # Validate blocker exists (same board or cross-board)
                    local blocker_board blocker_team
                    blocker_team=$(_kb_get_team_from_code "$blocker_id")
                    if [[ -n "$blocker_team" ]]; then
                        blocker_board=$(_kb_get_board_file "$blocker_team")
                    else
                        blocker_board="$board_file"
                    fi

                    local blocker_index
                    blocker_index=$(_kb_find_by_id "$blocker_board" "$blocker_id")
                    if [[ "$blocker_index" == "-1" ]]; then
                        echo "Warning: Blocker not found: $blocker_id (skipping)"
                        continue
                    fi

                    _kb_add_blocker "$board_file" "$actual_target_id" "$blocker_id"
                    echo "✓ $actual_target_id blocked by $blocker_id"
                done
            fi
            ;;

        unblock)
            # Remove blocker(s) from an item or subitem (XACA-0025)
            local target_id="$1"
            local blocker_id="$2"

            if [[ -z "$target_id" ]]; then
                echo "Usage: kb-backlog unblock <item-id|subitem-id> [blocker-id]"
                echo ""
                echo "Remove a specific blocker, or all blockers if none specified."
                echo ""
                echo "Examples:"
                echo "  kb-backlog unblock XACA-0016 XACA-0017       # Remove specific blocker from item"
                echo "  kb-backlog unblock XACA-0016                 # Remove all blockers from item"
                echo "  kb-backlog unblock XACA-0016-001 XACA-0016-002  # Remove blocker from subitem"
                echo "  kb-backlog unblock XACA-0016-001             # Remove all blockers from subitem"
                return 1
            fi

            # Determine if target is a subitem (XACA-0025)
            if _kb_is_subitem_id "$target_id"; then
                # Target is a subitem
                local indices
                indices=$(_kb_resolve_subitem_id "$board_file" "$target_id")
                if [[ "$indices" == "-1:-1" ]]; then
                    echo "Error: Subitem not found: $target_id"
                    return 1
                fi

                local parent_idx="${indices%%:*}"
                local sub_idx="${indices##*:}"
                local current_blockers
                current_blockers=$(_kb_jq_read "$board_file" ".backlog[$parent_idx].subitems[$sub_idx].blockedBy // [] | join(\", \")" -r)

                if [[ -z "$current_blockers" ]]; then
                    echo "Subitem $target_id is not blocked by anything"
                    return 0
                fi

                local timestamp
                timestamp=$(_kb_get_timestamp)

                if [[ -z "$blocker_id" ]]; then
                    # Remove all blockers from subitem
                    _kb_jq_update "$board_file" '
                        .backlog[$pidx].subitems[$sidx].status = "todo" |
                        del(.backlog[$pidx].subitems[$sidx].blockedBy) |
                        del(.backlog[$pidx].subitems[$sidx].blockedAt) |
                        .backlog[$pidx].subitems[$sidx].updatedAt = $ts |
                        .backlog[$pidx].updatedAt = $ts |
                        .lastUpdated = $ts
                    ' --argjson pidx "$parent_idx" --argjson sidx "$sub_idx" --arg ts "$timestamp"
                    echo "✓ Removed all blockers from $target_id"
                    echo "  Was blocked by: $current_blockers"
                else
                    # Remove specific blocker from subitem
                    _kb_remove_subitem_blocker "$board_file" "$target_id" "$blocker_id"
                    echo "✓ Removed blocker $blocker_id from $target_id"
                fi
            else
                # Existing parent item logic
                # Resolve target
                local target_index
                target_index=$(_kb_resolve_selector "$board_file" "$target_id")
                if [[ "$target_index" == "-1" ]]; then
                    echo "Error: Item not found: $target_id"
                    return 1
                fi

                local actual_target_id current_blockers
                actual_target_id=$(_kb_jq_read "$board_file" ".backlog[$target_index].id // empty" -r)
                current_blockers=$(_kb_jq_read "$board_file" ".backlog[$target_index].blockedBy // [] | join(\", \")" -r)

                if [[ -z "$current_blockers" ]]; then
                    echo "Item $actual_target_id is not blocked by anything"
                    return 0
                fi

                local timestamp
                timestamp=$(_kb_get_timestamp)

                if [[ -z "$blocker_id" ]]; then
                    # Remove all blockers
                    _kb_jq_update "$board_file" '
                        .backlog[$idx].status = "todo" |
                        del(.backlog[$idx].blockedBy) |
                        del(.backlog[$idx].blockedAt) |
                        .backlog[$idx].updatedAt = $ts |
                        .lastUpdated = $ts
                    ' --argjson idx "$target_index" --arg ts "$timestamp"
                    echo "✓ Removed all blockers from $actual_target_id"
                    echo "  Was blocked by: $current_blockers"

                    # XACA-0054: Sync to release manifests via LCARS server
                    _kb_release_sync "$actual_target_id"
                else
                    # Remove specific blocker
                    _kb_remove_blocker "$board_file" "$actual_target_id" "$blocker_id"
                    echo "✓ Removed blocker $blocker_id from $actual_target_id"

                    # XACA-0054: Sync to release manifests via LCARS server
                    _kb_release_sync "$actual_target_id"
                fi
            fi
            ;;

        blocked)
            # List all blocked items
            local blocked_count
            blocked_count=$(_kb_jq_read "$board_file" '[.backlog[] | select(.status == "blocked")] | length')

            echo "Blocked items for ${team}: ($blocked_count items)"
            echo "─────────────────────────────────────"

            if [[ "$blocked_count" -eq 0 ]]; then
                echo "  (no blocked items)"
            else
                _kb_jq_read "$board_file" '
                    .backlog[] | select(.status == "blocked") |
                    "  [\(.id)] \(.title)\n    Blocked by: \((.blockedBy // []) | join(", "))"
                ' -r
            fi
            echo "─────────────────────────────────────"
            ;;

        deps)
            # Show dependency tree
            local target_id="$1"

            if [[ -n "$target_id" ]]; then
                # Show deps for specific item
                local target_index
                target_index=$(_kb_resolve_selector "$board_file" "$target_id")
                if [[ "$target_index" == "-1" ]]; then
                    echo "Error: Item not found: $target_id"
                    return 1
                fi

                local actual_id item_title blockers dependents
                actual_id=$(_kb_jq_read "$board_file" ".backlog[$target_index].id // empty" -r)
                item_title=$(_kb_jq_read "$board_file" ".backlog[$target_index].title // empty" -r)
                blockers=$(_kb_jq_read "$board_file" ".backlog[$target_index].blockedBy // [] | join(\", \")" -r)

                # Find items blocked by this item
                dependents=$(_kb_jq_read "$board_file" '
                    [.backlog[] | select((.blockedBy // []) | any(. == $id))] | map(.id) | join(", ")
                ' --arg id "$actual_id" -r)

                echo "Dependency Tree for [$actual_id]: $item_title"
                echo "─────────────────────────────────────"
                if [[ -n "$blockers" ]]; then
                    echo "  Blocked by:"
                    for blocker in $(echo "$blockers" | tr ',' '\n'); do
                        local blocker_trim="${blocker## }"
                        blocker_trim="${blocker_trim%% }"
                        local blocker_title
                        blocker_title=$(_kb_jq_read "$board_file" '.backlog[] | select(.id == $id) | .title' --arg id "$blocker_trim" -r 2>/dev/null || echo "")
                        echo "    ↑ [$blocker_trim] $blocker_title"
                    done
                else
                    echo "  Blocked by: (none)"
                fi
                if [[ -n "$dependents" ]]; then
                    echo "  Blocks:"
                    for dep in $(echo "$dependents" | tr ',' '\n'); do
                        local dep_trim="${dep## }"
                        dep_trim="${dep_trim%% }"
                        local dep_title
                        dep_title=$(_kb_jq_read "$board_file" '.backlog[] | select(.id == $id) | .title' --arg id "$dep_trim" -r 2>/dev/null || echo "")
                        echo "    ↓ [$dep_trim] $dep_title"
                    done
                else
                    echo "  Blocks: (none)"
                fi
            else
                # Show all dependencies as a tree
                echo "Dependency Tree for ${team}:"
                echo "─────────────────────────────────────"

                # Items with no blockers that block others (roots)
                echo "Root items (no blockers, but blocking others):"
                _kb_jq_read "$board_file" '
                    .backlog[] |
                    select((.blockedBy // []) | length == 0) |
                    select(.id as $id | any(..; .blockedBy? // [] | any(. == $id))) |
                    "  [\(.id)] \(.title)"
                ' -r 2>/dev/null | head -20

                echo ""
                echo "Blocked items:"
                _kb_jq_read "$board_file" '
                    .backlog[] | select(.status == "blocked") |
                    "  [\(.id)] ← \((.blockedBy // []) | join(\", \"))"
                ' -r 2>/dev/null
                echo "─────────────────────────────────────"
            fi
            ;;

        # === CR Lifecycle Helpers (XACA-0291) ===
        show|info)
            # Display a single backlog item in detail, including CR lifecycle section when enabled.
            # INVARIANT: CR section is rendered if and only if crSupport.enabled=true AND cr_id is set.
            local selector="$1"
            if [[ -z "$selector" ]]; then
                echo "Usage: kb-backlog show <item-id>" >&2
                return 1
            fi

            local index
            index=$(_kb_resolve_selector "$board_file" "$selector")
            if [[ "$index" == "-1" ]]; then
                echo "Error: Item not found: $selector" >&2
                return 1
            fi

            local item_id item_title item_priority item_status item_desc
            local item_jira item_github item_tags item_due item_added item_updated
            item_id=$(_kb_jq_read "$board_file" ".backlog[$index].id // \"?\"" -r)
            item_title=$(_kb_jq_read "$board_file" ".backlog[$index].title // \"(no title)\"" -r)
            item_priority=$(_kb_jq_read "$board_file" ".backlog[$index].priority // \"medium\"" -r)
            item_status=$(_kb_jq_read "$board_file" ".backlog[$index].status // \"todo\"" -r)
            item_desc=$(_kb_jq_read "$board_file" ".backlog[$index].description // \"\"" -r)
            item_jira=$(_kb_jq_read "$board_file" ".backlog[$index].jiraId // \"\"" -r)
            item_github=$(_kb_jq_read "$board_file" ".backlog[$index].githubIssue // \"\"" -r)
            item_tags=$(_kb_jq_read "$board_file" ".backlog[$index].tags // [] | join(\", \")" -r)
            item_due=$(_kb_jq_read "$board_file" ".backlog[$index].dueDate // \"\"" -r)
            item_added=$(_kb_jq_read "$board_file" ".backlog[$index].addedAt // \"\"" -r)
            item_updated=$(_kb_jq_read "$board_file" ".backlog[$index].updatedAt // \"\"" -r)

            echo ""
            echo "╔═══════════════════════════════════════════════════════════╗"
            echo "║ [$item_id] $item_title"
            echo "╠═══════════════════════════════════════════════════════════╣"
            printf "║  Priority: %-10s  Status: %s\n" "${(U)item_priority}" "${(U)item_status}"
            [[ -n "$item_tags" ]]    && printf "║  Tags:     %s\n" "$item_tags"
            [[ -n "$item_jira" ]]    && printf "║  JIRA:     %s\n" "$item_jira"
            [[ -n "$item_github" ]]  && printf "║  GitHub:   %s\n" "$item_github"
            [[ -n "$item_due" ]]     && printf "║  Due:      %s\n" "$item_due"
            [[ -n "$item_added" ]]   && printf "║  Added:    %s\n" "$item_added"
            [[ -n "$item_updated" ]] && printf "║  Updated:  %s\n" "$item_updated"
            if [[ -n "$item_desc" ]]; then
                echo "╠═══════════════════════════════════════════════════════════╣"
                echo "║  $item_desc"
            fi
            echo "╚═══════════════════════════════════════════════════════════╝"

            # CR Lifecycle section — only rendered when crSupport.enabled=true AND cr_id is set.
            # When the flag is false, or cr_id is absent: render NOTHING (disabled-state parity invariant).
            local cr_enabled
            cr_enabled=$(_kb_jq_read "$board_file" '.teamConfig.crSupport.enabled // false' -r 2>/dev/null)
            if [[ "$cr_enabled" == "true" ]]; then
                local cr_id_val
                cr_id_val=$(_kb_jq_read "$board_file" ".backlog[$index].cr_id // \"\"" -r 2>/dev/null)
                if [[ -n "$cr_id_val" ]]; then
                    # Delegate to kb-cr show for consistent CR field rendering.
                    # kb-cr show will no-op if crSupport is disabled (double guard).
                    type kb-cr &>/dev/null && kb-cr show "$item_id"
                fi
            fi
            ;;

        *)
            echo "Usage: kb-backlog <command> [args...]"
            echo ""
            echo "Commands:"
            echo "  add \"task\" [pri] [\"desc\"] [jira] [os]  Add task with optional fields"
            echo "  list                               List all backlog items"
            echo "  show <id>                          Show detailed view of a single item"
            echo "  change <i> [\"title\"] [priority]   Update item title and/or priority"
            echo "  desc <i> [\"description\"]          Set/view/clear item description"
            echo "  jira <i> [JIRA-ID]                 Set/view/clear JIRA ticket ID"
            echo "  github <i> [issue-ref]             Set/view/clear GitHub issue"
            echo "  tag <i> [add|rm|clear] [tags...]   Manage tags (clickable in LCARS)"
            echo "  due <i> [YYYY-MM-DD]               Set/view/clear due date"
            echo "  remove <index>                     Remove item by index"
            echo "  unpick <index>                     Clear actively working flag"
            echo "  cleanup                            Clear orphaned items for current window"
            echo "  cleanup-all                        Clear ALL orphaned items"
            echo "  sub <cmd> [args...]                Manage subitems"
            echo ""
            echo "Dependency Commands:"
            echo "  block <id> <blocker-id>...         Mark item as blocked by another"
            echo "  unblock <id> [blocker-id]          Remove blocker(s) from item"
            echo "  blocked                            List all blocked items"
            echo "  deps [id]                          Show dependency tree"
            echo ""
            echo "Priority: low | med | high | crit | critical | block | blocked"
            echo "  - critical: Urgent issues requiring immediate attention"
            echo "  - blocked: Items waiting on external dependencies"
            echo ""
            echo "OS: iOS | Android | Firebase (platform-specific tasks)"
            echo ""
            echo "Issue Tracking:"
            echo "  JIRA:   ME-123, PROJ-456"
            echo "  GitHub: #123 (team default) or owner/repo#123 (explicit)"
            echo ""
            echo "Tags:"
            echo "  Tags appear as clickable pills in LCARS UI. Click to filter."
            echo "  kb-backlog tag 0 iOS refactor      # Set tags"
            echo "  kb-backlog tag 0 add testing       # Add tag"
            echo "  kb-backlog tag 0 rm testing        # Remove tag"
            echo ""
            echo "Examples:"
            echo "  kb-backlog add \"Fix login bug\" high"
            echo "  kb-backlog add \"Critical crash\" crit \"\" ME-123"
            echo "  kb-backlog add \"Update docs\" med \"Review API docs\""
            echo "  kb-backlog add \"iOS payment fix\" high \"\" ME-456 iOS"
            echo "  kb-backlog list"
            echo "  kb-backlog change 0 \"New title\" high"
            echo "  kb-backlog tag 0 iOS feature urgent"
            echo "  kb-backlog jira 0 ME-456"
            echo "  kb-backlog remove 0"
            return 1
            ;;
    esac
}

# Aliases for convenience
alias kb-backlog-list='kb-backlog list'
alias kb-backlog-remove='kb-backlog remove'

# Import external issues from JIRA, GitHub, Monday.com
kb-import() {
    local external_id="$1"
    shift

    # Default options
    local preview_only=false
    local skip_confirm=false
    local include_children=true
    local target_team=""
    local integration=""

    # Parse options
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --preview|-p)
                preview_only=true
                ;;
            --yes|-y)
                skip_confirm=true
                ;;
            --no-children)
                include_children=false
                ;;
            --team|-t)
                target_team="$2"
                shift
                ;;
            --integration|-i)
                integration="$2"
                shift
                ;;
            --help|-h)
                external_id=""
                break
                ;;
            *)
                echo "Unknown option: $1"
                external_id=""
                break
                ;;
        esac
        shift
    done

    # Show usage if no ID provided
    if [[ -z "$external_id" ]]; then
        echo "Usage: kb-import <external-id> [options]"
        echo ""
        echo "Import issues from external systems (JIRA, GitHub, Monday.com)"
        echo "into the kanban backlog with automatic ticket linking."
        echo ""
        echo "Arguments:"
        echo "  <external-id>  External ticket ID to import"
        echo "                 Examples: ME-123, gh:owner/repo#123, mon:1234567"
        echo ""
        echo "Options:"
        echo "  --preview, -p      Show preview only, don't import"
        echo "  --yes, -y          Skip confirmation prompt"
        echo "  --team, -t <team>  Target team (default: from context)"
        echo "  --integration, -i  Integration ID (default: auto-detect)"
        echo "  --no-children      Don't import subtasks/children"
        echo "  --help, -h         Show this help"
        echo ""
        echo "Provider Detection:"
        echo "  ME-123, MEM-456     → JIRA (PROJECT-NUMBER pattern)"
        echo "  gh:owner/repo#123   → GitHub"
        echo "  github:repo#123     → GitHub"
        echo "  mon:1234567890      → Monday.com"
        echo "  MON-1234567890      → Monday.com"
        echo ""
        echo "Examples:"
        echo "  kb-import ME-123                    # Import JIRA issue"
        echo "  kb-import ME-123 --preview          # Preview without importing"
        echo "  kb-import gh:lcars-ui#42            # Import GitHub issue"
        echo "  kb-import ME-123 --team iOS         # Import to iOS board"
        echo "  kb-import ME-123 --yes              # Import without confirmation"
        echo "  kb-import ME-123 --no-children      # Don't import subtasks"
        return 1
    fi

    # Detect team from context if not specified
    if [[ -z "$target_team" ]]; then
        local context
        context=$(_kb_detect_context 2>/dev/null || echo "academy:unknown")
        target_team="${context%%:*}"
    fi

    # Find the LCARS UI directory
    local lcars_ui_dir="${LCARS_UI_DIR:-${AITEAMFORGE_DIR}/lcars-ui}"

    # Check if the import script exists
    local import_script="$lcars_ui_dir/integrations/import_issue.py"
    if [[ ! -f "$import_script" ]]; then
        echo "Error: Import script not found: $import_script"
        echo "Make sure LCARS UI is installed correctly."
        return 1
    fi

    # Build command arguments
    local cmd_args=("--id" "$external_id" "--team" "$target_team")

    if [[ "$preview_only" == "true" ]]; then
        cmd_args+=("--preview")
    elif [[ "$skip_confirm" == "true" ]]; then
        cmd_args+=("--execute")
    fi

    if [[ "$include_children" == "false" ]]; then
        cmd_args+=("--no-children")
    fi

    if [[ -n "$integration" ]]; then
        cmd_args+=("--integration" "$integration")
    fi

    # Run the import script
    python3 "$import_script" "${cmd_args[@]}"
}

# Pick a task from backlog and mark it as active (simple assignment)
kb-pick() {
    _kb_ensure_jq || return 1

    local selector="$1"

    if [[ -z "$selector" ]]; then
        echo "Usage: kb-pick <id>"
        echo "Marks an item as actively being worked on."
        echo "Use 'kb-backlog list' to see available items"
        echo "Example: kb-pick XFRE-0001"
        echo ""
        echo "For full Claude Code launch with worktree setup, use: kb-run <id>"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Resolve selector to index
    local index
    index=$(_kb_resolve_selector "$board_file" "$selector")

    if [[ "$index" == "-1" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Read the item
    local item_json item_id title
    item_json=$(_kb_jq_read "$board_file" ".backlog[$index] // empty")
    item_id=$(echo "$item_json" | jq -r '.id // empty')
    title=$(echo "$item_json" | jq -r '.title // empty')

    if [[ -z "$item_id" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Check if item is blocked (XACA-0020)
    local item_status blocked_by
    item_status=$(echo "$item_json" | jq -r '.status // "todo"')
    blocked_by=$(echo "$item_json" | jq -r '(.blockedBy // []) | join(", ")')
    if [[ "$item_status" == "blocked" ]] || [[ -n "$blocked_by" ]]; then
        echo "─────────────────────────────────────"
        echo "⚠️  Cannot pick [$item_id]: Item is blocked"
        echo "   Blocked by: $blocked_by"
        echo "─────────────────────────────────────"
        echo "Complete the blocking items first, or use:"
        echo "  kb-backlog unblock $item_id"
        return 1
    fi

    # Mark item as actively being worked on
    local timestamp
    timestamp=$(_kb_get_timestamp)

    _kb_jq_update "$board_file" \
       '.backlog[$idx].activelyWorking = true |
        .backlog[$idx].status = "in_progress" |
        .backlog[$idx].workStartedAt = $ts |
        .backlog[$idx].startedAt //= $ts |
        .backlog[$idx].updatedAt = $ts |
        .lastUpdated = $ts' \
       --argjson idx "$index" \
       --arg ts "$timestamp"

    # XACA-0054: Sync to release manifests via LCARS server
    _kb_release_sync "$item_id"

    # Register window in activeWindows (required before _kb_set_working_on)
    _kb_update_window "coding" "$title"

    # Set as current working item
    _kb_set_working_on "$item_id" "DEV"

    echo "─────────────────────────────────────"
    echo "✓ Picked: [$item_id] $title"
    echo "  Status: in_progress (actively working)"
    echo "─────────────────────────────────────"
    echo ""
    echo "To launch Claude Code with this task: kb-run $item_id"
}

