# Reopen a completed/cancelled item for debugging
# Usage: _kb_reopen_item <board_file> <index> <item_id>
# Sets status back to in_progress, records previousStatus and reopenedAt
# Auto-adds debug subitems (diagnose, fix, testing, PR, QA, retrospective, sync)
# Returns 0 on success, 1 if item is not completed/cancelled
_kb_reopen_item() {
    local board_file="$1"
    local index="$2"
    local item_id="$3"

    # Read the item's current status
    local current_status
    current_status=$(_kb_jq_read "$board_file" ".backlog[$index].status // empty" -r)

    # Only reopen completed or cancelled items
    if [[ "$current_status" != "completed" ]] && [[ "$current_status" != "cancelled" ]]; then
        echo "Item [$item_id] is not completed or cancelled (status: $current_status) — no reopen needed"
        return 1
    fi

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Transition the item back to in_progress, preserving previous status
    _kb_jq_update "$board_file" '
        .backlog[$idx].status = "in_progress" |
        .backlog[$idx].activelyWorking = true |
        .backlog[$idx].workStartedAt = $ts |
        .backlog[$idx].reopenedAt = $ts |
        .backlog[$idx].previousStatus = $prev |
        del(.backlog[$idx].completedAt) |
        .lastUpdated = $ts
    ' --argjson idx "$index" \
      --arg ts "$timestamp" \
      --arg prev "$current_status"

    # Count existing subitems to determine starting number for debug subitems
    local existing_count
    existing_count=$(_kb_jq_read "$board_file" ".backlog[$index].subitems // [] | length" -r)
    local next_num=$((existing_count + 1))

    # The 7 standard debug subitems
    local debug_titles=(
        "[Debug] Diagnose root cause"
        "[Debug] Implement fix"
        "[Debug] Testing & validation"
        "[Debug] PR Creation & Test Handoff"
        "[Debug] QA Testing & Code Review"
        "[Debug] Retrospective and Knowledge Capture"
        "[Debug] Sync Local Develop Branch"
    )

    # Build a single jq filter that appends all 7 subitems atomically
    # Note: zsh arrays are 1-based, so we use (( i+1 )) to index into debug_titles
    local jq_filter='.backlog[$idx].subitems = ((.backlog[$idx].subitems // []) + ['
    local jq_args=(--argjson idx "$index" --arg ts "$timestamp")
    local num_titles=${#debug_titles[@]}
    local i sub_num sub_id
    for (( i = 0; i < num_titles; i++ )); do
        sub_num=$((next_num + i))
        sub_id=$(printf "%s-%03d" "$item_id" "$sub_num")
        if [[ $i -gt 0 ]]; then
            jq_filter+=','
        fi
        jq_filter+="{\"id\": \$sid$i, \"title\": \$stitle$i, \"status\": \"todo\", \"addedAt\": \$ts}"
        jq_args+=(--arg "sid$i" "$sub_id" --arg "stitle$i" "${debug_titles[$((i+1))]}")
    done
    jq_filter+=']) | .lastUpdated = $ts'

    _kb_jq_update "$board_file" "$jq_filter" "${jq_args[@]}"

    echo "✓ Reopened [$item_id] (was: $current_status → now: in_progress)"
    echo "✓ Added 7 debug subitems to [$item_id]"
    return 0
}

# Internal helper: Discover worktree for item when kanban .worktree field is null
# Uses the same naming convention as _kb_create_item_worktree: lowercase item ID
# Returns: worktree path on stdout if found, empty if not
# Usage: _kb_discover_worktree <item_id>
_kb_discover_worktree() {
    local item_id="$1"
    if [[ -z "$item_id" ]]; then
        return 1
    fi

    local worktree_name
    worktree_name=$(echo "$item_id" | tr '[:upper:]' '[:lower:]')

    # Strategy 1: Derive project_root the same way _kb_create_item_worktree does
    local git_root project_root
    git_root=$(git rev-parse --git-common-dir 2>/dev/null | xargs dirname)
    if [[ -z "$git_root" ]] || [[ "$git_root" == "." ]]; then
        git_root=$(git rev-parse --show-toplevel 2>/dev/null)
    fi

    if [[ -n "$git_root" ]]; then
        local git_root_name
        git_root_name=$(basename "$git_root")
        if [[ "$git_root_name" == "develop" ]] || [[ "$git_root_name" == "main" ]] || [[ "$git_root_name" == "master" ]] || [[ "$git_root_name" == "DEV" ]]; then
            project_root=$(dirname "$git_root")
        else
            project_root="$git_root"
        fi

        local candidate="${project_root}/worktrees/${worktree_name}"
        if [[ -d "$candidate" ]]; then
            echo "$candidate"
            return 0
        fi
    fi

    # Strategy 2: Check WT_DIR (worktree-helpers.sh environment)
    if [[ -n "$WT_DIR" ]]; then
        local wt_candidate="${WT_DIR}/${worktree_name}"
        if [[ -d "$wt_candidate" ]]; then
            echo "$wt_candidate"
            return 0
        fi
    fi

    # Strategy 3: Scan git worktree list for matching path
    if [[ -n "$git_root" ]]; then
        local git_match
        git_match=$(git worktree list --porcelain 2>/dev/null | grep "^worktree.*/${worktree_name}$" | head -1 | sed 's/^worktree //')
        if [[ -n "$git_match" ]] && [[ -d "$git_match" ]]; then
            echo "$git_match"
            return 0
        fi
    fi

    return 1
}

# Internal helper: Attempt to switch to an item's worktree with fallback discovery
# If item_worktree is set and valid, uses it directly.
# If not, runs _kb_discover_worktree and optionally backlinks to the kanban item.
# Sets item_worktree and item_worktree_branch in caller scope if discovered.
# Usage: _kb_switch_to_item_worktree <board_file> <index> <item_id>
# Returns 0 if switched, 1 if no worktree found (stays in current dir)
_kb_switch_to_item_worktree() {
    local board_file="$1"
    local index="$2"
    local item_id="$3"

    # item_worktree is set by _kb_display_item_box in the caller's scope
    if [[ -n "$item_worktree" ]] && [[ -d "$item_worktree" ]]; then
        # Verify the on-disk branch matches the kanban record before trusting the fast path
        local actual_branch
        actual_branch=$(git -C "$item_worktree" branch --show-current 2>/dev/null)
        if [[ -n "$item_worktree_branch" ]] && [[ -n "$actual_branch" ]] && [[ "$actual_branch" != "$item_worktree_branch" ]]; then
            echo "⚠️  Worktree branch mismatch: expected '$item_worktree_branch', found '$actual_branch'"
            echo "   Falling through to worktree discovery..."
        else
            echo "─────────────────────────────────────"
            echo "📁 Switching to item's worktree..."
            echo "   $item_worktree"
            echo "─────────────────────────────────────"
            cd "$item_worktree" || {
                echo "Error: Failed to cd into worktree: $item_worktree"
                return 1
            }
            local reset_rc=0
            _kb_reset_worktree || reset_rc=$?
            if [[ $reset_rc -eq 2 ]]; then
                echo "⛔ Worktree operation aborted by user." >&2
                return 1
            elif [[ $reset_rc -eq 1 ]]; then
                echo "⚠️  Worktree reset failed. Worktree may not be on latest code." >&2
            fi
            return 0
        fi
    fi

    # Fallback: discover worktree from filesystem
    local discovered
    discovered=$(_kb_discover_worktree "$item_id")

    if [[ -n "$discovered" ]] && [[ -d "$discovered" ]]; then
        echo "─────────────────────────────────────"
        echo "📁 Discovered worktree (not linked in kanban)..."
        echo "   $discovered"
        echo "─────────────────────────────────────"
        cd "$discovered" || {
            echo "Error: Failed to cd into worktree: $discovered"
            return 1
        }

        # Backlink to kanban item for future fast lookups
        local wt_branch wt_timestamp
        wt_branch=$(git branch --show-current 2>/dev/null || echo "")
        wt_timestamp=$(_kb_get_timestamp)
        _kb_jq_update "$board_file" \
            '.backlog[$idx].worktree = $wt |
             .backlog[$idx].worktreeBranch = $wtb |
             .backlog[$idx].worktreeLinkedAt = $ts |
             .lastUpdated = $ts' \
            --argjson idx "$index" \
            --arg wt "$discovered" \
            --arg wtb "$wt_branch" \
            --arg ts "$wt_timestamp"
        echo "   ✓ Linked worktree to [$item_id] for future use"

        # Update caller's scope
        item_worktree="$discovered"
        item_worktree_branch="$wt_branch"

        local reset_rc=0
        _kb_reset_worktree || reset_rc=$?
        if [[ $reset_rc -eq 2 ]]; then
            echo "⛔ Worktree operation aborted by user." >&2
            return 1
        elif [[ $reset_rc -eq 1 ]]; then
            echo "⚠️  Worktree reset failed. Worktree may not be on latest code." >&2
        fi
        return 0
    fi

    echo "─────────────────────────────────────"
    echo "⚠️  No worktree found for this item."
    echo "   Staying in current directory: $(pwd)"
    echo "─────────────────────────────────────"
    return 1
}

# Internal helper: Display a formatted item details box
# Usage: _kb_display_item_box <item_json> <box_title> [flags]
# Flags (comma-separated): worktree, branch, subitem_detail
# - worktree: show the worktree path line
# - branch: show the branch name line
# - subitem_detail: show individual subitems with status icons (vs count-only summary)
# Sets these variables in the caller's scope for downstream use:
#   item_id, title, description, jira_id, github_issue, priority, item_status,
#   due_date, tags, subitem_count, item_worktree, item_worktree_branch
_kb_display_item_box() {
    local _box_item_json="$1"
    local _box_title="$2"
    local _box_flags=",${3:-},"  # Wrap with commas for delimiter-safe matching

    # Extract item details — these are set in the CALLER's scope (no local)
    # shellcheck disable=SC2034
    item_id=$(echo "$_box_item_json" | jq -r '.id // empty')
    title=$(echo "$_box_item_json" | jq -r '.title // empty')
    description=$(echo "$_box_item_json" | jq -r '.description // empty')
    jira_id=$(echo "$_box_item_json" | jq -r '.jiraId // empty')
    github_issue=$(echo "$_box_item_json" | jq -r '.githubIssue // empty')
    priority=$(echo "$_box_item_json" | jq -r '.priority // "medium"')
    item_status=$(echo "$_box_item_json" | jq -r '.status // "todo"')
    due_date=$(echo "$_box_item_json" | jq -r '.dueDate // empty')
    tags=$(echo "$_box_item_json" | jq -r '(.tags // []) | join(", ")')

    # Get subitem count
    subitem_count=$(echo "$_box_item_json" | jq '.subitems // [] | length')

    # Get worktree info
    item_worktree=$(echo "$_box_item_json" | jq -r '.worktree // empty')
    item_worktree_branch=$(echo "$_box_item_json" | jq -r '.worktreeBranch // empty')

    # Render the box
    echo ""
    echo "╔══════════════════════════════════════════════════════════════════╗"
    printf "║                     %-45s║\n" "$_box_title"
    echo "╠══════════════════════════════════════════════════════════════════╣"
    echo "║"
    echo "║  ID:       $item_id"
    echo "║  Title:    $title"
    echo "║"
    echo "║  Priority: $(printf '%-12s' "$priority" | tr '[:lower:]' '[:upper:]')  Status: $item_status"
    if [[ -n "$due_date" ]]; then
        echo "║  Due Date: $due_date"
    fi
    if [[ -n "$tags" ]]; then
        echo "║  Tags:     $tags"
    fi
    echo "║"

    # Show description if present
    if [[ -n "$description" ]]; then
        echo "║  Description:"
        echo "$description" | fold -w 60 -s | while IFS= read -r line; do
            echo "║    $line"
        done
        echo "║"
    fi

    # Show external links
    if [[ -n "$jira_id" ]] || [[ -n "$github_issue" ]]; then
        echo "║  Links:"
        [[ -n "$jira_id" ]] && echo "║    JIRA:   $jira_id"
        [[ -n "$github_issue" ]] && echo "║    GitHub: $github_issue"
        echo "║"
    fi

    # Conditionally show worktree path
    if [[ "$_box_flags" == *",worktree,"* ]] && [[ -n "$item_worktree" ]]; then
        echo "║  Worktree: $item_worktree"
    fi

    # Conditionally show branch name
    if [[ "$_box_flags" == *",branch,"* ]] && [[ -n "$item_worktree_branch" ]]; then
        echo "║  Branch:   $item_worktree_branch"
    fi

    # Add separator if worktree or branch was shown (or always for consistency)
    echo "║"

    # Show subitems
    if [[ "$subitem_count" -gt 0 ]]; then
        local completed_count in_progress_count todo_count cancelled_count
        completed_count=$(echo "$_box_item_json" | jq '[.subitems[] | select(.status == "completed")] | length')
        in_progress_count=$(echo "$_box_item_json" | jq '[.subitems[] | select(.status == "in_progress")] | length')
        todo_count=$(echo "$_box_item_json" | jq '[.subitems[] | select(.status == "todo")] | length')
        cancelled_count=$(echo "$_box_item_json" | jq '[.subitems[] | select(.status == "cancelled")] | length')

        if [[ "$cancelled_count" -gt 0 ]]; then
            echo "║  Subitems: $subitem_count total ($completed_count done, $cancelled_count cancelled, $in_progress_count in progress, $todo_count todo)"
        else
            echo "║  Subitems: $subitem_count total ($completed_count done, $in_progress_count in progress, $todo_count todo)"
        fi
        echo "║"

        # Show individual subitem rows with status icons if requested
        if [[ "$_box_flags" == *",subitem_detail,"* ]]; then
            echo "$_box_item_json" | jq -r '.subitems[] | "║    [\(.status | if . == "completed" then "✓" elif . == "cancelled" then "✗" elif . == "in_progress" then "●" else "○" end)] \(.id): \(.title)"'
            echo "║"
        fi
    fi

    echo "╚══════════════════════════════════════════════════════════════════╝"
    echo ""
}

# Internal helper: Build the standard PR review prompt text
# Usage: _kb_build_review_prompt <item_id> <title> <description> <item_worktree_branch>
# Echoes the complete review prompt to stdout
_kb_build_review_prompt() {
    local item_id="$1"
    local title="$2"
    local description="$3"
    local item_worktree_branch="$4"

    local prompt="You are reviewing a Pull Request for kanban item [$item_id].\n\n"
    prompt+="## Task Being Reviewed\n"
    prompt+="**Kanban Item:** $item_id\n"
    prompt+="**Title:** $title\n"

    if [[ -n "$description" ]]; then
        prompt+="\n**Description:** $description\n"
    fi

    if [[ -n "$item_worktree_branch" ]]; then
        prompt+="\n**Branch:** $item_worktree_branch\n"
    fi

    prompt+="\n## Your Mission\n"
    prompt+="1. **Find the open PR** for this item. Try these approaches:\n"
    prompt+="   - Run: \`gh pr list --head $item_worktree_branch\` (if branch is known)\n"
    prompt+="   - Run: \`gh pr list --search \"$item_id\" --state open\`\n"
    prompt+="   - Run: \`gh pr list --state open\` and look for a matching PR\n"
    prompt+="\n2. **Review the PR** using the standard checklist:\n"
    prompt+="   - **Security**: No hardcoded secrets, no injection vulnerabilities, proper input validation\n"
    prompt+="   - **Architecture**: Follows existing patterns, appropriate separation of concerns, no unnecessary coupling\n"
    prompt+="   - **Code Quality**: No force unwraps without justification, proper error handling, no commented-out code\n"
    prompt+="   - **Performance**: Weak self in closures, no memory leaks, efficient algorithms\n"
    prompt+="   - **Testing**: Changes are testable, edge cases considered, error paths handled\n"
    prompt+="\n3. **Check the diff thoroughly:**\n"
    prompt+="   \`\`\`bash\n"
    prompt+="   gh pr diff <number>\n"
    prompt+="   \`\`\`\n"
    prompt+="\n4. **Submit your review** using gh-bot-review (NOT gh pr review):\n"
    prompt+="   \`\`\`bash\n"
    prompt+="   # To approve:\n"
    prompt+="   gh-bot-review --pr <number> --event APPROVE --body \"LGTM - <summary of why it's good>\"\n"
    prompt+="\n"
    prompt+="   # To request changes (blocking issues only):\n"
    prompt+="   gh-bot-review --pr <number> --event REQUEST_CHANGES --body \"<specific blocking feedback>\"\n"
    prompt+="\n"
    prompt+="   # For detailed reviews, write to a temp file first:\n"
    prompt+="   # Write feedback to /tmp/review-<number>.md, then:\n"
    prompt+="   gh-bot-review --pr <number> --event REQUEST_CHANGES --body-file /tmp/review-<number>.md\n"
    prompt+="   \`\`\`\n"
    prompt+="\n5. **Capture suggestions as merge-blocking kanban subitems** (do NOT leave them only as PR comments):\n"
    prompt+="   \`\`\`bash\n"
    prompt+="   source ${AITEAMFORGE_DIR}/kanban-helpers.sh\n"
    prompt+="   # One subitem per suggestion — title MUST start with [Review]\n"
    prompt+="   kb-backlog sub add $item_id \"[Review] <actionable suggestion> (PR #<number>)\"\n"
    prompt+="   \`\`\`\n"
    prompt+="   These subitems BLOCK merge. The creating agent must address each one and push fixes before merging.\n"
    prompt+="   Each gets its own subitem for independent tracking and must be resolved before PR merge.\n"
    prompt+="\n6. **After submitting REQUEST_CHANGES**, enter the reviewer monitoring loop:\n"
    prompt+="   \`\`\`bash\n"
    prompt+="   # Record current HEAD SHA after submitting REQUEST_CHANGES\n"
    prompt+="   LAST_SHA=\$(gh pr view <number> --json headRefOid --jq '.headRefOid')\n"
    prompt+="   while true; do\n"
    prompt+="     STATE=\$(gh pr view <number> --json state --jq '.state')\n"
    prompt+="     [ \"\$STATE\" = \"CLOSED\" ] || [ \"\$STATE\" = \"MERGED\" ] && echo \"PR \$STATE — exiting.\" && break\n"
    prompt+="     CURRENT_SHA=\$(gh pr view <number> --json headRefOid --jq '.headRefOid')\n"
    prompt+="     if [ \"\$CURRENT_SHA\" != \"\$LAST_SHA\" ]; then\n"
    prompt+="       sleep 30  # Stabilization: wait for rapid pushes to settle\n"
    prompt+="       LAST_SHA=\$(gh pr view <number> --json headRefOid --jq '.headRefOid')\n"
    prompt+="       gh pr checkout <number> && gh pr diff <number>\n"
    prompt+="       # Re-review: (1) verify each requested change was addressed,\n"
    prompt+="       # (2) check new code in fix commits for new issues.\n"
    prompt+="       # Then: gh-bot-review --pr <number> --event APPROVE or REQUEST_CHANGES\n"
    prompt+="     fi\n"
    prompt+="     sleep 60\n"
    prompt+="   done\n"
    prompt+="   \`\`\`\n"
    prompt+="   Re-review scope: verify blocking issues are resolved, check new code, skip unchanged code.\n"
    prompt+="\n## CRITICAL Rules\n"
    prompt+="- **USE gh-bot-review** for submitting reviews, NOT \`gh pr review\` (same-account restriction)\n"
    prompt+="- **DO NOT MERGE** the PR — the creating agent's monitoring loop handles merge after bot approval\n"
    prompt+="- **Blocking issues** go in REQUEST_CHANGES — must be fixed before approval\n"
    prompt+="- **[Review] subitems BLOCK MERGE** — add as kanban subitems (NOT PR comments); creating agent MUST resolve ALL [Review] subitems before merge\n"
    prompt+="- **After REQUEST_CHANGES** — enter the reviewer monitoring loop (step 6 above)\n"
    prompt+="- Be specific about what needs to change and why\n"
    prompt+="- Provide code examples when suggesting alternatives\n"

    echo -e "$prompt"
}

# Review a PR for a kanban item by switching to its worktree
# Usage: kb-run-review <id>
# Like kb-run but launches Claude Code with a PR review prompt instead of an implementation prompt
kb-run-review() {
    _kb_ensure_jq || return 1

    local selector="$1"

    if [[ -z "$selector" ]]; then
        echo "Usage: kb-run-review <id>"
        echo "Switches to item's worktree and launches Claude Code to review the related PR."
        echo "Use 'kb-backlog list' to see available items"
        echo "Example: kb-run-review XFRE-0001"
        echo ""
        echo "To review without switching worktree, use: kb-work-review <id>"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Resolve selector to index
    local index
    index=$(_kb_resolve_selector "$board_file" "$selector")

    if [[ "$index" == "-1" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Read the full backlog item
    local item_json
    item_json=$(_kb_jq_read "$board_file" ".backlog[$index] // empty")

    if [[ -z "$item_json" ]] || [[ "$item_json" == "null" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Extract and display item details for review confirmation
    local item_id title description jira_id github_issue priority item_status due_date tags
    local subitem_count item_worktree item_worktree_branch
    _kb_display_item_box "$item_json" "PR REVIEW REQUEST" "worktree,branch"

    # Confirmation prompt
    local confirm
    printf "Start reviewing this item's PR? [Y/n]: "
    read -r confirm

    if [[ "$confirm" =~ ^[Nn]$ ]]; then
        echo "Cancelled. Review not started."
        return 0
    fi

    echo ""

    # Switch to the item's worktree if we're not already in it
    if ! _kb_is_correct_worktree "$item_worktree" "$item_worktree_branch"; then
        _kb_switch_to_item_worktree "$board_file" "$index" "$item_id"
    fi

    # Build the review prompt using shared helper
    local prompt
    prompt=$(_kb_build_review_prompt "$item_id" "$title" "$description" "$item_worktree_branch")

    echo "Launching Claude Code for PR review of [$item_id]: $title"
    echo "─────────────────────────────────────"

    # Update window status
    kb-plan "Review: $title"
    _kb_set_working_on "$item_id" "REVIEW"

    # Launch cc with the review prompt
    echo "$prompt" | cc
}

# Review a PR for a kanban item in the current directory (no worktree switch)
# Usage: kb-work-review <id>
# Like kb-work but launches Claude Code with a PR review prompt instead of an implementation prompt
kb-work-review() {
    _kb_ensure_jq || return 1

