    prompt+="- **DO NOT MERGE** the PR — the creating agent's monitoring loop handles merge after bot approval\n"
    prompt+="- **Blocking failures** go in REQUEST_CHANGES — must be fixed before approval\n"
    prompt+="- **[Test] subitems BLOCK MERGE** — add as kanban subitems (NOT PR comments); creating agent MUST resolve ALL [Test] subitems before merge\n"
    prompt+="- **After REQUEST_CHANGES** — enter the tester monitoring loop (step 6 above)\n"
    prompt+="- Be specific about what failed, how to reproduce it, and what the expected behavior is\n"
    prompt+="- Provide steps to reproduce for any failures you report\n"

    echo -e "$prompt"
}

# QA test a PR for a kanban item by switching to its worktree
# Usage: kb-run-test <id>
# Like kb-run-review but launches Claude Code with a QA test prompt instead of a review prompt
kb-run-test() {
    _kb_ensure_jq || return 1

    local selector="$1"

    if [[ -z "$selector" ]]; then
        echo "Usage: kb-run-test <id>"
        echo "Switches to item's worktree and launches Claude Code to QA test the related PR."
        echo "Use 'kb-backlog list' to see available items"
        echo "Example: kb-run-test XFRE-0001"
        echo ""
        echo "To test without switching worktree, use: kb-work-test <id>"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Resolve selector to index
    local index
    index=$(_kb_resolve_selector "$board_file" "$selector")

    if [[ "$index" == "-1" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Read the full backlog item
    local item_json
    item_json=$(_kb_jq_read "$board_file" ".backlog[$index] // empty")

    if [[ -z "$item_json" ]] || [[ "$item_json" == "null" ]]; then
        echo "Error: Item not found: $selector"
        return 1
    fi

    # Extract and display item details for test confirmation
    local item_id title description jira_id github_issue priority item_status due_date tags
    local subitem_count item_worktree item_worktree_branch
    _kb_display_item_box "$item_json" "PR TEST REQUEST" "worktree,branch"

    # Confirmation prompt
    local confirm
    printf "Start QA testing this item's PR? [Y/n]: "
    read -r confirm

    if [[ "$confirm" =~ ^[Nn]$ ]]; then
        echo "Cancelled. Test not started."
        return 0
    fi

    echo ""

    # Switch to the item's worktree if we're not already in it
    if ! _kb_is_correct_worktree "$item_worktree" "$item_worktree_branch"; then
        _kb_switch_to_item_worktree "$board_file" "$index" "$item_id"
    fi

    # Build the test prompt using shared helper
    local prompt
    prompt=$(_kb_build_test_prompt "$item_id" "$title" "$description" "$item_worktree_branch")

    echo "Launching Claude Code for PR QA testing of [$item_id]: $title"
    echo "─────────────────────────────────────"

    # Update window status
    kb-plan "Test: $title"
    _kb_set_working_on "$item_id" "TEST"

    # Launch cc with the test prompt
    echo "$prompt" | cc
}

