# ============================================================================
# Todo List Helpers
# Lightweight one-shot items stored in the board JSON todos array.
# These do not become kanban backlog entries — just quick reminders.
# ============================================================================

# Add a new todo item
# Usage: kb-todo-add "text" [priority] [required-by-date]
#   priority defaults to "medium"
#   required-by-date is optional ISO date string (e.g. 2026-03-01)
kb-todo-add() {
    _kb_ensure_jq || return 1

    local text="$1"
    local priority="${2:-medium}"
    local required_by="${3:-}"

    if [[ -z "$text" ]]; then
        echo "Usage: kb-todo-add \"text\" [priority] [required-by-date]"
        echo "Priority: low | medium | high | critical (default: medium)"
        echo "required-by-date: optional ISO date string (e.g. 2026-03-01)"
        return 1
    fi

    # Normalize priority shortcuts
    [[ "$priority" == "med" ]] && priority="medium"
    [[ "$priority" == "crit" ]] && priority="critical"

    # Validate priority
    local valid_priorities=("low" "medium" "high" "critical")
    if [[ ! " ${valid_priorities[*]} " =~ " ${priority} " ]]; then
        echo "Error: Invalid priority '$priority'"
        echo "Valid priorities: ${valid_priorities[*]}"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    local timestamp todo_id
    timestamp=$(_kb_get_timestamp)
    todo_id="todo-$(date +%s)-$(printf '%04d' $((RANDOM % 10000)))"

    # Build jq filter — initialize todos array if it doesn't exist, then append
    # Use single filter with $requiredBy arg; pass "___NULL___" sentinel when unset
    local jq_filter='
        if .todos == null then .todos = [] else . end |
        .todos += [{
            "id": $id,
            "text": $text,
            "priority": $priority,
            "requiredBy": (if $requiredBy == "___NULL___" then null else $requiredBy end),
            "status": "todo",
            "createdAt": $timestamp,
            "completedAt": null
        }] |
        .lastUpdated = $timestamp
    '
    _kb_jq_update "$board_file" "$jq_filter" \
        --arg id "$todo_id" \
        --arg text "$text" \
        --arg priority "$priority" \
        --arg requiredBy "${required_by:-___NULL___}" \
        --arg timestamp "$timestamp"

    echo "✓ Added todo [$todo_id]: $text [$priority]"
    [[ -n "$required_by" ]] && echo "  Required by: $required_by"
}

# Toggle todo completion status
# Usage: kb-todo-complete <todo-id>
#   todo -> completed (sets completedAt)
#   completed -> todo (clears completedAt)
kb-todo-complete() {
    _kb_ensure_jq || return 1

    local todo_id="$1"

    if [[ -z "$todo_id" ]]; then
        echo "Usage: kb-todo-complete <todo-id>"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Check if the todo exists and get current status
    local current_status current_text
    current_status=$(_kb_jq_read "$board_file" \
        'if .todos == null then empty else (.todos[] | select(.id == $id) | .status) end' \
        -r --arg id "$todo_id")
    current_text=$(_kb_jq_read "$board_file" \
        'if .todos == null then empty else (.todos[] | select(.id == $id) | .text) end' \
        -r --arg id "$todo_id")

    if [[ -z "$current_status" ]]; then
        echo "Error: Todo not found: $todo_id"
        return 1
    fi

    local timestamp
    timestamp=$(_kb_get_timestamp)

    if [[ "$current_status" == "todo" ]]; then
        # Mark as completed
        _kb_jq_update "$board_file" \
            '(.todos[] | select(.id == $id)) |= . + {"status": "completed", "completedAt": $timestamp} | .lastUpdated = $timestamp' \
            --arg id "$todo_id" \
            --arg timestamp "$timestamp"
        echo "✓ Completed [$todo_id]: $current_text"
    else
        # Toggle back to todo
        _kb_jq_update "$board_file" \
            '(.todos[] | select(.id == $id)) |= . + {"status": "todo", "completedAt": null} | .lastUpdated = $timestamp' \
            --arg id "$todo_id" \
            --arg timestamp "$timestamp"
        echo "✓ Reopened [$todo_id]: $current_text"
    fi
}

# Update fields on an existing todo item
# Usage: kb-todo-update <todo-id> [--text "new text"] [--priority low|medium|high|critical] [--required-by date]
kb-todo-update() {
    _kb_ensure_jq || return 1

    local todo_id="$1"
    shift

    if [[ -z "$todo_id" ]]; then
        echo "Usage: kb-todo-update <todo-id> [--text \"new text\"] [--priority low|medium|high|critical] [--required-by date]"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Check if todo exists
    local current_text
    current_text=$(_kb_jq_read "$board_file" \
        'if .todos == null then empty else (.todos[] | select(.id == $id) | .text) end' \
        -r --arg id "$todo_id")

    if [[ -z "$current_text" ]]; then
        echo "Error: Todo not found: $todo_id"
        return 1
    fi

    # Parse flags
    local new_text="" new_priority="" new_required_by="" clear_required_by=0
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --text)
                new_text="$2"
                shift 2
                ;;
            --priority)
                new_priority="$2"
                shift 2
                ;;
            --required-by)
                new_required_by="$2"
                shift 2
                ;;
            --clear-required-by)
                clear_required_by=1
                shift
                ;;
            *)
                echo "Error: Unknown option '$1'"
                echo "Usage: kb-todo-update <todo-id> [--text \"new text\"] [--priority low|medium|high|critical] [--required-by date]"
                return 1
                ;;
        esac
    done

    if [[ -z "$new_text" && -z "$new_priority" && -z "$new_required_by" && "$clear_required_by" -eq 0 ]]; then
        echo "Error: No fields specified to update"
        echo "Usage: kb-todo-update <todo-id> [--text \"new text\"] [--priority low|medium|high|critical] [--required-by date]"
        return 1
    fi

    # Validate priority if provided
    if [[ -n "$new_priority" ]]; then
        [[ "$new_priority" == "med" ]] && new_priority="medium"
        [[ "$new_priority" == "crit" ]] && new_priority="critical"
        local valid_priorities=("low" "medium" "high" "critical")
        if [[ ! " ${valid_priorities[*]} " =~ " ${new_priority} " ]]; then
            echo "Error: Invalid priority '$new_priority'"
            echo "Valid priorities: ${valid_priorities[*]}"
            return 1
        fi
    fi

    local timestamp
    timestamp=$(_kb_get_timestamp)

    # Build jq filter incrementally — apply only the fields that were provided
    local jq_filter='(.todos[] | select(.id == $id)) |= .'
    local jq_args=(--arg id "$todo_id" --arg timestamp "$timestamp")

    if [[ -n "$new_text" ]]; then
        jq_filter+=' + {"text": $newText}'
        jq_args+=(--arg newText "$new_text")
    fi

    if [[ -n "$new_priority" ]]; then
        jq_filter+=' + {"priority": $newPriority}'
        jq_args+=(--arg newPriority "$new_priority")
    fi

    if [[ -n "$new_required_by" ]]; then
        jq_filter+=' + {"requiredBy": $newRequiredBy}'
        jq_args+=(--arg newRequiredBy "$new_required_by")
    elif [[ "$clear_required_by" -eq 1 ]]; then
        jq_filter+=' + {"requiredBy": null}'
    fi

    jq_filter+=' | .lastUpdated = $timestamp'

    _kb_jq_update "$board_file" "$jq_filter" "${jq_args[@]}"

    echo "✓ Updated todo [$todo_id]"
    [[ -n "$new_text" ]] && echo "  Text: $new_text"
    [[ -n "$new_priority" ]] && echo "  Priority: $new_priority"
    [[ -n "$new_required_by" ]] && echo "  Required by: $new_required_by"
    [[ "$clear_required_by" -eq 1 ]] && echo "  Required by: cleared"
}

# Delete a todo item entirely
# Usage: kb-todo-delete <todo-id>
kb-todo-delete() {
    _kb_ensure_jq || return 1

    local todo_id="$1"

    if [[ -z "$todo_id" ]]; then
        echo "Usage: kb-todo-delete <todo-id>"
        return 1
    fi

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Check if todo exists and get its text for confirmation message
    local current_text
    current_text=$(_kb_jq_read "$board_file" \
        'if .todos == null then empty else (.todos[] | select(.id == $id) | .text) end' \
        -r --arg id "$todo_id")

    if [[ -z "$current_text" ]]; then
        echo "Error: Todo not found: $todo_id"
        return 1
    fi

    local timestamp
    timestamp=$(_kb_get_timestamp)

    _kb_jq_update "$board_file" \
        'if .todos == null then . else .todos |= map(select(.id != $id)) end | .lastUpdated = $timestamp' \
        --arg id "$todo_id" \
        --arg timestamp "$timestamp"

    echo "✓ Deleted todo [$todo_id]: $current_text"
}

# List todo items
# Usage: kb-todo-list [--all|--completed|--todo]
#   Default: shows items with status "todo"
#   --completed: shows completed items
#   --all: shows everything
kb-todo-list() {
    _kb_ensure_jq || return 1

    local filter_mode="todo"

    case "${1:-}" in
        --all)      filter_mode="all" ;;
        --completed) filter_mode="completed" ;;
        --todo)     filter_mode="todo" ;;
        "")         filter_mode="todo" ;;
        *)
            echo "Usage: kb-todo-list [--all|--completed|--todo]"
            echo "  (default: shows pending todos)"
            return 1
            ;;
    esac

    local context team board_file
    context=$(_kb_detect_context)
    team="${context%%:*}"
    board_file=$(_kb_get_board_file "$team")

    if [[ ! -f "$board_file" ]]; then
        echo "Error: No kanban board found for team '$team'"
        return 1
    fi

    # Build jq filter based on mode
    local jq_filter
    case "$filter_mode" in
        all)
            jq_filter='if .todos == null then [] else .todos end'
            ;;
        completed)
            jq_filter='if .todos == null then [] else [.todos[] | select(.status == "completed")] end'
            ;;
        todo)
            jq_filter='if .todos == null then [] else [.todos[] | select(.status == "todo")] end'
            ;;
    esac

    local count
    count=$(_kb_jq_read "$board_file" "${jq_filter} | length")

    # Header
    case "$filter_mode" in
        all)       echo "Todos for ${team}: ($count items — all)" ;;
        completed) echo "Todos for ${team}: ($count completed)" ;;
        todo)      echo "Todos for ${team}: ($count pending)" ;;
    esac
    echo "─────────────────────────────────────"

    if [[ "$count" -eq 0 ]]; then
        echo "  (empty)"
    else
        # Print each item with priority indicator and optional required-by
        _kb_jq_read "$board_file" \
            "${jq_filter}[] |
            (if .priority == \"critical\" then \"[!!!]\"
             elif .priority == \"high\"     then \"[!! ]\"
             elif .priority == \"medium\"   then \"[!  ]\"
             else                               \"[   ]\"
             end) as \$pri |
            (if .status == \"completed\" then \"[DONE]\" else \"[TODO]\" end) as \$sta |
            (if .requiredBy != null then \" (by: \" + .requiredBy + \")\" else \"\" end) as \$req |
            \"  \($sta) \($pri) \(.text)\($req)  [\(.id)]\"" \
            -r
    fi

    echo "─────────────────────────────────────"
}

